export default "    if not isinstance(template_data, dict):\\n            continue\\n        declared_tweaks = {\\n            tweak_name: tweak_value\\n            for tweak_name, tweak_value in node_tweaks.items()\\n            if isinstance(template_data.get(tweak_name), dict)\\n        }\\n        if declared_tweaks:\\n            ParameterHandler(vertex, storage_service=None).process_runtime_params(declared_tweaks)\\n\\n    for vertex, node_tweaks in pending:\\n        apply_tweaks_on_vertex(\\n            vertex,\\n            node_tweaks,\\n            policy=policy,\\n            flow_declares_allowlist=flow_declares_allowlist,\\n        )\\n\\n    return graph\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/processing/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a6d5f60076e1a0f9266793bb0572130a8e7c8c167fbb53ae2b9f55950450b185\",\"content\":\"import json\\nfrom typing import Any\\n\\nfrom json_repair import repair_json\\n\\n\\ndef validate_and_repair_json(json_str: str | dict) -> dict[str, Any] | str:\\n    \\\"\\\"\\\"Validates a JSON string and attempts to repair it if invalid.\\n\\n    Args:\\n        json_str (str): The JSON string to validate/repair\\n\\n    Returns:\\n        Union[Dict[str, Any], str]: The parsed JSON dict if valid/repairable,\\n        otherwise returns the original string\\n    \\\"\\\"\\\"\\n    if not isinstance(json_str, str):\\n        return json_str\\n    try:\\n        # If invalid, attempt repair\\n        repaired = repair_json(json_str)\\n        return json.loads(repaired)\\n    except (json.JSONDecodeError, ImportError):\\n        # Return original if repair fails or module not found\\n        return json_str\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/run/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b9b8f62a95eed947ecd01a0822c48755e93076ed721815982ffc85d7a868a393\",\"content\":\"\\\"\\\"\\\"Run module for executing Langflow graphs.\\\"\\\"\\\"\\n\\nfrom lfx.run.base import RunError, run_flow\\n\\n__all__ = [\\\"RunError\\\", \\\"run_flow\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/run/_defaults.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"45b822b5b3b48842b6227f8e58a436289abc0e95d50de678ce8c2e19ebe267d2\",\"content\":\"\\\"\\\"\\\"Shared helpers for applying run-time defaults to a Graph.\\n\\nThe CLI's ``lfx run`` (``run_flow``) and ``lfx serve``/``execute_graph_with_capture``\\nboth need to:\\n\\n1. Reject empty/whitespace-only ``session_id`` / ``user_id`` (so a typo or\\n   empty env var doesn't silently produce a random session and break Memory\\n   continuity).\\n2. Auto-generate a UUID when neither is supplied (so component prechecks and\\n   ``astore_message`` validation don't fail).\\n3. Propagate ``session_id`` to ``Memory``/``MessageHistory`` vertices the way\\n   ``langflow.api.utils.flow_utils.build_graph_from_data`` does \u2014 preserving\\n   any value already pinned in the flow JSON.\\n4. Resolve ``fallback_to_env_vars`` from settings (mirrors the langflow API\\n   path in ``processing.process.run_graph_internal``).\\n\\nBoth call sites used to inline these steps; consolidating them here prevents\\nbehavior drift between ``lfx run`` and ``lfx serve``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport uuid\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.deps import get_settings_service\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.graph.base import Graph\\n\\n\\ndef validate_provided_id(name: str, value: str | None) -> None:\\n    \\\"\\\"\\\"Reject empty/whitespace strings while allowing None (which means \\\"auto-generate\\\").\\n\\n    Empty strings reach this code via shell quirks (``--session-id \\\"\\\"``), env-var\\n    expansion that resolved to empty, or callers that defaulted a missing arg to\\n    ``\\\"\\\"`` instead of ``None``. Treating them the same as ``None`` would silently\\n    fall through to UUID generation \u2014 and the user would only learn their session\\n    didn't carry over by noticing Memory looks empty on the next run.\\n    \\\"\\\"\\\"\\n    if value is None:\\n        return\\n    if not isinstance(value, str) or not value.strip():\\n        msg = (\\n            f\\\"{name} was provided but is empty or whitespace. \\\"\\n            f\\\"Pass a non-empty value, or omit {name} to auto-generate one.\\\"\\n        )\\n        raise ValueError(msg)\\n\\n\\ndef apply_run_defaults(\\n    graph: Graph,\\n    *,\\n    session_id: str | None,\\n    user_id: str | None,\\n    overwrite_user_id: bool = True,\\n) -> tuple[str, str]:\\n    \\\"\\\"\\\"Apply session_id, user_id, and vertex-propagation defaults to *graph*.\\n\\n    Validates non-None values are non-empty (raises ``ValueError`` otherwise).\\n    Auto-generates UUID hex strings for any value left as ``None``. Sets the\\n    resolved values on the graph and propagates ``session_id`` to vertices in\\n    ``graph.has_session_id_vertices`` that don't already have a hardcoded value.\\n\\n    Args:\\n        graph: The graph to mutate.\\n        session_id: Caller-supplied session_id. ``None`` -> auto-generate.\\n        user_id: Caller-supplied user_id. ``None`` -> auto-generate.\\n        overwrite_user_id: When False, an existing ``graph.user_id`` is preserved\\n            (matches the prior ``execute_graph_with_capture`` behavior). When True,\\n            the resolved user_id always wins (matches the prior ``run_flow``\\n            behavior, which intentionally re-stamps the graph).\\n\\n    Returns:\\n        ``(session_id, user_id)`` \u2014 the values actually applied to the graph.\\n    \\\"\\\"\\\"\\n    validate_provided_id(\\\"session_id\\\", session_id)\\n    validate_provided_id(\\\"user_id\\\", user_id)\\n\\n    if not user_id:\\n        user_id = uuid.uuid4().hex\\n        logger.debug(\\n            f\\\"No user_id provided; auto-generated {user_id} to satisfy component prechecks. \\\"\\n            \\\"lfx's variable service is env-backed, so user_id is not used for variable scoping.\\\"\\n        )\\n    if overwrite_user_id or not getattr(graph, \\\"user_id\\\", None):\\n        graph.user_id = user_id\\n    else:\\n        # Caller-supplied None plus an existing graph.user_id: preserve the existing.\\n        user_id = graph.user_id\\n\\n    if not session_id:\\n        session_id = uuid.uuid4().hex\\n        # info, not warning: this is the normal case for one-shot CLI runs and\\n        # would otherwise spam stderr on every invocation. Visible at -v.\\n        logger.info(\\n            f\\\"No session_id provided; auto-generated {session_id}. \\\"\\n            \\\"Memory/MessageHistory components will not see prior conversation state across runs.\\\"\\n        )\\n    graph.session_id = session_id\\n\\n    # Mirror langflow's build_graph_from_data: only write when raw_params has no\\n    # session_id (hardcoded values pinned in the flow JSON win). graph.async_start\\n    # bypasses the equivalent loop in Graph._run, so without this Memory components\\n    # would read \\\"\\\" from their input field even when --session-id is set.\\n    for vertex_id in graph.has_session_id_vertices:\\n        vertex = graph.get_vertex(vertex_id)\\n        if vertex is None:\\n            continue\\n        if not vertex.raw_params.get(\\\"session_id\\\"):\\n            vertex.update_raw_params({\\\"session_id\\\": session_id}, overwrite=True)\\n\\n    return session_id, user_id\\n\\n\\ndef resolve_fallback_to_env_vars() -> bool:\\n    \\\"\\\"\\\"Read ``fallback_to_env_var`` from settings, defaulting to True if the service is missing.\\n\\n    Mirrors the langflow API path (``processing.process.run_graph_internal``):\\n    when a ``load_from_db`` variable misses (e.g. the ceremonial UUID has no\\n    Variable row), fall through to ``os.environ`` instead of failing the build.\\n    A missing settings_service is unusual \u2014 log a warning so the user can debug.\\n    \\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n    if settings_service is None:\\n        logger.warning(\\n            \\\"settings_service is unavailable; defaulting fallback_to_env_vars=True. \\\"\\n            \\\"If load_from_db variables are misbehaving, verify the settings service initialized.\\\"\\n        )\\n        return True\\n    return bool(settings_service.settings.fallback_to_env_var)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/run/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c056089351cfd10b59cd4ffe39613661f54aadc25860aaad2920d9ad6f9217a5\",\"content\":\"\\\"\\\"\\\"Core run functionality for executing Langflow graphs.\\\"\\\"\\\"\\n\\nimport json\\nimport re\\nimport sys\\nimport time\\nfrom io import StringIO\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.cli.script_loader import (\\n    extract_structured_result,\\n    extract_text_from_result,\\n    find_graph_variable,\\n    load_graph_from_script,\\n)\\nfrom lfx.cli.validation import validate_global_variables_for_env\\nfrom lfx.execution import aget_default_coordinator\\nfrom lfx.log.logger import logger\\nfrom lfx.run._defaults import apply_run_defaults, resolve_fallback_to_env_vars, validate_provided_id\\nfrom lfx.schema.schema import InputValueRequest\\nfrom lfx.utils.flow_envelope import split_flow_envelope\\n\\nif TYPE_CHECKING:\\n    from lfx.events.event_manager import EventManager\\n\\n# Verbosity level constants\\nVERBOSITY_DETAILED = 2\\nVERBOSITY_FULL = 3\\n\\n\\nclass RunError(Exception):\\n    \\\"\\\"\\\"Exception raised when run execution fails.\\\"\\\"\\\"\\n\\n    def __init__(self, message: str, exception: Exception | None = None):\\n        super().__init__(message)\\n        self.original_exception = exception\\n\\n\\ndef _preflight_dependencies(\\n    *,\\n    flow_dict: dict | None,\\n    script_path: Path | None,\\n    verbose: bool,\\n) -> None:\\n    \\\"\\\"\\\"Fail fast when a JSON flow needs packages that are not installed.\\n\\n    Runs before the graph load (and the component imports it triggers) so a\\n    missing provider SDK surfaces as a single actionable ``pip install ...``\\n    message instead of a deep ``ModuleNotFoundError`` mid-build.\\n\\n    Best-effort and conservative: it analyzes only JSON flows (``.py`` scripts\\n    declare deps via PEP 723 inline metadata, handled elsewhere), and any\\n    analysis error is logged and skipped so a runnable flow is never blocked by\\n    the check itself. Disabled with ``--no-check-dependencies``.\\n\\n    Raises:\\n        RunError: when one or more required packages are positively missing.\\n    \\\"\\\"\\\"\\n    # Normalize to the ``{\\\"data\\\": {\\\"nodes\\\": [...]}}`` shape the analyzer expects.\\n    if flow_dict is not None:\\n        analysis_flow: dict = {\\\"data\\\": flow_dict}\\n    elif script_path is not None and script_path.suffix.lower() == \\\".json\\\":\\n        try:\\n            raw = json.loads(script_path.read_text(encoding=\\\"utf-8\\\"))\\n            _, inner = split_flow_envelope(raw)\\n        except (OSError, json.JSONDecodeError, TypeError):\\n            # Unreadable/invalid JSON: let the graph loader report it precisely.\\n            return\\n        analysis_flow = {\\\"data\\\": inner}\\n    else:\\n        # .py script or no JSON source: nothing to analyze here.\\n        return\\n\\n    try:\\n        from lfx.utils.flow_requirements import find_missing_dependencies\\n\\n        missing = find_missing_dependencies(analysis_flow)\\n    except Exception as e:  # noqa: BLE001 - never let analysis crash a runnable flow\\n        logger.debug(f\\\"Dependency preflight skipped (analysis error: {e})\\\")\\n        return\\n\\n    if missing:\\n        from lfx.utils.flow_requirements import format_missing_dependencies_error\\n\\n        error_msg = format_missing_dependencies_error(missing)\\n        output_error(error_msg, verbose=verbose)\\n        raise RunError(error_msg, None)\\n\\n\\ndef output_error(error_message: str, *, verbose: bool, exception: Exception | None = None) -> dict:\\n    \\\"\\\"\\\"Create error response dict and optionally print to stderr when verbose.\\\"\\\"\\\"\\n    if verbose:\\n        sys.stderr.write(f\\\"{error_message}\\\\n\\\")\\n\\n    error_response = {\\n        \\\"success\\\": False,\\n        \\\"type\\\": \\\"error\\\",\\n    }\\n\\n    # Add clean exception data if available\\n    if exception:\\n        error_response[\\\"exception_type\\\"] = type(exception).__name__\\n        error_response[\\\"exception_message\\\"] = str(exception)\\n    else:\\n        error_response[\\\"exception_message\\\"] = error_message\\n\\n    return error_response\\n\\n\\ndef _materialize_flow_dict(\\n    *,\\n    flow_json: str | None,\\n    stdin: bool,\\n    script_path: Path | None,\\n    upgrade_flow: str | None,\\n    verbosity: int,\\n    verbose: bool,\\n) -> dict | None:\\n    \\\"\\\"\\\"Parse inline JSON / stdin / (for --upgrade-flow) a .json file into a flow dict.\\n\\n    Returns the unwrapped inner graph (any outer ``{\\\"data\\\": ...}`` envelope removed), or None\\n    when there is no JSON source to materialize. A plain script path without ``--upgrade-flow``\\n    is loaded later by file path, not here.\\n\\n    Raises:\\n        RunError: on malformed JSON, a non-object payload, an unreadable upgrade target, a\\n            non-JSON ``--upgrade-flow`` target, or a missing JSON source when ``--upgrade-flow``\\n            was requested.\\n    \\\"\\\"\\\"\\n    flow_dict: dict | None = None\\n\\n    if flow_json is not None:\\n        if verbosity > 0:\\n            sys.stderr.write(\\\"Processing inline JSON content...\\\\n\\\")\\n        try:\\n            raw = json.loads(flow_json)\\n            _, flow_dict = split_flow_envelope(raw)\\n            if verbosity > 0:\\n                sys.stderr.write(\\\"JSON content is valid\\\\n\\\")\\n        except json.JSONDecodeError as e:\\n            error_msg = f\\\"Invalid JSON content: {e}\\\"\\n            output_error(error_msg, verbose=verbose)\\n            raise RunError(error_msg, e) from e\\n        except Exception as e:\\n            error_msg = f\\\"Error processing JSON content: {e}\\\"\\n            output_error(error_msg, verbose=verbose)\\n            raise RunError(error_msg, e) from e\\n    elif stdin:\\n        if verbosity > 0:\\n            sys.stderr.write(\\\"Reading JSON content from stdin...\\\\n\\\")\\n        try:\\n            stdin_content = sys.stdin.read().strip()\\n            if not stdin_content:\\n                error_msg = \\\"No content received from stdin\\\"\\n                output_error(error_msg, verbose=verbose)\\n                raise RunError(error_msg, None)\\n            raw = json.loads(stdin_content)\\n            _, flow_dict = split_flow_envelope(raw)\\n            if verbosity > 0:\\n                sys.stderr.write(\\\"JSON content from stdin is valid\\\\n\\\")\\n        except json.JSONDecodeError as e:\\n            error_msg = f\\\"Invalid JSON content from stdin: {e}\\\"\\n            output_error(error_msg, verbose=verbose)\\n            raise RunError(error_msg, e) from e\\n        except Exception as e:\\n            error_msg = f\\\"Error reading from stdin: {e}\\\"\\n            output_error(error_msg, verbose=verbose)\\n            raise RunError(error_msg, e) from e\\n\\n    # For JSON file paths with --upgrade-flow: read into flow_dict so the gate fires and any\\n    # applied upgrades are used when loading the graph (instead of the original file).\\n    # .py scripts are not JSON flows and cannot be upgraded.\\n    if upgrade_flow and flow_dict is None and script_path is not None:\\n        if script_path.suffix.lower() == \\\".json\\\":\\n            try:\\n                raw = json.loads(script_path.read_text(encoding=\\\"utf-8\\\"))\\n                _, flow_dict = split_flow_envelope(raw)\\n            except Exception as e:\\n                error_msg = f\\\"--upgrade-flow: could not read flow file '{script_path}': {e}\\\"\\n                output_error(error_msg, verbose=verbose)\\n                raise RunError(error_msg, e) from e\\n        else:\\n            error_msg = f\\\"--upgrade-flow is only supported for JSON flows, not '{script_path.suffix}' files.\\\"\\n            output_error(error_msg, verbose=verbose)\\n            raise RunError(error_msg, None)\\n\\n    # Fail fast if upgrade_flow was requested but we still have nothing to check.\\n    # This guards against unexpected code paths that leave flow_dict None.\\n    if upgrade_flow and flow_dict is None:\\n        error_msg = \\\"--upgrade-flow requires a JSON flow source (--flow-json, --stdin, or a .json file path).\\\"\\n        output_error(error_msg, verbose=verbose)\\n        raise RunError(error_msg, None)\\n\\n    return flow_dict\\n\\n\\nasync def run_flow(\\n    script_path: Path | None = None,\\n    input_value: str | None = None,\\n    input_value_option: str | None = None,\\n    output_format: str = \\\"json\\\",\\n    flow_json: str | None = None,\\n    *,\\n    stdin: bool = False,\\n    check_variables: bool = True,\\n    check_dependencies: bool = True,\\n    verbose: bool = False,\\n    verbose_detailed: bool = False,\\n    verbose_full: bool = False,\\n    timing: bool = False,\\n    global_variables: dict[str, str] | None = None,\\n    user_id: str | None = None,\\n    session_id: str | None = None,\\n    event_manager: \\\"EventManager | None\\\" = None,\\n    upgrade_flow: str | None = None,\\n    human_input: bool | None = None,\\n) -> dict:\\n    \\\"\\\"\\\"Execute a Langflow graph script or JSON flow and return the result.\\n\\n    This function analyzes and executes either a Python script containing a Langflow graph,\\n    a JSON flow file, inline JSON, or JSON from stdin, returning the result as a dict.\\n\\n    Args:\\n        script_path: Path to the Python script (.py) or JSON flow (.json) containing a graph\\n        input_value: Input value to pass to the graph (positional argument)\\n        input_value_option: Input value to pass to the graph (alternative option)\\n        output_format: Format for output (json, text, message, or result)\\n        flow_json: Inline JSON flow content as a string\\n        stdin: Read JSON flow content from stdin\\n        check_variables: Check global variables for environment compatibility\\n        check_dependencies: Preflight the flow's required packages and fail fast\\n            with install guidance when any are missing (JSON flows only)\\n        verbose: Show basic progress information\\n        verbose_detailed: Show detailed progress and debug information\\n        verbose_full: Show full debugging output including component logs\\n        timing: Include detailed timing information in output\\n        global_variables: Dict of global variables to inject into the graph context\\n        user_id: Optional user ID for tracking purposes\\n        session_id: Optional session ID for memory isolation\\n        event_manager: Optional EventManager for streaming token events\\n        upgrade_flow: Component compatibility mode. ``'check'`` refuses to run if any\\n            component is outdated or blocked. ``'safe'`` auto-applies safe upgrades and\\n            aborts on breaking or blocked components.\\n        human_input: Interactive human-in-the-loop. ``None`` (default) auto-enables it\\n            when the flow has a pausing node (e.g. HumanInput) and stdin is a TTY;\\n            ``True``/``False`` force it on/off. When active the flow runs via the\\n            pause/resume driver, prompting at the terminal for each decision.\\n\\n    Returns:\\n        dict: Result data containing the execution results, logs, and optionally timing info\\n\\n    Raises:\\n        RunError: If execution fails at any stage\\n    \\\"\\\"\\\"\\n    # Configure logger based on verbosity level\\n    from lfx.log.logger import configure\\n\\n    if verbose_full:\\n        configure(log_level=\\\"DEBUG\\\", output_file=sys.stderr)\\n        verbosity = 3\\n    elif verbose_detailed:\\n        configure(log_level=\\\"DEBUG\\\", output_file=sys.stderr)\\n        verbosity = 2\\n    elif verbose:\\n        configure(log_level=\\\"INFO\\\", output_file=sys.stderr)\\n        verbosity = 1\\n    else:\\n        configure(log_level=\\\"CRITICAL\\\", output_file=sys.stderr)\\n        verbosity = 0\\n\\n    # Validate caller-supplied IDs up-front so users get a clear error before any\\n    # graph loading work happens. None means \\\"auto-generate later\\\"; \\\"\\\" / whitespace\\n    # is rejected so a typo or empty env var doesn't silently produce a fresh\\n    # session and break Memory continuity.\\n    try:\\n        validate_provided_id(\\\"session_id\\\", session_id)\\n        validate_provided_id(\\\"user_id\\\", user_id)\\n    except ValueError as e:\\n        error_msg = str(e)\\n        output_error(error_msg, verbose=verbose, exception=e)\\n        raise RunError(error_msg, e) from e\\n\\n    start_time = time.monotonic() if timing else None\\n\\n    # Use either positional input_value or --input-value option\\n    final_input_value = input_value or input_value_option\\n\\n    # Validate input sources - exactly one must be provided\\n    input_sources = [script_path is not None, flow_json is not None, bool(stdin)]\\n    if sum(input_sources) != 1:\\n        if sum(input_sources) == 0:\\n            error_msg = \\\"No input source provided. Must provide either script_path, --flow-json, or --stdin\\\"\\n        else:\\n            error_msg = (\\n                \\\"Multiple input sources provided. Cannot use script_path, --flow-json, and \\\"\\n                \\\"--stdin together. Choose exactly one.\\\"\\n            )\\n        output_error(error_msg, verbose=verbose)\\n        raise RunError(error_msg, None)\\n\\n    # Materialize a flow dict from inline JSON / stdin / (for --upgrade-flow) a .json file.\\n    # Plain script paths without --upgrade-flow stay None and are loaded by path below.\\n    flow_dict = _materialize_flow_dict(\\n        flow_json=flow_json,\\n        stdin=stdin,\\n        script_path=script_path,\\n        upgrade_flow=upgrade_flow,\\n        verbosity=verbosity,\\n        verbose=verbose,\\n    )\\n\\n    # --- upgrade compatibility gate (shared with `lfx serve`) ---\\n    if upgrade_flow and flow_dict is not None:\\n        from lfx.upgrade.cli_gate import UpgradeFlowError, apply_upgrade_gate\\n\\n        # Pass no registry: the gate loads the bundled component index (the same source\\n        # `lfx upgrade` uses). component_cache.all_types_dict is empty here because it is\\n        # populated lazily after services start, so using it would block every component.\\n        try:\\n            flow_dict, applied = apply_upgrade_gate(flow_dict, mode=upgrade_flow)\\n        except UpgradeFlowError as e:\\n            output_error(str(e), verbose=verbose)\\n            raise RunError(str(e), e) from e\\n        if applied and verbose:\\n            sys.stderr.write(f\\\"Applied {applied} safe component upgrade(s).\\\\n\\\")\\n    # --- end upgrade gate ---\\n\\n    # --- dependency preflight (fail fast before component imports) ---\\n    if check_dependencies:\\n        _preflight_dependencies(flow_dict=flow_dict, script_path=script_path, verbose=verbose)\\n    # --- end dependency preflight ---\\n\\n    try:\\n        # Handle direct JSON dict (from stdin or --flow-json)\\n        if flow_dict is not None:\\n            if verbosity > 0:\\n                sys.stderr.write(\\\"Loading graph from JSON content...\\\\n\\\")\\n            from lfx.load import aload_flow_from_json\\n\\n            graph = await aload_flow_from_json({\\\"data\\\": flow_dict}, disable_logs=not verbose)\\n        # Handle file path\\n        elif script_path is not None:\\n            if not script_path.exists():\\n                error_msg = f\\\"File '{script_path}' does not exist.\\\"\\n                raise ValueError(error_msg)\\n            if not script_path.is_file():\\n                error_msg = f\\\"'{script_path}' is not a file.\\\"\\n                raise ValueError(error_msg)\\n            file_extension = script_path.suffix.lower()\\n            if file_extension not in [\\\".py\\\", \\\".json\\\"]:\\n                error_msg = f\\\"'{script_path}' must be a .py or .json file.\\\"\\n                raise ValueError(error_msg)\\n            file_type = \\\"Python script\\\" if file_extension == \\\".py\\\" else \\\"JSON flow\\\"\\n            if verbosity > 0:\\n                sys.stderr.write(f\\\"Analyzing {file_type}: {script_path}\\\\n\\\")\\n            if file_extension == \\\".py\\\":\\n                graph_info = find_graph_variable(script_path)\\n                if not graph_info:\\n                    error_msg = (\\n                        \\\"No 'graph' variable found in the script. \\\"\\n                        \\\"Expected to find an assignment like: graph = Graph(...)\\\"\\n                    )\\n                    raise ValueError(error_msg)\\n                if verbosity > 0:\\n                    sys.stderr.write(f\\\"Found 'graph' variable at line {graph_info['line_number']}\\\\n\\\")\\n                    sys.stderr.write(f\\\"Type: {graph_info['type']}\\\\n\\\")\\n                    sys.stderr.write(f\\\"Source: {graph_info['source_line']}\\\\n\\\")\\n                    sys.stderr.write(\\\"Loading and executing script...\\\\n\\\")\\n                graph = await load_graph_from_script(script_path)\\n            else:  # .json file\\n                if verbosity > 0:\\n                    sys.stderr.write(\\\"Valid JSON flow file detected\\\\n\\\")\\n                    sys.stderr.write(\\\"Loading and executing JSON flow\\\\n\\\")\\n                from lfx.load import aload_flow_from_json\\n\\n                graph = await aload_flow_from_json(script_path, disable_logs=not verbose)\\n        else:\\n            error_msg = \\\"No input source provided\\\"\\n            raise ValueError(error_msg)\\n\\n        # Apply session_id, user_id, and Memory-vertex propagation defaults. Both\\n        # are auto-generated when not supplied so component prechecks (custom_component\\n        # .get_variable for user_id) and astore_message validation (for session_id)\\n        # don't fail. See lfx.run._defaults.apply_run_defaults for the full rationale.\\n        session_id, user_id = apply_run_defaults(graph, session_id=session_id, user_id=user_id)\\n        if verbosity > 0:\\n            logger.info(f\\\"Set graph user_id: {user_id}\\\")\\n            logger.info(f\\\"Set graph session_id: {session_id}\\\")\\n\\n        # Inject global variables into graph context\\n        if global_variables:\\n            if \\\"request_variables\\\" not in graph.context:\\n                graph.context[\\\"request_variables\\\"] = {}\\n            graph.context[\\\"request_variables\\\"].update(global_variables)\\n            if verbosity > 0:\\n                # Log keys only to avoid leaking sensitive data\\n                logger.info(f\\\"Injected global variables: {list(global_variables.keys())}\\\")\\n\\n    except Exception as e:\\n        error_type = type(e).__name__\\n        logger.error(f\\\"Graph loading failed with {error_type}\\\")\\n\\n        if verbosity > 0:\\n            # Try to identify common error patterns\\n            if \\\"ModuleNotFoundError\\\" in str(e) or \\\"No module named\\\" in str(e):\\n                logger.info(\\\"This appears to be a missing dependency issue\\\")\\n                if \\\"langchain\\\" in str(e).lower():\\n                    match = re.search(r\\\"langchain_(.*)\\\", str(e).lower())\\n                    if match:\\n                        module_name = match.group(1)\\n                        logger.info(\\n                            f\\\"Missing LangChain dependency detected. Try: pip install langchain-{module_name}\\\",\\n                        )\\n            elif \\\"ImportError\\\" in str(e):\\n                logger.info(\\\"This appears to be an import issue - check component dependencies\\\")\\n            elif \\\"AttributeError\\\" in str(e):\\n                logger.info(\\\"This appears to be a component configuration issue\\\")\\n\\n            # Show full traceback in debug mode\\n            logger.exception(\\\"Failed to load graph.\\\")\\n\\n        error_msg = f\\\"Failed to load graph. {e}\\\"\\n        output_error(error_msg, verbose=verbose, exception=e)\\n        raise RunError(error_msg, e) from e\\n\\n    inputs = InputValueRequest(input_value=final_input_value) if final_input_value else None\\n\\n    # Mark end of loading phase if timing\\n    load_end_time = time.monotonic() if timing else None\\n\\n    if verbosity > 0:\\n        sys.stderr.write(\\\"Preparing graph for execution...\\\\n\\\")\\n    try:\\n        # Add detailed preparation steps\\n        if verbosity > 0:\\n            logger.debug(f\\\"Graph contains {len(graph.vertices)} vertices\\\")\\n            logger.debug(f\\\"Graph contains {len(graph.edges)} edges\\\")\\n\\n            # Show component types being used\\n            component_types = set()\\n            for vertex in graph.vertices:\\n                if hasattr(vertex, \\\"display_name\\\"):\\n                    component_types.add(vertex.display_name)\\n            logger.debug(f\\\"Component types in graph: {', '.join(sorted(component_types))}\\\")\\n\\n        graph.prepare()\\n        logger.info(\\\"Graph preparation completed\\\")\\n\\n        # Validate global variables for environment compatibility\\n        if check_variables:\\n            logger.info(\\\"Validating global variables...\\\")\\n            validation_errors = validate_global_variables_for_env(graph)\\n            if validation_errors:\\n                error_details = \\\"Global variable validation failed: \\\" + \\\"; \\\".join(validation_errors)\\n                logger.info(f\\\"Variable validation failed: {len(validation_errors)} errors\\\")\\n                for error in validation_errors:\\n                    logger.debug(f\\\"Validation error: {error}\\\")\\n                output_error(error_details, verbose=verbose)\\n                raise RunError(error_details, None)\\n            logger.info(\\\"Global variable validation passed\\\")\\n        else:\\n            logger.info(\\\"Global variable validation skipped\\\")\\n    except RunError:\\n        raise\\n    except Exception as e:\\n        error_type = type(e).__name__\\n        logger.info(f\\\"Graph preparation failed with {error_type}\\\")\\n\\n        if verbosity > 0:\\n            logger.debug(f\\\"Preparation error: {e!s}\\\")\\n            logger.exception(\\\"Failed to prepare graph - full traceback:\\\")\\n\\n        error_msg = f\\\"Failed to prepare graph: {e}\\\"\\n        output_error(error_msg, verbose=verbose, exception=e)\\n        raise RunError(error_msg, e) from e\\n\\n    logger.info(\\\"Executing graph...\\\")\\n    execution_start_time = time.monotonic() if timing else None\\n    if verbose:\\n        logger.debug(\\\"Setting up execution environment\\\")\\n        if inputs:\\n            logger.debug(f\\\"Input provided: {inputs.input_value}\\\")\\n        else:\\n            logger.debug(\\\"No input provided\\\")\\n\\n    captured_stdout = StringIO()\\n    captured_stderr = StringIO()\\n    original_stdout = sys.stdout\\n    original_stderr = sys.stderr\\n\\n    # Track component timing if requested\\n    component_timings = [] if timing else None\\n    execution_step_start = execution_start_time if timing else None\\n    result_count = 0\\n\\n    try:\\n        sys.stdout = captured_stdout\\n        # Don't capture stderr at high verbosity levels to avoid duplication with direct logging\\n        if verbosity < VERBOSITY_FULL:\\n            sys.stderr = captured_stderr\\n        results = []\\n\\n        logger.info(\\\"Starting graph execution...\\\", level=\\\"DEBUG\\\")\\n\\n        # See lfx.run._defaults.resolve_fallback_to_env_vars for why this flag is\\n        # plumbed through (mirrors langflow's API path so load_from_db variables\\n        # fall through to os.environ on miss instead of erroring the build).\\n        fallback_to_env_vars = resolve_fallback_to_env_vars()\\n\\n        from lfx.run.hitl import flow_has_pausing_node\\n\\n        # None auto-enables only for a known pausing node on an interactive terminal.\\n        hitl_active = human_input if human_input is not None else (flow_has_pausing_node(graph) and sys.stdin.isatty())\\n        if hitl_active:\\n            from lfx.run.hitl import run_graph_with_human_input, terminal_decision_provider\\n\\n            # Restore real stderr so the interactive prompt reaches the terminal.\\n            sys.stderr = original_stderr\\n            try:\\n                results = await run_graph_with_human_input(\\n                    graph,\\n                    decision_provider=terminal_decision_provider,\\n                    input_value=final_input_value,\\n                    event_manager=event_manager,\\n                    fallback_to_env_vars=fallback_to_env_vars,\\n                )\\n            finally:\\n                if verbosity < VERBOSITY_FULL:\\n                    sys.stderr = captured_stderr\\n            result_count = len(results)\\n        else:\\n            if flow_has_pausing_node(graph):\\n                # Real stderr: the captured one is swallowed at default verbosity, and this must be loud.\\n                original_stderr.write(\\n                    \\\"Warning: this flow has a Human Input (pausing) node, but the run is \\\"\\n                    \\\"non-interactive, so it will NOT pause for a decision. CLI HITL is \\\"\\n                    \\\"interactive-session only (in-memory, no durable resume). Run in a \\\"\\n                    \\\"terminal or pass --human-input to enable the interactive prompts.\\\\n\\\"\\n                )\\n            coordinator = await aget_default_coordinator()\\n            # See Graph.async_start: the span belongs to this coroutine, not the generator.\\n            with graph.flow_execution_span():\\n                async for result in coordinator.stream(\\n                    graph,\\n                    initial_inputs=inputs,\\n                    event_manager=event_manager,\\n                    fallback_to_env_vars=fallback_to_env_vars,\\n                    open_flow_span=False,\\n                ):\\n                    result_count += 1\\n                    if verbosity > 0:\\n                        logger.debug(f\\\"Processing result #{result_count}\\\")\\n                        if hasattr(result, \\\"vertex\\\") and hasattr(result.vertex, \\\"display_name\\\"):\\n                            logger.debug(f\\\"Component: {result.vertex.display_name}\\\")\\n                    if timing:\\n                        step_end_time = time.monotonic()\\n                        step_duration = step_end_time - execution_step_start\\n\\n                        # Extract component information\\n                        if hasattr(result, \\\"vertex\\\"):\\n                            component_name = getattr(result.vertex, \\\"display_name\\\", \\\"Unknown\\\")\\n                            component_id = getattr(result.vertex, \\\"id\\\", \\\"Unknown\\\")\\n                            component_timings.append(\\n                                {\\n                                    \\\"component\\\": component_name,\\n                                    \\\"component_id\\\": component_id,\\n                                    \\\"duration\\\": step_duration,\\n                                    \\\"cumulative_time\\\": step_end_time - execution_start_time,\\n                                }\\n                            )\\n\\n                        execution_step_start = step_end_time\\n\\n                    results.append(result)\\n\\n        logger.info(f\\\"Graph execution completed. Processed {result_count} results\\\")\\n\\n    except Exception as e:\\n        error_type = type(e).__name__\\n        logger.info(f\\\"Graph execution failed with {error_type}\\\")\\n\\n        if verbosity >= VERBOSITY_DETAILED:  # Only show details at -vv and above\\n            logger.debug(f\\\"Failed after processing {result_count} results\\\")\\n\\n        # Only show component output at maximum verbosity (-vvv)\\n        if verbosity >= VERBOSITY_FULL:\\n            # Capture any output that was generated before the error\\n            # Only show captured stdout since stderr logging is already shown directly in verbose mode\\n            captured_content = captured_stdout.getvalue()\\n            if captured_content.strip():\\n                # Check if captured content contains the same error that will be displayed at the end\\n                error_text = str(e)\\n                captured_lines = captured_content.strip().split(\\\"\\\\n\\\")\\n\\n                # Filter out lines that are duplicates of the final error message\\n                unique_lines = [\\n                    line\\n                    for line in captured_lines\\n                    if not any(\\n                        error_part.strip() in line for error_part in error_text.split(\\\"\\\\n\\\") if error_part.strip()\\n                    )\\n                ]\\n\\n                if unique_lines:\\n                    logger.info(\\\"Component output before error:\\\", level=\\\"DEBUG\\\")\\n                    for line in unique_lines:\\n                        # Log each line directly using the logger to avoid nested formatting\\n                        if verbosity > 0:\\n                            # Remove any existing timestamp prefix to avoid duplication\\n                            clean_line = line\\n                            if \\\"] \\\" in line and line.startswith(\\\"2025-\\\"):\\n                                # Extract just the log message after the timestamp and level\\n                                parts = line.split(\\\"] \\\", 1)\\n                                if len(parts) > 1:\\n                                    clean_line = parts[1]\\n                            logger.debug(clean_line)\\n\\n            # Provide context about common execution errors\\n            if \\\"list can't be used in 'await' expression\\\" in str(e):\\n                logger.info(\\\"This appears to be an async/await mismatch in a component\\\")\\n                logger.info(\\\"Check that async methods are properly awaited\\\")\\n            elif \\\"AttributeError\\\" in error_type and \\\"NoneType\\\" in str(e):\\n                logger.info(\\\"This appears to be a null reference error\\\")\\n                logger.info(\\\"A component may be receiving unexpected None values\\\")\\n            elif \\\"ConnectionError\\\" in str(e) or \\\"TimeoutError\\\" in str(e):\\n                logger.info(\\\"This appears to be a network connectivity issue\\\")\\n                logger.info(\\\"Check API keys and network connectivity\\\")\\n\\n            logger.exception(\\\"Failed to execute graph - full traceback:\\\")\\n\\n        sys.stdout = original_stdout\\n        sys.stderr = original_stderr\\n        error_msg = f\\\"Failed to execute graph: {e}\\\"\\n        output_error(error_msg, verbose=verbosity > 0, exception=e)\\n        raise RunError(error_msg, e) from e\\n    finally:\\n        sys.stdout = original_stdout\\n        sys.stderr = original_stderr\\n\\n    execution_end_time = time.monotonic() if timing else None\\n\\n    captured_logs = captured_stdout.getvalue() + captured_stderr.getvalue()\\n\\n    # Create timing metadata if requested\\n    timing_metadata = None\\n    if timing:\\n        load_duration = load_end_time - start_time\\n        execution_duration = execution_end_time - execution_start_time\\n        total_duration = execution_end_time - start_time\\n\\n        timing_metadata = {\\n            \\\"load_time\\\": round(load_duration, 3),\\n            \\\"execution_time\\\": round(execution_duration, 3),\\n            \\\"total_time\\\": round(total_duration, 3),\\n            \\\"component_timings\\\": [\\n                {\\n                    \\\"component\\\": ct[\\\"component\\\"],\\n                    \\\"component_id\\\": ct[\\\"component_id\\\"],\\n                    \\\"duration\\\": round(ct[\\\"duration\\\"], 3),\\n                    \\\"cumulative_time\\\": round(ct[\\\"cumulative_time\\\"], 3),\\n                }\\n                for ct in component_timings\\n            ],\\n        }\\n\\n    # Build result based on output format\\n    if output_format == \\\"json\\\":\\n        result_data = extract_structured_result(results)\\n        result_data[\\\"logs\\\"] = captured_logs\\n        if timing_metadata:\\n            result_data[\\\"timing\\\"] = timing_metadata\\n        return result_data\\n    if output_format in {\\\"text\\\", \\\"message\\\"}:\\n        result_data = extract_structured_result(results)\\n        output_text = result_data.get(\\\"result\\\", result_data.get(\\\"text\\\", \\\"\\\"))\\n        return {\\\"output\\\": str(output_text), \\\"format\\\": output_format}\\n    if output_format == \\\"result\\\":\\n        return {\\\"output\\\": extract_text_from_result(results), \\\"format\\\": \\\"result\\\"}\\n    # Default case\\n    result_data = extract_structured_result(results)\\n    result_data[\\\"logs\\\"] = captured_logs\\n    if timing_metadata:\\n        result_data[\\\"timing\\\"] = timing_metadata\\n    return result_data\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/run/hitl.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1464649b6127648c21bd30f70b1bb58fa983bcb5503b8555b021744e2fbff219\",\"content\":\"\\\"\\\"\\\"Interactive human-in-the-loop driver for CLI runs (CLI HITL).\\n\\n``lfx run`` streams via ``Graph.async_start``, which does not honor the pause seam\\n(``check_and_handle_pause`` runs only inside ``Graph.process``). When a flow contains\\na pausing node (e.g. HumanInput) and the CLI is interactive, this driver runs the\\ngraph via ``process()`` in a loop: each pause surfaces the request to a decision\\nprovider (a terminal prompt on the CLI, a scripted callable in tests), injects the\\nchosen decision into the resumed graph, and continues until the run completes.\\n\\nCheckpoints stay in-process (``InMemoryCheckpointStore``): the CLI has no durable job\\nstore, so a paused CLI run lives only as long as the process. The restore + inject +\\nun-build sequence mirrors what ``build.py``'s background resume branch performs.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport inspect\\nimport sys\\nfrom collections.abc import Awaitable, Callable\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.graph.checkpoint.resume import resume_graph_with_decision\\nfrom lfx.graph.checkpoint.store import CheckpointStore, InMemoryCheckpointStore\\nfrom lfx.graph.exceptions import GraphPausedException\\nfrom lfx.graph.graph.schema import VertexBuildResult\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.graph.base import Graph\\n\\nDecisionProvider = Callable[[dict[str, Any]], \\\"dict[str, Any] | Awaitable[dict[str, Any]]\\\"]\\n\\n# A provider that never resolves a pause would loop forever; bound it.\\n_MAX_PAUSES = 100\\n\\n# Sentinel action for a late answer when no fallback is configured: it matches no\\n# branch, so ``HumanInput.route_branch`` stops every branch and the flow takes no path.\\nEXPIRED_ACTION = \\\"__expired__\\\"\\n\\n\\ndef request_id_targets_vertex(request_id: str, vertex_id: str, run_id: str) -> bool:\\n    \\\"\\\"\\\"Whether a resume ``request_id`` addresses this vertex's pause.\\n\\n    Node pauses use ``vertex_id:run_id``; agent tool-approval pauses append a\\n    per-pause interrupt id (``vertex_id:run_id:interrupt_id``) so each approval\\n    in one run is individually addressable and a stale resume for an earlier\\n    approval cannot be applied to a later one.\\n    \\\"\\\"\\\"\\n    base = f\\\"{vertex_id}:{run_id}\\\"\\n    return request_id == base or request_id.startswith(base + \\\":\\\")\\n\\n\\ndef reroute_decision_on_timeout(pending: dict | None, decision: dict) -> dict:\\n    \\\"\\\"\\\"Reroute a late HITL decision once the pause timed out.\\n\\n    Lazy timeout (no background watchdog): when the human responds we compare now against\\n    ``paused_at + timeout_seconds``. If it elapsed, the late answer must not take the path\\n    the human picked: it is rerouted to the fallback branch when the node defined one, or\\n    to an expired sentinel (no branch taken) otherwise. A timely answer is kept unchanged.\\n    \\\"\\\"\\\"\\n    pending = pending or {}\\n    timeout_s = max(0, pending.get(\\\"timeout_seconds\\\") or 0)\\n    fallback = pending.get(\\\"fallback_action\\\")\\n    paused_at = pending.get(\\\"paused_at\\\")\\n    if not (timeout_s and paused_at):\\n        return decision\\n    try:\\n        paused_dt = datetime.fromisoformat(paused_at)\\n        if paused_dt.tzinfo is None:\\n            paused_dt = paused_dt.replace(tzinfo=timezone.utc)\\n        elapsed = (datetime.now(timezone.utc) - paused_dt).total_seconds()\\n    except (TypeError, ValueError):\\n        return decision\\n    if elapsed > timeout_s:\\n        return {**(decision or {}), \\\"action_id\\\": fallback or EXPIRED_ACTION}\\n    return decision\\n\\n\\nasync def run_graph_with_human_input(\\n    graph: Graph,\\n    *,\\n    decision_provider: DecisionProvider,\\n    input_value: str | None = None,\\n    event_manager: Any = None,\\n    fallback_to_env_vars: bool = False,\\n    store: CheckpointStore | None = None,\\n    start_component_id: str | None = None,\\n) -> list[VertexBuildResult]:\\n    \\\"\\\"\\\"Drive a graph through pauses, asking ``decision_provider`` at each one.\\n\\n    Returns the per-vertex results of the completed run (same shape ``async_start``\\n    yields) so the existing CLI output extractors work unchanged.\\n    \\\"\\\"\\\"\\n    from lfx.schema.schema import INPUT_FIELD_NAME\\n\\n    store = store or InMemoryCheckpointStore()\\n    graph.checkpointing_enabled = True\\n    graph.checkpoint_store = store\\n    # process() (used so resume honors restored state) takes no inputs argument, so\\n    # apply the chat input to the input vertices up front, as Graph.arun does.\\n    if input_value is not None:\\n        graph._set_inputs([], {INPUT_FIELD_NAME: input_value}, \\\"chat\\\")  # noqa: SLF001\\n\\n    pauses = 0\\n    while True:\\n        try:\\n            # Inside the loop on purpose: each pass between pauses is its own unit of work for the\\n            # operator, so a run that pauses twice shows as three spans rather than one long one.\\n            with graph.flow_execution_span():\\n                await graph.process(\\n                    fallback_to_env_vars=fallback_to_env_vars,\\n                    event_manager=event_manager,\\n                    start_component_id=start_component_id,\\n                )\\n        except GraphPausedException as exc:\\n            pauses += 1\\n            if pauses > _MAX_PAUSES:\\n                raise\\n            request = exc.data or {}\\n            decision = decision_provider(request)\\n            if inspect.isawaitable(decision):\\n                decision = await decision\\n            checkpoint = await store.load(exc.checkpoint_id) or await store.load_by_run_id(graph.run_id)\\n            if checkpoint is None:\\n                msg = \\\"Paused run has no recoverable checkpoint; cannot resume.\\\"\\n                raise RuntimeError(msg) from exc\\n            decision = reroute_decision_on_timeout(request, decision)\\n            graph = resume_graph_with_decision(checkpoint, store, request.get(\\\"request_id\\\"), decision)\\n            continue\\n        break\\n\\n    return _collect_results(graph)\\n\\n\\ndef terminal_decision_provider(request: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Interactive CLI provider: print the prompt + options, read the human's pick.\\n\\n    Prints to stderr (stdout is captured for the structured result) and reads a 1-based\\n    option number from stdin. Returns ``{\\\"action_id\\\", \\\"values\\\": {}}``. An empty/invalid\\n    entry defaults to the first option.\\n    \\\"\\\"\\\"\\n    prompt = request.get(\\\"prompt\\\") or \\\"Human input required\\\"\\n    options = request.get(\\\"options\\\") or []\\n    sys.stderr.write(f\\\"\\\\n\u23f8  {prompt}\\\\n\\\")\\n    for index, option in enumerate(options, start=1):\\n        label = option.get(\\\"label\\\") or option.get(\\\"action_id\\\")\\n        sys.stderr.write(f\\\"  {index}. {label}\\\\n\\\")\\n    sys.stderr.write(\\\"Choose an option [1]: \\\")\\n    sys.stderr.flush()\\n    raw = sys.stdin.readline().strip()\\n    choice = 0\\n    if raw.isdigit() and 1 <= int(raw) <= len(options):\\n        choice = int(raw) - 1\\n    action_id = options[choice].get(\\\"action_id\\\") if options else raw\\n    return {\\\"action_id\\\": action_id, \\\"values\\\": {}}\\n\\n\\ndef flow_has_pausing_node(graph: Graph) -> bool:\\n    \\\"\\\"\\\"True when the graph contains a node that can request a human-input pause.\\\"\\\"\\\"\\n    pausing_types = {\\\"HumanInput\\\"}\\n    return any((getattr(vertex, \\\"data\\\", None) or {}).get(\\\"type\\\") in pausing_types for vertex in graph.vertices)\\n\\n\\nNESTED_HITL_UNSUPPORTED = (\\n    \\\"This flow uses Human-in-the-Loop (a Human Input node or a tool that requires approval) and cannot \\\"\\n    \\\"run as a nested flow (Run Flow / Sub Flow / flow-as-tool), because a nested run cannot pause for \\\"\\n    \\\"a decision. Move the approval to the parent flow.\\\"\\n)\\n\\n\\nclass NestedHITLUnsupportedError(ValueError):\\n    \\\"\\\"\\\"Deliberate user guidance \u2014 wrappers must surface it verbatim, not genericize it.\\\"\\\"\\\"\\n\\n\\ndef flow_has_blocking_pausing_node(graph: Graph) -> bool:\\n    \\\"\\\"\\\"True when a non-pausable run of this graph would need to pause.\\n\\n    Mirrors the v1 API guard's two HITL shapes: a Human Input wired to a downstream consumer\\n    (an isolated one skips at runtime, so it is not blocking), or an agent tool carrying a\\n    non-empty ``approval_actions``.\\n    \\\"\\\"\\\"\\n    for vertex in graph.vertices:\\n        data = getattr(vertex, \\\"data\\\", None) or {}\\n        if data.get(\\\"type\\\") == \\\"HumanInput\\\" and graph.successor_map.get(vertex.id):\\n            return True\\n        template = ((data.get(\\\"node\\\") or {}).get(\\\"template\\\")) or {}\\n        rows = (template.get(\\\"tools_metadata\\\") or {}).get(\\\"value\\\")\\n        if isinstance(rows, list) and any(isinstance(row, dict) and row.get(\\\"approval_actions\\\") for row in rows):\\n            return True\\n    return False\\n\\n\\ndef raise_if_nested_hitl_unsupported(graph: Graph) -> None:\\n    \\\"\\\"\\\"Reject a nested run of a pausing flow with a clear error instead of a silent non-pause.\\\"\\\"\\\"\\n    if flow_has_blocking_pausing_node(graph):\\n        raise NestedHITLUnsupportedError(NESTED_HITL_UNSUPPORTED)\\n\\n\\ndef _collect_results(graph: Graph) -> list[VertexBuildResult]:\\n    \\\"\\\"\\\"Rebuild the per-vertex result list from a processed graph's built vertices.\\\"\\\"\\\"\\n    results: list[VertexBuildResult] = []\\n    for vertex in graph.vertices:\\n        if not vertex.built or vertex.result is None:\\n            continue\\n        results.append(\\n            VertexBuildResult(\\n                result_dict=vertex.result,\\n                params=\\\"\\\",\\n                valid=True,\\n                artifacts=vertex.artifacts,\\n                vertex=vertex,\\n            )\\n        )\\n    return results\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9b5de6b49d1c1204c891c6187a2a1af00dedb6a9750f3ec83b4370bd2d7a5c0f\",\"content\":\"\\\"\\\"\\\"Schema modules for lfx package.\\\"\\\"\\\"\\n\\n__all__ = [\\n    \\\"WORKFLOW_EXECUTION_RESPONSES\\\",\\n    \\\"WORKFLOW_STATUS_RESPONSES\\\",\\n    \\\"ComponentOutput\\\",\\n    \\\"Data\\\",\\n    \\\"DataFrame\\\",\\n    \\\"ErrorDetail\\\",\\n    \\\"InputValue\\\",\\n    \\\"JobStatus\\\",\\n    \\\"Message\\\",\\n    \\\"OpenAIErrorResponse\\\",\\n    \\\"OpenAIResponsesRequest\\\",\\n    \\\"OpenAIResponsesResponse\\\",\\n    \\\"OpenAIResponsesStreamChunk\\\",\\n    \\\"Tweaks\\\",\\n    \\\"UUIDstr\\\",\\n    \\\"WorkflowExecutionRequest\\\",\\n    \\\"WorkflowExecutionResponse\\\",\\n    \\\"WorkflowJobResponse\\\",\\n    \\\"WorkflowStopRequest\\\",\\n    \\\"WorkflowStopResponse\\\",\\n    \\\"WorkflowStreamEvent\\\",\\n    \\\"create_openai_error\\\",\\n    \\\"create_openai_error_chunk\\\",\\n    \\\"dotdict\\\",\\n]\\n\\n\\ndef __getattr__(name: str):\\n    # Import to avoid circular dependencies\\n    if name == \\\"Data\\\":\\n        from .data import Data\\n\\n        return Data\\n    if name == \\\"DataFrame\\\":\\n        from .dataframe import DataFrame\\n\\n        return DataFrame\\n    if name == \\\"dotdict\\\":\\n        from .dotdict import dotdict\\n\\n        return dotdict\\n    if name == \\\"InputValue\\\":\\n        from .graph import InputValue\\n\\n        return InputValue\\n    if name == \\\"Tweaks\\\":\\n        from .graph import Tweaks\\n\\n        return Tweaks\\n    if name == \\\"Message\\\":\\n        from .message import Message\\n\\n        return Message\\n    if name == \\\"UUIDstr\\\":\\n        from .serialize import UUIDstr\\n\\n        return UUIDstr\\n    if name == \\\"OpenAIResponsesRequest\\\":\\n        from .openai_responses_schemas import OpenAIResponsesRequest\\n\\n        return OpenAIResponsesRequest\\n    if name == \\\"OpenAIResponsesResponse\\\":\\n        from .openai_responses_schemas import OpenAIResponsesResponse\\n\\n        return OpenAIResponsesResponse\\n    if name == \\\"OpenAIResponsesStreamChunk\\\":\\n        from .openai_responses_schemas import OpenAIResponsesStreamChunk\\n\\n        return OpenAIResponsesStreamChunk\\n    if name == \\\"OpenAIErrorResponse\\\":\\n        from .openai_responses_schemas import OpenAIErrorResponse\\n\\n        return OpenAIErrorResponse\\n    if name == \\\"create_openai_error\\\":\\n        from .openai_responses_schemas import create_openai_error\\n\\n        return create_openai_error\\n    if name == \\\"create_openai_error_chunk\\\":\\n        from .openai_responses_schemas import create_openai_error_chunk\\n\\n        return create_openai_error_chunk\\n    if name == \\\"WorkflowExecutionRequest\\\":\\n        from .workflow import WorkflowExecutionRequest\\n\\n        return WorkflowExecutionRequest\\n    if name == \\\"WorkflowExecutionResponse\\\":\\n        from .workflow import WorkflowExecutionResponse\\n\\n        return WorkflowExecutionResponse\\n    if name == \\\"WorkflowJobResponse\\\":\\n        from .workflow import WorkflowJobResponse\\n\\n        return WorkflowJobResponse\\n    if name == \\\"WorkflowStreamEvent\\\":\\n        from .workflow import WorkflowStreamEvent\\n\\n        return WorkflowStreamEvent\\n    if name == \\\"WORKFLOW_EXECUTION_RESPONSES\\\":\\n        from .workflow import WORKFLOW_EXECUTION_RESPONSES\\n\\n        return WORKFLOW_EXECUTION_RESPONSES\\n    if name == \\\"WORKFLOW_STATUS_RESPONSES\\\":\\n        from .workflow import WORKFLOW_STATUS_RESPONSES\\n\\n        return WORKFLOW_STATUS_RESPONSES\\n    if name == \\\"WorkflowStopRequest\\\":\\n        from .workflow import WorkflowStopRequest\\n\\n        return WorkflowStopRequest\\n    if name == \\\"WorkflowStopResponse\\\":\\n        from .workflow import WorkflowStopResponse\\n\\n        return WorkflowStopResponse\\n    if name == \\\"JobStatus\\\":\\n        from .workflow import JobStatus\\n\\n        return JobStatus\\n    if name == \\\"ErrorDetail\\\":\\n        from .workflow import ErrorDetail\\n\\n        return ErrorDetail\\n    if name == \\\"ComponentOutput\\\":\\n        from .workflow import ComponentOutput\\n\\n        return ComponentOutput\\n\\n    msg = f\\\"module '{__name__}' has no attribute '{name}'\\\"\\n    raise AttributeError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/artifact.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a2858fba2a25c6c448f6379349241e7184dbf2fc88686c0f17c0b5b9d679918a\",\"content\":\"from collections.abc import Generator\\nfrom enum import Enum\\n\\nfrom fastapi.encoders import jsonable_encoder\\nfrom pydantic import BaseModel\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.encoders import CUSTOM_ENCODERS\\nfrom lfx.schema.message import Message\\nfrom lfx.serialization.serialization import serialize\\n\\n\\nclass ArtifactType(str, Enum):\\n    TEXT = \\\"text\\\"\\n    DATA = \\\"data\\\"\\n    OBJECT = \\\"object\\\"\\n    ARRAY = \\\"array\\\"\\n    STREAM = \\\"stream\\\"\\n    UNKNOWN = \\\"unknown\\\"\\n    MESSAGE = \\\"message\\\"\\n    RECORD = \\\"record\\\"\\n\\n\\ndef get_artifact_type(value, build_result=None) -> str:\\n    result = ArtifactType.UNKNOWN\\n    match value:\\n        case Message():\\n            if not isinstance(value.text, str):\\n                enum_value = get_artifact_type(value.text)\\n                result = ArtifactType(enum_value)\\n            else:\\n                result = ArtifactType.MESSAGE\\n        case Data():\\n            enum_value = get_artifact_type(value.data)\\n            result = ArtifactType(enum_value)\\n\\n        case str():\\n            result = ArtifactType.TEXT\\n\\n        case dict():\\n            result = ArtifactType.OBJECT\\n\\n        case list() | DataFrame():\\n            result = ArtifactType.ARRAY\\n    if result == ArtifactType.UNKNOWN and (\\n        (build_result and isinstance(build_result, Generator))\\n        or (isinstance(value, Message) and isinstance(value.text, Generator))\\n    ):\\n        result = ArtifactType.STREAM\\n\\n    return result.value\\n\\n\\ndef _to_list_of_dicts(raw):\\n    raw_ = []\\n    for item in raw:\\n        if hasattr(item, \\\"dict\\\") or hasattr(item, \\\"model_dump\\\"):\\n            raw_.append(serialize(item))\\n        else:\\n            raw_.append(str(item))\\n    return raw_\\n\\n\\ndef post_process_raw(raw, artifact_type: str):\\n    default_message = \\\"Built Successfully \u2728\\\"\\n\\n    if artifact_type == ArtifactType.STREAM.value:\\n        raw = \\\"\\\"\\n    elif artifact_type == ArtifactType.ARRAY.value:\\n        raw = raw.to_dict(orient=\\\"records\\\") if isinstance(raw, DataFrame) else _to_list_of_dicts(raw)\\n    elif artifact_type == ArtifactType.UNKNOWN.value and raw is not None:\\n        if isinstance(raw, BaseModel | dict):\\n            try:\\n                raw = jsonable_encoder(raw, custom_encoder=CUSTOM_ENCODERS)\\n                artifact_type = ArtifactType.OBJECT.value\\n            except Exception:  # noqa: BLE001\\n                logger.debug(f\\\"Error converting to json: {raw} ({type(raw)})\\\", exc_info=True)\\n                raw = default_message\\n        else:\\n            raw = default_message\\n    return raw, artifact_type\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/content_block.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e287396ae97e87b82d1662ef8b401998e66dbb4dc20e0a2d977dd25dd5321f4e\",\"content\":\"\\\"\\\"\\\"Re-export shim.\\n\\nContentBlock and ContentType now live in content_types.py alongside the\\nrest of the discriminated union.\\n\\\"\\\"\\\"\\n\\nfrom .content_types import ContentBlock, ContentBlockDict, ContentType\\n\\n__all__ = [\\\"ContentBlock\\\", \\\"ContentBlockDict\\\", \\\"ContentType\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/content_types.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"68a7fc4ba0905671101b33bbe067216d4ccfefb39267e28b2db52b2d215b94d6\",\"content\":\"\\\"\\\"\\\"Content types for ``Message.content_blocks``.\\n\\nEach content type carries one kind of payload \u2014 text, a tool call, an image,\\na chain-of-thought trace, etc. \u2014 and the ``contents`` field on ``BaseContent``\\nlets any node nest more content underneath. That nesting is how a single\\n``ToolContent`` can carry a multimodal result (text + image + citation), a\\n``ReasoningContent`` can carry sub-steps, and a ``ContentBlock`` can be a\\ntitled group of related items, all using the same primitive.\\n\\n``ContentType`` is a discriminated union over every concrete subclass\\n(including ``ContentBlock``), keyed by the ``type`` literal on each class.\\nA ``content_blocks`` list is always ``list[ContentType]`` \u2014 there's no\\nseparate \\\"wrapper\\\" shape; the wrapper *is* a ContentType.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import Annotated, Any, Literal\\n\\nfrom fastapi.encoders import jsonable_encoder\\nfrom pydantic import (\\n    BaseModel,\\n    ConfigDict,\\n    Discriminator,\\n    Field,\\n    Tag,\\n    field_serializer,\\n    field_validator,\\n    model_serializer,\\n    model_validator,\\n)\\nfrom typing_extensions import TypedDict\\n\\nfrom lfx.schema.encoders import CUSTOM_ENCODERS\\n\\n\\nclass HeaderDict(TypedDict, total=False):\\n    title: str | None\\n    icon: str | None\\n\\n\\nclass BaseContent(BaseModel):\\n    \\\"\\\"\\\"Base class for all content types.\\n\\n    The optional ``id`` field carries stable identity across re-emissions of\\n    the same logical block. Producers that have a natural id (LangChain\\n    ``tool_call_id``, an external API id, a UUID stamped before the first\\n    emission) set it; consumers use it for dedup and cross-frame correlation.\\n    Without an id, consumers fall back to position-derived dedup, which\\n    assumes ``content_blocks`` is append-only within a message lifetime.\\n\\n    The optional ``contents`` field lets any content type nest more content\\n    underneath. Leaf types (``TextContent``, ``ErrorContent``, ``UsageContent``)\\n    leave it empty; container-shaped types (``ContentBlock``, multimodal\\n    ``ToolContent``, multi-step ``ReasoningContent``) populate it.\\n    \\\"\\\"\\\"\\n\\n    type: str = Field(..., description=\\\"Type of the content\\\")\\n    id: str | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Optional stable identity for this content block across \\\"\\n            \\\"re-emissions. Set by producers that have a natural id \\\"\\n            \\\"(e.g. LangChain tool_call_id).\\\"\\n        ),\\n    )\\n    duration: int | None = None\\n    header: HeaderDict | None = Field(default_factory=dict)\\n    contents: list[ContentType] = Field(\\n        default_factory=list,\\n        description=(\\n            \\\"Nested content. Leaf types leave this empty; container-shaped \\\"\\n            \\\"types (groups, multimodal tool outputs, multi-step reasoning) \\\"\\n            \\\"populate it.\\\"\\n        ),\\n    )\\n\\n    def to_dict(self) -> dict[str, Any]:\\n        return self.model_dump()\\n\\n    @classmethod\\n    def from_dict(cls, data: dict[str, Any]) -> BaseContent:\\n        return cls(**data)\\n\\n    @model_serializer(mode=\\\"wrap\\\")\\n    def serialize_model(self, nxt) -> dict[str, Any]:\\n        try:\\n            dump = nxt(self)\\n            # Keep the discriminator through exclude_unset/defaults (else reload fails union_tag_not_found).\\n            if isinstance(dump, dict):\\n                dump.setdefault(\\\"type\\\", self.type)\\n            return jsonable_encoder(dump, custom_encoder=CUSTOM_ENCODERS)\\n        except Exception:  # noqa: BLE001\\n            return nxt(self)\\n\\n\\nclass ErrorContent(BaseContent):\\n    \\\"\\\"\\\"Content type for error messages.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"error\\\"] = Field(default=\\\"error\\\")\\n    component: str | None = None\\n    field: str | None = None\\n    reason: str | None = None\\n    solution: str | None = None\\n    traceback: str | None = None\\n\\n\\nclass TextContent(BaseContent):\\n    \\\"\\\"\\\"Content type for simple text content.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"text\\\"] = Field(default=\\\"text\\\")\\n    text: str\\n    duration: int | None = None\\n\\n\\nclass MediaContent(BaseContent):\\n    \\\"\\\"\\\"Content type for media content.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"media\\\"] = Field(default=\\\"media\\\")\\n    urls: list[str]\\n    caption: str | None = None\\n\\n\\nclass JSONContent(BaseContent):\\n    \\\"\\\"\\\"Content type for JSON content.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"json\\\"] = Field(default=\\\"json\\\")\\n    data: dict[str, Any]\\n\\n\\nclass CodeContent(BaseContent):\\n    \\\"\\\"\\\"Content type for code snippets.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"code\\\"] = Field(default=\\\"code\\\")\\n    code: str\\n    language: str\\n    title: str | None = None\\n\\n\\nclass HumanInputContent(BaseContent):\\n    \\\"\\\"\\\"Content type for a human-in-the-loop pause persisted in the chat history.\\n\\n    Carries the pending decision so the interactive card survives reload: the\\n    request_id and job_id let the card resume the suspended run after an F5.\\n    \\\"\\\"\\\"\\n\\n    type: Literal[\\\"human_input\\\"] = Field(default=\\\"human_input\\\")\\n    request_id: str\\n    job_id: str | None = None\\n    kind: str = \\\"node_input\\\"\\n    prompt: str | None = None\\n    options: list[dict[str, Any]] = Field(default_factory=list)\\n    fields: list[dict[str, Any]] = Field(default_factory=list)\\n    allowed_decisions: list[str] = Field(default_factory=list)\\n    submitted_action: str | None = None\\n    superseded: bool = False\\n\\n\\nclass ToolContent(BaseContent):\\n    \\\"\\\"\\\"Content type for a tool invocation.\\n\\n    ``output`` carries a string / JSON output (legacy / single-value tools).\\n    Rich, multimodal outputs use the inherited ``contents`` list \u2014 e.g. an\\n    image-generation tool returns\\n    ``ToolContent(name=..., contents=[TextContent(...), ImageContent(...)])``.\\n    \\\"\\\"\\\"\\n\\n    model_config = ConfigDict(populate_by_name=True)\\n\\n    type: Literal[\\\"tool_use\\\"] = Field(default=\\\"tool_use\\\")\\n    name: str | None = None\\n    tool_input: dict[str, Any] = Field(default_factory=dict, alias=\\\"input\\\")\\n    output: Any | None = None\\n    error: Any | None = None\\n    duration: int | None = None\\n\\n    @field_validator(\\\"tool_input\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def _coerce_tool_input(cls, v: Any) -> dict[str, Any]:\\n        # LangChain ``AgentAction.tool_input`` is ``str | dict`` during\\n        # streaming, and ``event[\\\"data\\\"].get(\\\"input\\\") or {}`` passes a\\n        # non-empty string straight through. The dict-typed field used to\\n        # raise ValidationError on it. Parse JSON objects; wrap any other\\n        # string under an ``input`` key so the field always validates.\\n        if isinstance(v, str):\\n            try:\\n                parsed = json.loads(v)\\n            except (ValueError, TypeError):\\n                return {\\\"input\\\": v}\\n            return parsed if isinstance(parsed, dict) else {\\\"input\\\": parsed}\\n        if v is None:\\n            return {}\\n        return v\\n\\n\\nclass _MediaContentMixin:\\n    \\\"\\\"\\\"Shared validation for media content types (image, audio, video).\\\"\\\"\\\"\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _validate_media_source(self):\\n        if not self.urls and not self.base64:\\n            msg = f\\\"{type(self).__name__} requires at least one of 'urls' or 'base64'\\\"\\n            raise ValueError(msg)\\n        if self.base64 and not self.mime_type:\\n            msg = f\\\"{type(self).__name__} with 'base64' data requires 'mime_type'\\\"\\n            raise ValueError(msg)\\n        return self\\n\\n\\nclass ImageContent(_MediaContentMixin, BaseContent):\\n    \\\"\\\"\\\"Content type for image content.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"image\\\"] = Field(default=\\\"image\\\")\\n    urls: list[str] | None = None\\n    base64: str | None = None\\n    mime_type: str | None = None\\n    caption: str | None = None\\n\\n\\nclass AudioContent(_MediaContentMixin, BaseContent):\\n    \\\"\\\"\\\"Content type for audio content.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"audio\\\"] = Field(default=\\\"audio\\\")\\n    urls: list[str] | None = None\\n    base64: str | None = None\\n    mime_type: str | None = None\\n    transcript: str | None = None\\n\\n\\nclass VideoContent(_MediaContentMixin, BaseContent):\\n    \\\"\\\"\\\"Content type for video content.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"video\\\"] = Field(default=\\\"video\\\")\\n    urls: list[str] | None = None\\n    base64: str | None = None\\n    mime_type: str | None = None\\n\\n\\nclass FileContent(BaseContent):\\n    \\\"\\\"\\\"Content type for file content.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"file\\\"] = Field(default=\\\"file\\\")\\n    urls: list[str] | None = None\\n    mime_type: str | None = None\\n    filename: str | None = None\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _validate_file_source(self):\\n        if not self.urls:\\n            msg = \\\"FileContent requires 'urls'\\\"\\n            raise ValueError(msg)\\n        return self\\n\\n\\nclass ReasoningContent(BaseContent):\\n    \\\"\\\"\\\"Content type for reasoning content.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"reasoning\\\"] = Field(default=\\\"reasoning\\\")\\n    text: str = \\\"\\\"\\n\\n\\nclass UsageContent(BaseContent):\\n    \\\"\\\"\\\"Content type for usage/token tracking content.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"usage\\\"] = Field(default=\\\"usage\\\")\\n    input_tokens: int | None = Field(default=None, ge=0)\\n    output_tokens: int | None = Field(default=None, ge=0)\\n    model: str | None = None\\n\\n\\nclass CitationContent(BaseContent):\\n    \\\"\\\"\\\"Content type for citation content.\\\"\\\"\\\"\\n\\n    type: Literal[\\\"citation\\\"] = Field(default=\\\"citation\\\")\\n    url: str | None = None\\n    title: str | None = None\\n    cited_text: str | None = None\\n    start_index: int | None = Field(default=None, ge=0)\\n    end_index: int | None = Field(default=None, ge=0)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _validate_index_range(self):\\n        if self.start_index is not None and self.end_index is not None and self.start_index > self.end_index:\\n            msg = f\\\"start_index ({self.start_index}) must be <= end_index ({self.end_index})\\\"\\n            raise ValueError(msg)\\n        return self\\n\\n\\nclass ContentBlock(BaseContent):\\n    \\\"\\\"\\\"A titled group of nested contents.\\n\\n    Use this when a section needs an explicit label and icon \u2014 typically\\n    errors, agent step traces, or any UI grouping that shouldn't be inferred\\n    from adjacency. The ``contents`` list (inherited from ``BaseContent``)\\n    holds the grouped items.\\n    \\\"\\\"\\\"\\n\\n    type: Literal[\\\"group\\\"] = Field(default=\\\"group\\\")\\n    title: str\\n    allow_markdown: bool = Field(default=True)\\n    media_url: list[str] | None = None\\n\\n    def __init__(self, **data) -> None:\\n        super().__init__(**data)\\n        # Mark only the discriminator as \\\"set\\\" so partial-update callers\\n        # using ``model_dump(exclude_unset=True)`` (notably\\n        # ``aupdate_messages``) still carry the ``type=\\\"group\\\"`` field\\n        # downstream. Other defaulted fields stay unset so true\\n        # exclude_unset semantics survive: a patch like\\n        # ``ContentBlock(title=\\\"...\\\")`` no longer overwrites an existing\\n        # block's ``duration`` / ``header`` / ``contents`` with their\\n        # defaults on merge.\\n        self.model_fields_set.add(\\\"type\\\")\\n\\n    @field_validator(\\\"contents\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_contents(cls, v):\\n        # Accept either a single content item or a list. Legacy callers may\\n        # pass a bare BaseModel; wrap it so the discriminated-union validator\\n        # downstream sees a list.\\n        if isinstance(v, dict):\\n            msg = \\\"Contents must be a list of ContentTypes\\\"\\n            raise TypeError(msg)\\n        return [v] if isinstance(v, BaseModel) else v\\n\\n    @field_serializer(\\\"contents\\\")\\n    def serialize_contents(self, value) -> list[dict]:\\n        return [v.model_dump() for v in value]\\n\\n\\ndef _get_content_type(d: dict | BaseModel) -> str | None:\\n    \\\"\\\"\\\"Pydantic discriminator: return the ``type`` field from dict or model.\\\"\\\"\\\"\\n    if isinstance(d, dict):\\n        return d.get(\\\"type\\\")\\n    return getattr(d, \\\"type\\\", None)\\n\\n\\n# Discriminated union over every concrete content type. ``ContentBlock`` is a\\n# first-class member (tag ``group``) so consumers walk one uniform shape\\n# instead of branching on \\\"wrapper vs leaf.\\\"\\nContentType = Annotated[\\n    Annotated[ToolContent, Tag(\\\"tool_use\\\")]\\n    | Annotated[ErrorContent, Tag(\\\"error\\\")]\\n    | Annotated[TextContent, Tag(\\\"text\\\")]\\n    | Annotated[MediaContent, Tag(\\\"media\\\")]\\n    | Annotated[CodeContent, Tag(\\\"code\\\")]\\n    | Annotated[JSONContent, Tag(\\\"json\\\")]\\n    | Annotated[ImageContent, Tag(\\\"image\\\")]\\n    | Annotated[AudioContent, Tag(\\\"audio\\\")]\\n    | Annotated[VideoContent, Tag(\\\"video\\\")]\\n    | Annotated[FileContent, Tag(\\\"file\\\")]\\n    | Annotated[ReasoningContent, Tag(\\\"reasoning\\\")]\\n    | Annotated[UsageContent, Tag(\\\"usage\\\")]\\n    | Annotated[CitationContent, Tag(\\\"citation\\\")]\\n    | Annotated[HumanInputContent, Tag(\\\"human_input\\\")]\\n    | Annotated[ContentBlock, Tag(\\\"group\\\")],\\n    Discriminator(_get_content_type),\\n]\\n\\n\\n# Resolve the forward reference on ``BaseContent.contents``. Every subclass\\n# inherits the field, so rebuilding the parent is enough \u2014 Pydantic re-derives\\n# the validator schema for subclasses on next validation.\\nBaseContent.model_rebuild()\\n\\n\\nclass ContentBlockDict(TypedDict):\\n    \\\"\\\"\\\"Legacy TypedDict shape kept for callers that expect a plain dict.\\\"\\\"\\\"\\n\\n    title: str\\n    contents: list[dict]\\n    allow_markdown: bool\\n    media_url: list[str] | None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/cross_module.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6b190c9162d01cb8ae004660e8a6ca97758549591bac1ccd83eab34603cf4e3b\",\"content\":\"\\\"\\\"\\\"Cross-module BaseModel for handling re-exported classes.\\n\\nThis module provides a metaclass and base model that enable isinstance checks\\nto work across module boundaries for Pydantic models. This is particularly useful\\nwhen the same class is re-exported from different modules (e.g., lfx.Message vs\\nlangflow.schema.Message) but Python's isinstance() checks fail due to different\\nmodule paths.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\nfrom pydantic import BaseModel\\n\\n\\nclass CrossModuleMeta(type(BaseModel)):  # type: ignore[misc]\\n    \\\"\\\"\\\"Metaclass that enables cross-module isinstance checks for Pydantic models.\\n\\n    This metaclass overrides __instancecheck__ to perform structural type checking\\n    based on the model's fields rather than strict class identity. This allows\\n    instances of the same model from different module paths to be recognized as\\n    compatible.\\n    \\\"\\\"\\\"\\n\\n    def __instancecheck__(cls, instance: Any) -> bool:\\n        \\\"\\\"\\\"Check if instance is compatible with this class across module boundaries.\\n\\n        First performs a standard isinstance check. If that fails, falls back to\\n        checking if the instance has all required Pydantic model attributes and\\n        a compatible set of model fields.\\n\\n        Args:\\n            instance: The object to check.\\n\\n        Returns:\\n            bool: True if instance is compatible with this class.\\n        \\\"\\\"\\\"\\n        # First try standard isinstance check\\n        if type.__instancecheck__(cls, instance):\\n            return True\\n\\n        # If that fails, check for cross-module compatibility\\n        # An object is cross-module compatible if it:\\n        # 1. Has model_fields attribute (is a Pydantic model)\\n        # 2. Has the same __class__.__name__\\n        # 3. Has compatible model fields\\n        instance_cls = type(instance)\\n        if not hasattr(instance_cls, \\\"model_fields\\\"):\\n            return False\\n\\n        # Check if class names match\\n        if instance_cls.__name__ != cls.__name__:\\n            return False\\n\\n        # Check if the instance has all required fields from cls\\n        cls_fields = set(cls.model_fields.keys()) if hasattr(cls, \\\"model_fields\\\") else set()\\n        instance_fields = set(instance_cls.model_fields.keys())\\n\\n        # The instance must have at least the same fields as the class\\n        # (it can have more, but not fewer required fields)\\n        return cls_fields.issubset(instance_fields)\\n\\n\\nclass CrossModuleModel(BaseModel, metaclass=CrossModuleMeta):\\n    \\\"\\\"\\\"Base Pydantic model with cross-module isinstance support.\\n\\n    This class should be used as the base for models that may be re-exported\\n    from different modules. It enables isinstance() checks to work across\\n    module boundaries by using structural type checking.\\n\\n    Example:\\n        >>> class Message(CrossModuleModel):\\n        ...     text: str\\n        ...\\n        >>> # Even if Message is imported from different paths:\\n        >>> from lfx.schema.message import Message as LfxMessage\\n        >>> from langflow.schema import Message as LangflowMessage\\n        >>> msg = LfxMessage(text=\\\"hello\\\")\\n        >>> isinstance(msg, LangflowMessage)  # True (with cross-module support)\\n    \\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/data.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"565eea5840dc0b5a544a663858360532978bbb7c8d8c58fbd40b57e3b3bfbff0\",\"content\":\"\\\"\\\"\\\"Lightweight JSON class for lfx package - contains only methods with no langflow dependencies.\\n\\nThis module provides the JSON class (formerly Data) as the base type for Langflow data structures.\\nData is maintained as an alias for backwards compatibility.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport copy\\nimport json\\nfrom datetime import datetime, timezone\\nfrom decimal import Decimal\\nfrom typing import TYPE_CHECKING, cast\\nfrom uuid import UUID\\n\\nfrom langchain_core.documents import Document\\nfrom langchain_core.messages import AIMessage, BaseMessage, HumanMessage\\nfrom pydantic import BaseModel, ConfigDict, model_serializer, model_validator\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.cross_module import CrossModuleModel\\nfrom lfx.utils.constants import MESSAGE_SENDER_AI, MESSAGE_SENDER_USER\\nfrom lfx.utils.image import create_image_content_dict\\n\\nif TYPE_CHECKING:\\n    from lfx.schema.dataframe import Table\\n    from lfx.schema.message import Message\\n\\n\\ndef custom_serializer(obj):\\n    if isinstance(obj, datetime):\\n        utc_date = obj.replace(tzinfo=timezone.utc)\\n        return utc_date.strftime(\\\"%Y-%m-%d %H:%M:%S %Z\\\")\\n    if isinstance(obj, Decimal):\\n        return float(obj)\\n    if isinstance(obj, UUID):\\n        return str(obj)\\n    if isinstance(obj, BaseModel):\\n        return obj.model_dump()\\n    if isinstance(obj, bytes):\\n        return obj.decode(\\\"utf-8\\\", errors=\\\"replace\\\")\\n    # Add more custom serialization rules as needed\\n    msg = f\\\"Type {type(obj)} not serializable\\\"\\n    raise TypeError(msg)\\n\\n\\ndef serialize_data(data):\\n    return json.dumps(data, indent=4, default=custom_serializer)\\n\\n\\nclass JSON(CrossModuleModel):\\n    \\\"\\\"\\\"Represents a record with text and optional data.\\n\\n    This is the base type for Langflow data structures, replacing the legacy Data class.\\n    Data is maintained as an alias for backwards compatibility.\\n\\n    Attributes:\\n        data (dict, optional): Additional data associated with the record.\\n    \\\"\\\"\\\"\\n\\n    model_config = ConfigDict(validate_assignment=True)\\n\\n    text_key: str = \\\"text\\\"\\n    data: dict = {}\\n    default_value: str | None = \\\"\\\"\\n\\n    @model_validator(mode=\\\"before\\\")\\n    @classmethod\\n    def validate_data(cls, values):\\n        if not isinstance(values, dict):\\n            msg = \\\"Data must be a dictionary\\\"\\n            raise ValueError(msg)  # noqa: TRY004\\n        if \\\"data\\\" not in values or values[\\\"data\\\"] is None:\\n            values[\\\"data\\\"] = {}\\n        if not isinstance(values[\\\"data\\\"], dict):\\n            msg = (\\n                f\\\"Invalid data format: expected dictionary but got {type(values).__name__}.\\\"\\n                \\\" This will raise an error in version langflow==1.3.0.\\\"\\n            )\\n            logger.warning(msg)\\n        # Any other keyword should be added to the data dictionary\\n        for key in values:\\n            if key not in values[\\\"data\\\"] and key not in {\\\"text_key\\\", \\\"data\\\", \\\"default_value\\\"}:\\n                values[\\\"data\\\"][key] = values[key]\\n        return values\\n\\n    @model_serializer(mode=\\\"plain\\\", when_used=\\\"json\\\")\\n    def serialize_model(self):\\n        return {k: v.to_json() if hasattr(v, \\\"to_json\\\") else v for k, v in self.data.items()}\\n\\n    def get_text(self):\\n        \\\"\\\"\\\"Retrieves the text value from the data dictionary.\\n\\n        If the text key is present in the data dictionary, the corresponding value is returned.\\n        Otherwise, the default value is returned.\\n\\n        Returns:\\n            The text value from the data dictionary or the default value.\\n        \\\"\\\"\\\"\\n        return self.data.get(self.text_key, self.default_value)\\n\\n    def set_text(self, text: str | None) -> str:\\n        r\\\"\\\"\\\"Sets the text value in the data dictionary.\\n\\n        The object's `text` value is set to `text parameter as given, with the following modifications:\\n\\n         - `text` value of `None` is converted to an empty string.\\n         - `text` value is converted to `str` type.\\n\\n        Args:\\n            text (str): The text to be set in the data dictionary.\\n\\n        Returns:\\n            str: The text value that was set in the data dictionary.\\n        \\\"\\\"\\\"\\n        new_text = \\\"\\\" if text is None else str(text)\\n        self.data[self.text_key] = new_text\\n        return new_text\\n\\n    @classmethod\\n    def from_document(cls, document: Document) -> JSON:\\n        \\\"\\\"\\\"Converts a Document to a JSON.\\n\\n        Args:\\n            document (Document): The Document to convert.\\n\\n        Returns:\\n            JSON: The converted JSON.\\n        \\\"\\\"\\\"\\n        data = document.metadata\\n        data[\\\"text\\\"] = document.page_content\\n        return cls(data=data, text_key=\\\"text\\\")\\n\\n    @classmethod\\n    def from_lc_message(cls, message: BaseMessage) -> JSON:\\n        \\\"\\\"\\\"Converts a BaseMessage to a JSON.\\n\\n        Args:\\n            message (BaseMessage): The BaseMessage to convert.\\n\\n        Returns:\\n            JSON: The converted JSON.\\n        \\\"\\\"\\\"\\n        data: dict = {\\\"text\\\": message.content}\\n        data[\\\"metadata\\\"] = cast(\\\"dict\\\", message.to_json())\\n        return cls(data=data, text_key=\\\"text\\\")\\n\\n    def __add__(self, other: JSON) -> JSON:\\n        \\\"\\\"\\\"Combines the data of two JSON objects by attempting to add values for overlapping keys.\\n\\n        Combines the data of two JSON objects by attempting to add values for overlapping keys\\n        for all types that support the addition operation. Falls back to the value from 'other'\\n        when addition is not supported.\\n        \\\"\\\"\\\"\\n        combined_data = self.data.copy()\\n        for key, value in other.data.items():\\n            # If the key exists in both data and both values support the addition operation\\n            if key in combined_data:\\n                try:\\n                    combined_data[key] += value\\n                except TypeError:\\n                    # Fallback: Use the value from 'other' if addition is not supported\\n                    combined_data[key] = value\\n            else:\\n                # If the key is not in the first object, simply add it\\n                combined_data[key] = value\\n\\n        return JSON(data=combined_data)\\n\\n    def to_lc_document(self) -> Document:\\n        \\\"\\\"\\\"Converts the Data to a Document.\\n\\n        Returns:\\n            Document: The converted Document.\\n        \\\"\\\"\\\"\\n        data_copy = self.data.copy()\\n        text = data_copy.pop(self.text_key, self.default_value)\\n        if isinstance(text, str):\\n            return Document(page_content=text, metadata=data_copy)\\n        return Document(page_content=str(text), metadata=data_copy)\\n\\n    def to_lc_message(\\n        self,\\n    ) -> BaseMessage:\\n        \\\"\\\"\\\"Converts the JSON to a BaseMessage.\\n\\n        Returns:\\n            BaseMessage: The converted BaseMessage.\\n        \\\"\\\"\\\"\\n        # The idea of this function is to be a helper to convert a JSON to a BaseMessage\\n        # It will use the \\\"sender\\\" key to determine if the message is Human or AI\\n        # If the key is not present, it will default to AI\\n        # But first we check if all required keys are present in the data dictionary\\n        # they are: \\\"text\\\", \\\"sender\\\"\\n        if not all(key in self.data for key in [\\\"text\\\", \\\"sender\\\"]):\\n            msg = f\\\"Missing required keys ('text', 'sender') in JSON: {self.data}\\\"\\n            raise ValueError(msg)\\n        sender = self.data.get(\\\"sender\\\", MESSAGE_SENDER_AI)\\n        text = self.data.get(\\\"text\\\", \\\"\\\")\\n        files = self.data.get(\\\"files\\\", [])\\n        if sender == MESSAGE_SENDER_USER:\\n            if files:\\n                from lfx.schema.image import get_file_paths\\n\\n                resolved_file_paths = get_file_paths(files)\\n                contents = [create_image_content_dict(file_path) for file_path in resolved_file_paths]\\n                # add to the beginning of the list\\n                contents.insert(0, {\\\"type\\\": \\\"text\\\", \\\"text\\\": text})\\n                human_message = HumanMessage(content=contents)\\n            else:\\n                human_message = HumanMessage(\\n                    content=[{\\\"type\\\": \\\"text\\\", \\\"text\\\": text}],\\n                )\\n\\n            return human_message\\n\\n        return AIMessage(content=text)\\n\\n    def __getattr__(self, key):\\n        \\\"\\\"\\\"Allows attribute-like access to the data dictionary.\\\"\\\"\\\"\\n        try:\\n            if key.startswith(\\\"__\\\"):\\n                return self.__getattribute__(key)\\n            if key in {\\\"data\\\", \\\"text_key\\\"} or key.startswith(\\\"_\\\"):\\n                return super().__getattr__(key)\\n            return self.data[key]\\n        except KeyError as e:\\n            # Fallback to default behavior to raise AttributeError for undefined attributes\\n            msg = f\\\"'{type(self).__name__}' object has no attribute '{key}'\\\"\\n            raise AttributeError(msg) from e\\n\\n    def __setattr__(self, key, value) -> None:\\n        \\\"\\\"\\\"Set attribute-like values in the data dictionary.\\n\\n        Allows attribute-like setting of values in the data dictionary.\\n        while still allowing direct assignment to class attributes.\\n        \\\"\\\"\\\"\\n        # Respect property descriptors defined on subclasses (e.g., Message.text)\\n        if key not in {\\\"data\\\", \\\"text_key\\\"} and not key.startswith(\\\"_\\\"):\\n            for klass in type(self).__mro__:\\n                attr = klass.__dict__.get(key)\\n                if isinstance(attr, property) and attr.fset is not None:\\n                    attr.fset(self, value)\\n                    return\\n                if attr is not None:\\n                    break  # Found a non-property attribute, stop looking\\n\\n        if key in {\\\"data\\\", \\\"text_key\\\"} or key.startswith(\\\"_\\\"):\\n            super().__setattr__(key, value)\\n        elif key in type(self).model_fields:\\n            self.data[key] = value\\n            super().__setattr__(key, value)\\n        else:\\n            self.data[key] = value\\n\\n    def __delattr__(self, key) -> None:\\n        \\\"\\\"\\\"Allows attribute-like deletion from the data dictionary.\\\"\\\"\\\"\\n        if key in {\\\"data\\\", \\\"text_key\\\"} or key.startswith(\\\"_\\\"):\\n            super().__delattr__(key)\\n        else:\\n            del self.data[key]\\n\\n    def __deepcopy__(self, memo):\\n        \\\"\\\"\\\"Custom deepcopy implementation to handle copying of the JSON object.\\\"\\\"\\\"\\n        # Create a new JSON object with a deep copy of the data dictionary\\n        return JSON(data=copy.deepcopy(self.data, memo), text_key=self.text_key, default_value=self.default_value)\\n\\n    # check which attributes the JSON has by checking the keys in the data dictionary\\n    def __dir__(self):\\n        return super().__dir__() + list(self.data.keys())\\n\\n    def __str__(self) -> str:\\n        # return a JSON string representation of the JSON attributes\\n        try:\\n            data = {k: v.to_json() if hasattr(v, \\\"to_json\\\") else v for k, v in self.data.items()}\\n            return serialize_data(data)  # use the custom serializer\\n        except Exception:  # noqa: BLE001\\n            logger.debug(\\\"Error converting JSON to string\\\", exc_info=True)\\n            return str(self.data)\\n\\n    def __contains__(self, key) -> bool:\\n        return key in self.data\\n\\n    def __eq__(self, /, other):\\n        return isinstance(other, JSON) and self.data == other.data\\n\\n    def filter_data(self, filter_str: str) -> JSON:\\n        \\\"\\\"\\\"Filters the data dictionary based on the filter string.\\n\\n        Args:\\n            filter_str (str): The filter string to apply to the data dictionary.\\n\\n        Returns:\\n            JSON: The filtered JSON.\\n        \\\"\\\"\\\"\\n        from lfx.template.utils import apply_json_filter\\n\\n        return apply_json_filter(self.data, filter_str)\\n\\n    def to_message(self) -> Message:\\n        from lfx.schema.message import Message  # Local import to avoid circular import\\n\\n        if self.text_key in self.data:\\n            return Message(text=self.get_text())\\n        return Message(text=str(self.data))\\n\\n    def to_dataframe(self) -> Table:\\n        from lfx.schema.dataframe import DataFrame  # Local import to avoid circular import\\n\\n        data_dict = self.data\\n        # If data contains only one key and the value is a list of dictionaries, convert to DataFrame\\n        if (\\n            len(data_dict) == 1\\n            and isinstance(next(iter(data_dict.values())), list)\\n            and all(isinstance(item, dict) for item in next(iter(data_dict.values())))\\n        ):\\n            return DataFrame(data=next(iter(data_dict.values())))\\n        return DataFrame(data=[self])\\n\\n    def __repr__(self) -> str:\\n        \\\"\\\"\\\"Return string representation of the JSON object.\\\"\\\"\\\"\\n        return f\\\"JSON(text_key={self.text_key!r}, data={self.data!r}, default_value={self.default_value!r})\\\"\\n\\n    def __hash__(self) -> int:\\n        \\\"\\\"\\\"Return hash of the JSON object based on its string representation.\\\"\\\"\\\"\\n        return hash(self.__repr__())\\n\\n\\n# Data class is maintained for backwards compatibility - it is now an alias to JSON\\n# All new code should use JSON instead of Data\\nData = JSON\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/dataframe.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"54308d696d08eb068918501d9f22419bc00fe11909de9e1c8002ed214e8b9185\",\"content\":\"\\\"\\\"\\\"Table class for lfx package - pandas DataFrame subclass for Langflow data structures.\\n\\nThis module provides the Table class (formerly DataFrame) as the base type for tabular data in Langflow.\\nDataFrame is maintained as an alias for backwards compatibility.\\n\\\"\\\"\\\"\\n\\nfrom typing import TYPE_CHECKING, cast\\n\\nimport pandas as pd\\nfrom langchain_core.documents import Document\\nfrom pandas import DataFrame as pandas_DataFrame\\n\\nfrom lfx.schema.data import Data\\n\\nif TYPE_CHECKING:\\n    from lfx.schema.message import Message\\n\\n\\nclass Table(pandas_DataFrame):\\n    \\\"\\\"\\\"A pandas DataFrame subclass specialized for handling collections of JSON objects.\\n\\n    This is the base type for Langflow tabular data structures, replacing the legacy DataFrame class.\\n    DataFrame is maintained as an alias for backwards compatibility.\\n\\n    This class extends pandas.DataFrame to provide seamless integration between\\n    Langflow's JSON objects and pandas' powerful data manipulation capabilities.\\n\\n    Args:\\n        data: Input data in various formats:\\n            - List[Data]: List of Data/JSON objects\\n            - List[Dict]: List of dictionaries\\n            - Dict: Dictionary of arrays/lists\\n            - pandas.DataFrame: Existing DataFrame\\n            - Any format supported by pandas.DataFrame\\n        **kwargs: Additional arguments passed to pandas.DataFrame constructor\\n\\n    Examples:\\n        >>> # From Data objects\\n        >>> dataset = Table([Data(data={\\\"name\\\": \\\"John\\\"}), Data(data={\\\"name\\\": \\\"Jane\\\"})])\\n\\n        >>> # From dictionaries\\n        >>> dataset = Table([{\\\"name\\\": \\\"John\\\"}, {\\\"name\\\": \\\"Jane\\\"}])\\n\\n        >>> # From dictionary of lists\\n        >>> dataset = Table({\\\"name\\\": [\\\"John\\\", \\\"Jane\\\"], \\\"age\\\": [30, 25]})\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        data: list[dict] | list[Data] | pd.DataFrame | None = None,\\n        text_key: str = \\\"text\\\",\\n        default_value: str = \\\"\\\",\\n        **kwargs,\\n    ):\\n        # Initialize pandas DataFrame first without data\\n        super().__init__(**kwargs)  # Removed data parameter\\n\\n        # Store attributes as private members to avoid conflicts with pandas\\n        self._text_key = text_key\\n        self._default_value = default_value\\n\\n        if data is None:\\n            return\\n\\n        if isinstance(data, list):\\n            if all(isinstance(x, Data) for x in data):\\n                data = [d.data for d in data if hasattr(d, \\\"data\\\")]\\n            elif not all(isinstance(x, dict) for x in data):\\n                msg = \\\"List items must be either all Data objects or all dictionaries\\\"\\n                raise ValueError(msg)\\n            self._update(data, **kwargs)\\n        elif isinstance(data, dict | pd.DataFrame):  # Fixed type check syntax\\n            self._update(data, **kwargs)\\n\\n    def _update(self, data, **kwargs):\\n        \\\"\\\"\\\"Helper method to update Table with new data.\\\"\\\"\\\"\\n        new_df = pd.DataFrame(data, **kwargs)\\n        self._update_inplace(new_df)\\n\\n    # Update property accessors\\n    @property\\n    def text_key(self) -> str:\\n        return self._text_key\\n\\n    @text_key.setter\\n    def text_key(self, value: str) -> None:\\n        if value not in self.columns:\\n            msg = f\\\"Text key '{value}' not found in Table columns\\\"\\n            raise ValueError(msg)\\n        self._text_key = value\\n\\n    @property\\n    def default_value(self) -> str:\\n        return self._default_value\\n\\n    @default_value.setter\\n    def default_value(self, value: str) -> None:\\n        self._default_value = value\\n\\n    def to_data_list(self) -> list[Data]:\\n        \\\"\\\"\\\"Converts the Table back to a list of Data objects.\\\"\\\"\\\"\\n        list_of_dicts = self.to_dict(orient=\\\"records\\\")\\n        # suggested change: [Data(**row) for row in list_of_dicts]\\n        return [Data(data=row) for row in list_of_dicts]\\n\\n    def add_row(self, data: dict | Data) -> \\\"Table\\\":\\n        \\\"\\\"\\\"Adds a single row to the dataset.\\n\\n        Args:\\n            data: Either a Data object or a dictionary to add as a new row\\n\\n        Returns:\\n            Table: A new Table with the added row\\n\\n        Example:\\n            >>> dataset = Table([{\\\"name\\\": \\\"John\\\"}])\\n            >>> dataset = dataset.add_row({\\\"name\\\": \\\"Jane\\\"})\\n        \\\"\\\"\\\"\\n        if isinstance(data, Data):\\n            data = data.data\\n        new_df = self._constructor([data])\\n        return cast(\\\"Table\\\", pd.concat([self, new_df], ignore_index=True))\\n\\n    def add_rows(self, data: list[dict | Data]) -> \\\"Table\\\":\\n        \\\"\\\"\\\"Adds multiple rows to the dataset.\\n\\n        Args:\\n            data: List of Data objects or dictionaries to add as new rows\\n\\n        Returns:\\n            Table: A new Table with the added rows\\n        \\\"\\\"\\\"\\n        processed_data = []\\n        for item in data:\\n            if isinstance(item, Data):\\n                processed_data.append(item.data)\\n            else:\\n                processed_data.append(item)\\n        new_df = self._constructor(processed_data)\\n        return cast(\\\"Table\\\", pd.concat([self, new_df], ignore_index=True))\\n\\n    @property\\n    def _constructor(self):\\n        def _c(*args, **kwargs):\\n            return Table(*args, **kwargs).__finalize__(self)\\n\\n        return _c\\n\\n    def __bool__(self):\\n        \\\"\\\"\\\"Truth value testing for the Table.\\n\\n        Returns True if the Table has at least one row, False otherwise.\\n        \\\"\\\"\\\"\\n        return not self.empty\\n\\n    def __repr__(self) -> str:\\n        # Disable column-width truncation so agent observations include full content.\\n        # Pandas default (50 chars) silently truncates Memory Base / Knowledge Base results.\\n        with pd.option_context(\\\"display.max_colwidth\\\", None):\\n            return super().__repr__()\\n\\n    __str__ = __repr__\\n\\n    __hash__ = None  # Tables are mutable and shouldn't be hashable\\n\\n    _CONTENT_COLUMNS = frozenset(\\n        {\\n            \\\"text\\\",\\n            \\\"content\\\",\\n            \\\"output\\\",\\n            \\\"summary\\\",\\n            \\\"result\\\",\\n            \\\"answer\\\",\\n            \\\"response\\\",\\n        }\\n    )\\n    _SYSTEM_COLUMNS = frozenset(\\n        {\\n            \\\"timestamp\\\",\\n            \\\"sender\\\",\\n            \\\"sender_name\\\",\\n            \\\"session_id\\\",\\n            \\\"context_id\\\",\\n            \\\"flow_id\\\",\\n            \\\"files\\\",\\n            \\\"error\\\",\\n            \\\"edit\\\",\\n        }\\n    )\\n\\n    def smart_column_order(self) -> \\\"DataFrame\\\":\\n        \\\"\\\"\\\"Reorder columns: content-like columns first, system metadata last.\\\"\\\"\\\"\\n        if self.empty:\\n            return self\\n\\n        content_cols = [c for c in self.columns if c.lower() in self._CONTENT_COLUMNS]\\n        system_cols = [c for c in self.columns if c.lower() in self._SYSTEM_COLUMNS or c.startswith(\\\"_\\\")]\\n        regular_cols = [c for c in self.columns if c not in content_cols and c not in system_cols]\\n\\n        new_order = content_cols + regular_cols + system_cols\\n        return self[new_order]\\n\\n    def to_lc_documents(self) -> list[Document]:\\n        \\\"\\\"\\\"Converts the Table to a list of Documents.\\n\\n        Returns:\\n            list[Document]: The converted list of Documents.\\n        \\\"\\\"\\\"\\n        list_of_dicts = self.to_dict(orient=\\\"records\\\")\\n        documents = []\\n        for row in list_of_dicts:\\n            data_copy = row.copy()\\n            text = data_copy.pop(self._text_key, self._default_value)\\n            if isinstance(text, str):\\n                documents.append(Document(page_content=text, metadata=data_copy))\\n            else:\\n                documents.append(Document(page_content=str(text), metadata=data_copy))\\n        return documents\\n\\n    def _docs_to_dataframe(self, docs):\\n        \\\"\\\"\\\"Converts a list of Documents to a Table.\\n\\n        Args:\\n            docs: List of Document objects\\n\\n        Returns:\\n            Table: A new Table with the converted Documents\\n        \\\"\\\"\\\"\\n        return Table(docs)\\n\\n    def __eq__(self, other):\\n        \\\"\\\"\\\"Override equality to handle comparison with empty Tables and non-Table objects.\\\"\\\"\\\"\\n        if self.empty:\\n            return False\\n        if isinstance(other, list) and not other:  # Empty list case\\n            return False\\n        if not isinstance(other, Table | pd.DataFrame):  # Non-Table case\\n            return False\\n        return super().__eq__(other)\\n\\n    def to_data(self) -> Data:\\n        \\\"\\\"\\\"Convert this Table to a Data object.\\n\\n        Returns:\\n            Data: A Data object containing the Table records under 'results' key.\\n        \\\"\\\"\\\"\\n        dict_list = self.to_dict(orient=\\\"records\\\")\\n        return Data(data={\\\"results\\\": dict_list})\\n\\n    def to_message(self) -> \\\"Message\\\":\\n        from lfx.schema.message import Message\\n\\n        # Process Table similar to the _safe_convert method\\n        # Remove empty rows\\n        processed_df = self.dropna(how=\\\"all\\\")\\n        # Remove empty lines in each cell\\n        processed_df = processed_df.replace(r\\\"^\\\\s*$\\\", \\\"\\\", regex=True)\\n        # Replace multiple newlines with a single newline\\n        processed_df = processed_df.replace(r\\\"\\\\n+\\\", \\\"\\\\n\\\", regex=True)\\n        # Replace pipe characters to avoid markdown table issues\\n        processed_df = processed_df.replace(r\\\"\\\\|\\\", r\\\"\\\\\\\\|\\\", regex=True)\\n        processed_df = processed_df.map(lambda x: str(x).replace(\\\"\\\\n\\\", \\\"<br/>\\\") if isinstance(x, str) else x)\\n        # Convert to markdown and wrap in a Message\\n        return Message(text=processed_df.to_markdown(index=False))\\n\\n\\n# DataFrame class is maintained for backwards compatibility - it is now an alias to Table\\n# All new code should use Table instead of DataFrame\\nDataFrame = Table\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/dotdict.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"77a4798eff15fe9c5a4145f740fe356734f3db06699d9d0e16cca515fdf12fe4\",\"content\":\"\\\"\\\"\\\"Dot-notation dictionary implementation copied from langflow for lfx package.\\\"\\\"\\\"\\n\\n\\nclass dotdict(dict):  # noqa: N801\\n    \\\"\\\"\\\"dotdict allows accessing dictionary elements using dot notation (e.g., dict.key instead of dict['key']).\\n\\n    It automatically converts nested dictionaries into dotdict instances, enabling dot notation on them as well.\\n\\n    Note:\\n        - Only keys that are valid attribute names (e.g., strings that could be variable names) are accessible via dot\\n          notation.\\n        - Keys which are not valid Python attribute names or collide with the dict method names (like 'items', 'keys')\\n          should be accessed using the traditional dict['key'] notation.\\n    \\\"\\\"\\\"\\n\\n    def __getattr__(self, attr):\\n        \\\"\\\"\\\"Override dot access to behave like dictionary lookup. Automatically convert nested dicts to dotdicts.\\n\\n        Args:\\n            attr (str): Attribute to access.\\n\\n        Returns:\\n            The value associated with 'attr' in the dictionary, converted to dotdict if it is a dict.\\n\\n        Raises:\\n            AttributeError: If the attribute is not found in the dictionary.\\n        \\\"\\\"\\\"\\n        try:\\n            value = self[attr]\\n            if isinstance(value, dict) and not isinstance(value, dotdict):\\n                value = dotdict(value)\\n                self[attr] = value  # Update self to nest dotdict for future accesses\\n        except KeyError as e:\\n            msg = f\\\"'dotdict' object has no attribute '{attr}'\\\"\\n            raise AttributeError(msg) from e\\n        else:\\n            return value\\n\\n    def __setattr__(self, key, value) -> None:\\n        \\\"\\\"\\\"Override attribute setting to work as dictionary item assignment.\\n\\n        Args:\\n            key (str): The key under which to store the value.\\n            value: The value to store in the dictionary.\\n        \\\"\\\"\\\"\\n        if isinstance(value, dict) and not isinstance(value, dotdict):\\n            value = dotdict(value)\\n        self[key] = value\\n\\n    def __delattr__(self, key) -> None:\\n        \\\"\\\"\\\"Override attribute deletion to work as dictionary item deletion.\\n\\n        Args:\\n            key (str): The key of the item to delete from the dictionary.\\n\\n        Raises:\\n            AttributeError: If the key is not found in the dictionary.\\n        \\\"\\\"\\\"\\n        try:\\n            del self[key]\\n        except KeyError as e:\\n            msg = f\\\"'dotdict' object has no attribute '{key}'\\\"\\n            raise AttributeError(msg) from e\\n\\n    def __missing__(self, key):\\n        \\\"\\\"\\\"Handle missing keys by returning an empty dotdict. This allows chaining access without raising KeyError.\\n\\n        Args:\\n            key: The missing key.\\n\\n        Returns:\\n            An empty dotdict instance for the given missing key.\\n        \\\"\\\"\\\"\\n        return dotdict()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/encoders.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"49f44ba96f7c8ccd6e2ddc1d28a25d37969711998c39c71032b74164123ad1eb\",\"content\":\"from collections.abc import Callable\\nfrom datetime import datetime\\n\\n\\ndef encode_callable(obj: Callable):\\n    return obj.__name__ if hasattr(obj, \\\"__name__\\\") else str(obj)\\n\\n\\ndef encode_datetime(obj: datetime):\\n    return obj.strftime(\\\"%Y-%m-%d %H:%M:%S.%f %Z\\\")\\n\\n\\nCUSTOM_ENCODERS = {Callable: encode_callable, datetime: encode_datetime}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/image.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9fcb626ad229bde9cc00dbd9b75621e6f7a85aa58dff0505e138c7cb8e81d3d1\",\"content\":\"import base64\\nfrom pathlib import Path\\n\\nimport aiofiles\\nfrom PIL import Image as PILImage\\nfrom platformdirs import user_cache_dir\\nfrom pydantic import BaseModel\\n\\nfrom lfx.services.deps import get_storage_service\\nfrom lfx.utils.image import create_image_content_dict\\n\\nIMAGE_ENDPOINT = \\\"/files/images/\\\"\\n\\n\\ndef is_image_file(file_path) -> bool:\\n    \\\"\\\"\\\"Check if a file is a valid image.\\\"\\\"\\\"\\n    try:\\n        with PILImage.open(file_path) as img:\\n            img.verify()  # Verify that it is, in fact, an image\\n    except (OSError, SyntaxError):\\n        return False\\n    return True\\n\\n\\ndef get_file_paths(files: list[str | dict]):\\n    \\\"\\\"\\\"Get file paths for a list of files.\\\"\\\"\\\"\\n    if not files:\\n        return []\\n\\n    storage_service = get_storage_service()\\n    if not storage_service:\\n        # Extract paths from dicts if present\\n\\n        extracted_files = []\\n        cache_dir = Path(user_cache_dir(\\\"langflow\\\"))\\n\\n        for file in files:\\n            if not file:  # Skip empty/None files\\n                continue\\n\\n            # Handle Image objects, dicts, and strings\\n            if isinstance(file, dict) and \\\"path\\\" in file:\\n                file_path = file[\\\"path\\\"]\\n            elif hasattr(file, \\\"path\\\") and file.path:\\n                file_path = file.path\\n            else:\\n                file_path = file\\n\\n            if not file_path:  # Skip empty paths\\n                continue\\n\\n            # If it's a relative path like \\\"flow_id/filename\\\", resolve it to cache dir\\n            path = Path(file_path)\\n            if not path.is_absolute() and not path.exists():\\n                # Check if it exists in the cache directory\\n                cache_path = cache_dir / file_path\\n                if cache_path.exists():\\n                    extracted_files.append(str(cache_path))\\n                else:\\n                    # Keep the original path if not found\\n                    extracted_files.append(file_path)\\n            else:\\n                extracted_files.append(file_path)\\n        return extracted_files\\n\\n    file_paths = []\\n    for file in files:\\n        # Handle dict case\\n        if storage_service is None:\\n            continue\\n\\n        if not file:  # Skip empty/None files\\n            continue\\n\\n        if isinstance(file, dict) and \\\"path\\\" in file:\\n            file_path_str = file[\\\"path\\\"]\\n        elif hasattr(file, \\\"path\\\") and file.path:\\n            file_path_str = file.path\\n        else:\\n            file_path_str = file\\n\\n        if not file_path_str:  # Skip empty paths\\n            continue\\n\\n        flow_id, file_name = storage_service.parse_file_path(file_path_str)\\n\\n        if not file_name:  # Skip if no filename\\n            continue\\n\\n        file_paths.append(storage_service.build_full_path(flow_id=flow_id, file_name=file_name))\\n    return file_paths\\n\\n\\nasync def get_files(\\n    file_paths: list[str],\\n    *,\\n    convert_to_base64: bool = False,\\n):\\n    \\\"\\\"\\\"Get files from storage service.\\\"\\\"\\\"\\n    if not file_paths:\\n        return []\\n\\n    storage_service = get_storage_service()\\n    if not storage_service:\\n        # For testing purposes, read files directly when no storage service\\n        file_objects: list[str | bytes] = []\\n        for file_path_str in file_paths:\\n            if not file_path_str:  # Skip empty paths\\n                continue\\n\\n            file_path = Path(file_path_str)\\n            if file_path.exists():\\n                # Use async read for compatibility\\n                try:\\n                    async with aiofiles.open(file_path, \\\"rb\\\") as f:\\n                        file_content = await f.read()\\n                    if convert_to_base64:\\n                        file_base64 = base64.b64encode(file_content).decode(\\\"utf-8\\\")\\n                        file_objects.append(file_base64)\\n                    else:\\n                        file_objects.append(file_content)\\n                except Exception as e:\\n                    msg = f\\\"Error reading file {file_path}: {e}\\\"\\n                    raise FileNotFoundError(msg) from e\\n            else:\\n                msg = f\\\"File not found: {file_path}\\\"\\n                raise FileNotFoundError(msg)\\n        return file_objects\\n\\n    file_objects: list[str | bytes] = []\\n    for file in file_paths:\\n        if not file:  # Skip empty file paths\\n            continue\\n\\n        flow_id, file_name = storage_service.parse_file_path(file)\\n\\n        if not file_name:  # Skip if no filename\\n            continue\\n\\n        if not storage_service:\\n            continue\\n\\n        try:\\n            file_object = await storage_service.get_file(flow_id=flow_id, file_name=file_name)\\n            if convert_to_base64:\\n                file_base64 = base64.b64encode(file_object).decode(\\\"utf-8\\\")\\n                file_objects.append(file_base64)\\n            else:\\n                file_objects.append(file_object)\\n        except Exception as e:\\n            msg = f\\\"Error getting file {file} from storage: {e}\\\"\\n            raise FileNotFoundError(msg) from e\\n    return file_objects\\n\\n\\nclass Image(BaseModel):\\n    \\\"\\\"\\\"Image model for lfx package.\\\"\\\"\\\"\\n\\n    path: str | None = None\\n    url: str | None = None\\n\\n    def to_base64(self):\\n        \\\"\\\"\\\"Convert image to base64 string.\\\"\\\"\\\"\\n        if self.path:\\n            files = get_files([self.path], convert_to_base64=True)\\n            if not files:\\n                msg = f\\\"No files found or file could not be converted to base64: {self.path}\\\"\\n                raise ValueError(msg)\\n            return files[0]\\n        msg = \\\"Image path is not set.\\\"\\n        raise ValueError(msg)\\n\\n    def to_content_dict(self, flow_id: str | None = None):\\n        \\\"\\\"\\\"Convert image to content dictionary.\\n\\n        Args:\\n            flow_id: Optional flow ID to prepend to the path if it doesn't contain one\\n        \\\"\\\"\\\"\\n        if not self.path:\\n            msg = \\\"Image path is not set.\\\"\\n            raise ValueError(msg)\\n\\n        # If the path doesn't contain a \\\"/\\\" and we have a flow_id, prepend it\\n        image_path = self.path\\n        if flow_id and \\\"/\\\" not in self.path:\\n            image_path = f\\\"{flow_id}/{self.path}\\\"\\n\\n        # Use the utility function that properly handles the conversion\\n        return create_image_content_dict(image_path, None, None)\\n\\n    def get_url(self) -> str:\\n        \\\"\\\"\\\"Get the URL for the image.\\\"\\\"\\\"\\n        return f\\\"{IMAGE_ENDPOINT}{self.path}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/json_schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"98834af6ed4c8514b33295a1c184d249c24c0086078239f23e4ccde9949531e7\",\"content\":\"\\\"\\\"\\\"JSON Schema utilities for LFX.\\\"\\\"\\\"\\n\\nfrom typing import Any\\n\\nfrom pydantic import AliasChoices, BaseModel, ConfigDict, Field, create_model\\n\\nfrom lfx.log.logger import logger\\n\\nNULLABLE_TYPE_LENGTH = 2  # Number of types in a nullable union (the type itself + null)\\n\\n\\ndef _snake_to_camel(name: str) -> str:\\n    \\\"\\\"\\\"Convert snake_case to camelCase, preserving leading/trailing underscores.\\\"\\\"\\\"\\n    if not name:\\n        return name\\n\\n    # Handle leading underscores\\n    leading = \\\"\\\"\\n    start_idx = 0\\n    while start_idx < len(name) and name[start_idx] == \\\"_\\\":\\n        leading += \\\"_\\\"\\n        start_idx += 1\\n\\n    # Handle trailing underscores\\n    trailing = \\\"\\\"\\n    end_idx = len(name)\\n    while end_idx > start_idx and name[end_idx - 1] == \\\"_\\\":\\n        trailing += \\\"_\\\"\\n        end_idx -= 1\\n\\n    # Convert the middle part\\n    middle = name[start_idx:end_idx]\\n    if not middle:\\n        return name  # All underscores\\n\\n    components = middle.split(\\\"_\\\")\\n    camel = components[0] + \\\"\\\".join(word.capitalize() for word in components[1:])\\n\\n    return leading + camel + trailing\\n\\n\\ndef create_input_schema_from_json_schema(schema: dict[str, Any]) -> type[BaseModel]:\\n    \\\"\\\"\\\"Dynamically build a Pydantic model from a JSON schema (with $defs).\\n\\n    Non-required fields become Optional[...] with default=None.\\n    \\\"\\\"\\\"\\n    if schema.get(\\\"type\\\") != \\\"object\\\":\\n        msg = \\\"Root schema must be type 'object'\\\"\\n        raise ValueError(msg)\\n\\n    defs: dict[str, dict[str, Any]] = schema.get(\\\"$defs\\\", {})\\n    model_cache: dict[str, type[BaseModel]] = {}\\n    # Tracks $def names currently being built to detect self-referential schemas\\n    building: set[str] = set()\\n    # Monotonic counter for anonymous nested-object models. Using len(model_cache)\\n    # is unsafe during recursive descent because the cache is populated only after\\n    # a build completes, causing concurrent in-progress models to collide on the\\n    # same name and falsely trigger the self-reference guard.\\n    anon_counter: list[int] = [0]\\n\\n    def _next_anon_name() -> str:\\n        n = anon_counter[0]\\n        anon_counter[0] += 1\\n        return f\\\"AnonModel{n}\\\"\\n\\n    def resolve_ref(s: dict[str, Any] | None) -> dict[str, Any]:\\n        \\\"\\\"\\\"Follow a $ref chain until you land on a real subschema.\\\"\\\"\\\"\\n        if s is None:\\n            return {}\\n        visited: set[str] = set()\\n        while \\\"$ref\\\" in s:\\n            ref_name = s[\\\"$ref\\\"].split(\\\"/\\\")[-1]\\n            if ref_name in visited:\\n                logger.warning(\\\"Parsing input schema: Circular $ref detected for '%s', treating as string\\\", ref_name)\\n                return {\\\"type\\\": \\\"string\\\"}\\n            visited.add(ref_name)\\n            s = defs.get(ref_name)\\n            if s is None:\\n                logger.warning(\\\"Parsing input schema: Definition '%s' not found\\\", ref_name)\\n                return {\\\"type\\\": \\\"string\\\"}\\n        return s\\n\\n    def parse_type(s: dict[str, Any] | None) -> Any:\\n        \\\"\\\"\\\"Map a JSON Schema subschema to a Python type (possibly nested).\\\"\\\"\\\"\\n        if s is None:\\n            return None\\n        # Preserve the original subschema so we can detect when an object was\\n        # reached via a named $ref and route it through _build_model's $ref branch\\n        # for stable naming and cache reuse.\\n        original = s\\n        s = resolve_ref(s)\\n\\n        if \\\"anyOf\\\" in s:\\n            # Handle common pattern for nullable types (anyOf with string and null)\\n            subtypes = [sub.get(\\\"type\\\") for sub in s[\\\"anyOf\\\"] if isinstance(sub, dict) and \\\"type\\\" in sub]\\n\\n            # Check if this is a simple nullable type (e.g., str | None)\\n            if len(subtypes) == NULLABLE_TYPE_LENGTH and \\\"null\\\" in subtypes:\\n                # Get the non-null type\\n                non_null_type = next(t for t in subtypes if t != \\\"null\\\")\\n                # Map it to Python type\\n                if isinstance(non_null_type, str):\\n                    return {\\n                        \\\"string\\\": str,\\n                        \\\"integer\\\": int,\\n                        \\\"number\\\": float,\\n                        \\\"boolean\\\": bool,\\n                        \\\"object\\\": dict,\\n                        \\\"array\\\": list,\\n                    }.get(non_null_type, Any)\\n                return Any\\n\\n            # For other anyOf cases, use the first non-null type\\n            subtypes = [parse_type(sub) for sub in s[\\\"anyOf\\\"]]\\n            non_null_types = [t for t in subtypes if t is not None and t is not type(None)]\\n            if non_null_types:\\n                return non_null_types[0]\\n            return str\\n\\n        t = s.get(\\\"type\\\", \\\"any\\\")  # Use string \\\"any\\\" as default instead of Any type\\n        if isinstance(t, list):\\n            # JSON Schema: \\\"type\\\": [\\\"string\\\", \\\"null\\\"] for nullable\\n            non_null = [x for x in t if x != \\\"null\\\" and isinstance(x, str)]\\n            if non_null:\\n                prim = {\\n                    \\\"string\\\": str,\\n                    \\\"integer\\\": int,\\n                    \\\"number\\\": float,\\n                    \\\"boolean\\\": bool,\\n                    \\\"object\\\": dict,\\n                    \\\"array\\\": list,\\n                }.get(non_null[0], Any)\\n                return prim | None if \\\"null\\\" in t else prim\\n            return Any\\n        if t == \\\"array\\\":\\n            item_schema = s.get(\\\"items\\\", {})\\n            schema_type: Any = parse_type(item_schema)\\n            return list[schema_type]\\n\\n        if t == \\\"object\\\":\\n            # Generic object (no properties) \u21d2 dict[str, Any] for free-form key-value pairs\\n            # This preserves nested dictionaries (fixes issue #9881)\\n            if not s.get(\\\"properties\\\"):\\n                return dict[str, Any]\\n            # If the object was reached via a named $ref, pass the original $ref-bearing\\n            # subschema so _build_model uses its $ref branch (stable name, cache reuse).\\n            if isinstance(original, dict) and \\\"$ref\\\" in original:\\n                return _build_model(_next_anon_name(), original)\\n            # Inline object with defined properties \u21d2 anonymous nested model\\n            return _build_model(_next_anon_name(), s)\\n\\n        # primitive fallback\\n        return {\\n            \\\"string\\\": str,\\n            \\\"integer\\\": int,\\n            \\\"number\\\": float,\\n            \\\"boolean\\\": bool,\\n            \\\"object\\\": dict,\\n            \\\"array\\\": list,\\n        }.get(t, Any)\\n\\n    def _build_model(name: str, subschema: dict[str, Any]) -> type[BaseModel]:\\n        \\\"\\\"\\\"Create (or fetch) a BaseModel subclass for the given object schema.\\\"\\\"\\\"\\n        # If this came via a named $ref, use that name. The recursive _build_model\\n        # call below handles `building` tracking and cache population itself, so we\\n        # must NOT pre-add `refname` to `building` here \u2014 doing so would cause the\\n        # recursive call to falsely see itself as self-referential and fall back to\\n        # dict on the very first visit of a non-recursive def.\\n        if \\\"$ref\\\" in subschema:\\n            refname = subschema[\\\"$ref\\\"].split(\\\"/\\\")[-1]\\n            if refname in model_cache:\\n                return model_cache[refname]\\n            # Already in progress (true self-reference encountered via $ref)\\n            if refname in building:\\n                logger.warning(\\\"Parsing input schema: Self-referential $ref '%s' detected, treating as dict\\\", refname)\\n                return dict  # type: ignore[return-value]\\n            target = defs.get(refname)\\n            if not target:\\n                msg = f\\\"Definition '{refname}' not found\\\"\\n                raise ValueError(msg)\\n            return _build_model(refname, target)\\n\\n        # Named anonymous or inline: avoid clashes by name\\n        if name in model_cache:\\n            return model_cache[name]\\n        # Self-referential: this model name is already being built \u2014 fall back to dict\\n        if name in building:\\n            logger.warning(\\\"Parsing input schema: Self-referential model '%s' detected, treating as dict\\\", name)\\n            return dict  # type: ignore[return-value]\\n\\n        building.add(name)\\n        try:\\n            props = subschema.get(\\\"properties\\\", {})\\n            reqs = {r for r in (subschema.get(\\\"required\\\") or []) if isinstance(r, str)}\\n            fields: dict[str, Any] = {}\\n\\n            for prop_name, prop_schema in props.items():\\n                py_type = parse_type(prop_schema)\\n                is_required = prop_name in reqs\\n                if not is_required:\\n                    py_type = py_type | None\\n                    default = prop_schema.get(\\\"default\\\", None)\\n                else:\\n                    default = ...  # required by Pydantic\\n\\n                # Add alias for camelCase if field name is snake_case\\n                field_kwargs = {\\\"description\\\": prop_schema.get(\\\"description\\\")}\\n                if \\\"_\\\" in prop_name:\\n                    camel_case_name = _snake_to_camel(prop_name)\\n                    if camel_case_name != prop_name:  # Only add alias if it's different\\n                        field_kwargs[\\\"validation_alias\\\"] = AliasChoices(prop_name, camel_case_name)\\n\\n                fields[prop_name] = (py_type, Field(default, **field_kwargs))\\n\\n            # Preserve extras unless schema sets additionalProperties:false (#9881, #10975).\\n            extra_mode = \\\"ignore\\\" if subschema.get(\\\"additionalProperties\\\") is False else \\\"allow\\\"\\n            model_cls = create_model(name, __config__=ConfigDict(extra=extra_mode), **fields)\\n        finally:\\n            building.discard(name)\\n        model_cache[name] = model_cls\\n        return model_cls\\n\\n    # build the top - level \\\"InputSchema\\\" from the root properties\\n    top_props = schema.get(\\\"properties\\\", {})\\n    top_reqs = {r for r in (schema.get(\\\"required\\\") or []) if isinstance(r, str)}\\n    top_fields: dict[str, Any] = {}\\n\\n    for fname, fdef in top_props.items():\\n        py_type = parse_type(fdef)\\n        if fname not in top_reqs:\\n            py_type = py_type | None\\n            default = fdef.get(\\\"default\\\", None)\\n        else:\\n            default = ...\\n\\n        # Add alias for camelCase if field name is snake_case\\n        field_kwargs = {\\\"description\\\": fdef.get(\\\"description\\\")}\\n        if \\\"_\\\" in fname:\\n            camel_case_name = _snake_to_camel(fname)\\n            if camel_case_name != fname:  # Only add alias if it's different\\n                field_kwargs[\\\"validation_alias\\\"] = AliasChoices(fname, camel_case_name)\\n\\n        top_fields[fname] = (py_type, Field(default, **field_kwargs))\\n\\n    # Same JSON Schema rule applies at the root: preserve extras unless explicitly forbidden.\\n    top_extra_mode = \\\"ignore\\\" if schema.get(\\\"additionalProperties\\\") is False else \\\"allow\\\"\\n    return create_model(\\\"InputSchema\\\", __config__=ConfigDict(extra=top_extra_mode), **top_fields)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/legacy_render.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ce781330706e1f0ca2a51aa0bb67582765893387f4f4a1966fb8f4037713d8a4\",\"content\":\"\\\"\\\"\\\"Project the new content_blocks model back onto the release-1.11.0 (v1) wire shape.\\n\\nThe in-memory ``Message`` is the source of truth and carries the new content_blocks\\nunion: groups are tagged ``type=\\\"group\\\"``, every node carries ``id``/``contents``,\\nand an agent's final answer is a trailing top-level ``TextContent``. The v1 API must\\nkeep emitting the exact pre-1.11.0 shape, so these pure helpers run only at the v1\\nboundary (the v1 read models, ``MessageResponse.from_message``, the v1 event stream,\\nand the v1 openai-responses consumer). The v2 (AG-UI / workflows) path serializes the\\nlive ``Message`` directly and keeps the new shape, so it must never call these.\\n\\nBaseline v1 invariants reproduced here:\\n- ``content_blocks`` holds groups only (baseline never stored a top-level text leaf).\\n- each group is ``{title, contents, allow_markdown, media_url}`` in that order.\\n- leaves carry no ``id`` / ``contents`` keys.\\n- an agent's answer lives inside the \\\"Agent Steps\\\" group as a trailing \\\"Output\\\" leaf.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\n\\n_OUTPUT_HEADER = {\\\"title\\\": \\\"Output\\\", \\\"icon\\\": \\\"MessageSquare\\\"}\\n_AGENT_STEPS_TITLE = \\\"Agent Steps\\\"\\n\\n\\ndef legacy_text(message) -> str:\\n    \\\"\\\"\\\"The v1 ``text`` value: always a string. A pending stream/iterator renders as \\\"\\\".\\\"\\\"\\\"\\n    text = message.text\\n    return text if isinstance(text, str) else \\\"\\\"\\n\\n\\ndef _is_group(block) -> bool:\\n    if not isinstance(block, dict):\\n        return False\\n    if block.get(\\\"type\\\") == \\\"group\\\":\\n        return True\\n    # A legacy group dict read back from the DB carries no discriminator.\\n    return \\\"title\\\" in block and \\\"contents\\\" in block and \\\"type\\\" not in block\\n\\n\\ndef _legacy_leaf(node: dict) -> dict:\\n    # Drop the two additive keys the new model puts on every leaf. ``id`` sat right\\n    # after ``type`` and ``contents`` right after ``header`` in the new node, so plain\\n    # deletion leaves the remaining keys in baseline order (type, duration, header, ...).\\n    return {k: v for k, v in node.items() if k not in (\\\"id\\\", \\\"contents\\\")}\\n\\n\\ndef _legacy_group(block: dict) -> dict:\\n    return {\\n        \\\"title\\\": block.get(\\\"title\\\"),\\n        \\\"contents\\\": [_legacy_leaf(c) for c in block.get(\\\"contents\\\") or []],\\n        \\\"allow_markdown\\\": block.get(\\\"allow_markdown\\\", True),\\n        \\\"media_url\\\": block.get(\\\"media_url\\\"),\\n    }\\n\\n\\ndef legacy_content_blocks(blocks) -> list[dict]:\\n    \\\"\\\"\\\"Project new-model content_blocks (serialized dicts) onto the v1 shape.\\n\\n    Groups are kept and rendered legacy; top-level text leaves are dropped because\\n    baseline never stored one. For an agent message (a group titled \\\"Agent Steps\\\")\\n    the relocated answer is folded back into that group as the trailing \\\"Output\\\"\\n    leaf, reproducing baseline. In every other case the answer text is carried by\\n    the message's ``text`` / ``data[\\\"text\\\"]`` and is not re-injected, which keeps\\n    generic ``.text=`` / multi-group / custom-titled-group messages untouched.\\n\\n    The agent renderer can also emit a flat, chronological log (interleaved text +\\n    tool_use leaves with no wrapping group). release-1.11.0 rendered agent steps\\n    inside an \\\"Agent Steps\\\" group, so reconstruct one here when the top level holds\\n    a ``tool_use`` leaf and no group exists, otherwise the group-only rule below\\n    would drop every tool call and leave v1 with an empty content_blocks. The gate\\n    is ``tool_use`` specifically (the agent-step signal), not \\\"any non-text leaf\\\":\\n    plain ``from_lc_message`` conversions put top-level ``usage`` / ``media`` /\\n    ``image`` leaves on ordinary replies, and those must stay text-only on the v1\\n    wire (a tool-less agent answer likewise carries no steps and projects to []).\\n    \\\"\\\"\\\"\\n    blocks = blocks or []\\n    groups = [b for b in blocks if _is_group(b)]\\n    leaves = [b for b in blocks if isinstance(b, dict) and not _is_group(b)]\\n\\n    if not groups and any(leaf.get(\\\"type\\\") == \\\"tool_use\\\" for leaf in leaves):\\n        return [\\n            {\\n                \\\"title\\\": _AGENT_STEPS_TITLE,\\n                \\\"contents\\\": [_legacy_leaf(leaf) for leaf in leaves],\\n                \\\"allow_markdown\\\": True,\\n                \\\"media_url\\\": None,\\n            }\\n        ]\\n\\n    answer = \\\"\\\".join(leaf.get(\\\"text\\\", \\\"\\\") for leaf in leaves if leaf.get(\\\"type\\\") == \\\"text\\\")\\n\\n    rendered: list[dict] = []\\n    folded = False\\n    for block in groups:\\n        group = _legacy_group(block)\\n        if not folded and answer and block.get(\\\"title\\\") == _AGENT_STEPS_TITLE:\\n            # ``duration`` is None on purpose: the new model relocates the answer to a\\n            # bare top-level TextContent (the text setter builds ``TextContent(text=...)``\\n            # with no duration), so the answer's timing baseline once stamped on the\\n            # in-group leaf is simply not present to carry through. This is a faithful\\n            # projection of what the message holds, not a dropped field.\\n            group[\\\"contents\\\"].append({\\\"type\\\": \\\"text\\\", \\\"duration\\\": None, \\\"header\\\": dict(_OUTPUT_HEADER), \\\"text\\\": answer})\\n            folded = True\\n        rendered.append(group)\\n    return rendered\\n\\n\\ndef project_payload_to_v1(obj):\\n    \\\"\\\"\\\"Recursively project every message ``content_blocks`` in a nested payload.\\n\\n    Used at v1 boundaries that serialize whole run results or stream events (the\\n    ``/run`` endpoint and its streaming ``end`` event) where messages sit at\\n    arbitrary depth. Pure: returns a new structure, the live objects are\\n    untouched. Wherever a dict carries a ``content_blocks`` list it is rendered\\n    to the legacy v1 shape, and a co-located non-string ``text`` is coerced to \\\"\\\".\\n    \\\"\\\"\\\"\\n    if isinstance(obj, dict):\\n        out = {}\\n        for key, value in obj.items():\\n            if key == \\\"content_blocks\\\" and isinstance(value, list):\\n                out[key] = legacy_content_blocks(value)\\n            else:\\n                out[key] = project_payload_to_v1(value)\\n        if isinstance(out.get(\\\"content_blocks\\\"), list) and \\\"text\\\" in out and not isinstance(out[\\\"text\\\"], str):\\n            # Reached only when text is non-string (the guard above); v1 text is\\n            # always a string, so a co-located non-string projects to \\\"\\\".\\n            out[\\\"text\\\"] = \\\"\\\"\\n        return out\\n    if isinstance(obj, list):\\n        return [project_payload_to_v1(item) for item in obj]\\n    return obj\\n\\n\\ndef render_v1_content_blocks(value):\\n    \\\"\\\"\\\"Normalize any content_blocks value to the legacy v1 shape.\\n\\n    Accepts ``ContentType`` model instances (live ``Message``), serialized dicts\\n    (a DB-row read), a JSON string, a list mixing those, or ``None``. ``None`` is\\n    returned unchanged; everything else is normalized to dicts and projected with\\n    :func:`legacy_content_blocks`. This is the single entry point every v1 wire\\n    model uses so the projection cannot drift between them.\\n    \\\"\\\"\\\"\\n    if value is None:\\n        return None\\n    if isinstance(value, str):\\n        value = json.loads(value)\\n    if not isinstance(value, list):\\n        return value\\n    dicts = []\\n    for block in value:\\n        if hasattr(block, \\\"model_dump\\\"):\\n            dicts.append(block.model_dump())\\n        elif isinstance(block, str):\\n            dicts.append(json.loads(block))\\n        else:\\n            dicts.append(block)\\n    return legacy_content_blocks(dicts)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/log.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4c84906b8e03e292fff803b0f69d2738f57eeece8f865fb4caba6e66286112c5\",\"content\":\"\\\"\\\"\\\"Log schema and types for lfx package.\\\"\\\"\\\"\\n\\nfrom typing import Any, Literal, TypeAlias\\n\\nfrom pydantic import BaseModel, field_serializer\\nfrom pydantic_core import PydanticSerializationError\\nfrom typing_extensions import Protocol\\n\\nfrom lfx.schema.message import ContentBlock, Message\\nfrom lfx.serialization.serialization import serialize\\n\\n# Simplified LoggableType without PlaygroundEvent dependency\\nLoggableType: TypeAlias = str | dict | list | int | float | bool | BaseModel | None\\n\\n\\nclass LogFunctionType(Protocol):\\n    \\\"\\\"\\\"Protocol for log function type.\\\"\\\"\\\"\\n\\n    def __call__(self, message: LoggableType | list[LoggableType], *, name: str | None = None) -> None: ...\\n\\n\\nclass SendMessageFunctionType(Protocol):\\n    \\\"\\\"\\\"Protocol for send message function type.\\\"\\\"\\\"\\n\\n    async def __call__(\\n        self,\\n        message: Message | None = None,\\n        text: str | None = None,\\n        background_color: str | None = None,\\n        text_color: str | None = None,\\n        icon: str | None = None,\\n        content_blocks: list[ContentBlock] | None = None,\\n        format_type: Literal[\\\"default\\\", \\\"error\\\", \\\"warning\\\", \\\"info\\\"] = \\\"default\\\",\\n        id_: str | None = None,\\n        *,\\n        allow_markdown: bool = True,\\n        skip_db_update: bool = False,\\n    ) -> Message: ...\\n\\n\\nclass OnTokenFunctionType(Protocol):\\n    \\\"\\\"\\\"Protocol for on token function type.\\\"\\\"\\\"\\n\\n    def __call__(self, data: dict[str, Any]) -> None: ...\\n\\n\\nclass Log(BaseModel):\\n    \\\"\\\"\\\"Log model for storing log messages with serialization support.\\\"\\\"\\\"\\n\\n    name: str\\n    message: LoggableType\\n    type: str\\n\\n    @field_serializer(\\\"message\\\")\\n    def serialize_message(self, value):\\n        \\\"\\\"\\\"Serialize the message field with fallback error handling.\\\"\\\"\\\"\\n        try:\\n            return serialize(value)\\n        except UnicodeDecodeError:\\n            return str(value)  # Fallback to string representation\\n        except PydanticSerializationError:\\n            return str(value)  # Fallback to string for Pydantic errors\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/message.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b6853ef4418d9dee78eb40d42ebe29c884df7462a9d910a5b9e577d559b0b3b6\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport json\\nimport re\\nimport traceback\\nfrom collections.abc import AsyncIterator, Iterator\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING, Annotated, Any, Literal\\nfrom uuid import UUID\\n\\nfrom fastapi.encoders import jsonable_encoder\\nfrom langchain_core.load import load\\nfrom langchain_core.messages import AIMessage, BaseMessage, HumanMessage, SystemMessage, ToolMessage\\nfrom pydantic import (\\n    BaseModel,\\n    ConfigDict,\\n    Field,\\n    ValidationError,\\n    computed_field,\\n    field_serializer,\\n    field_validator,\\n    model_serializer,\\n)\\n\\nif TYPE_CHECKING:\\n    from langchain_core.prompts.chat import BaseChatPromptTemplate\\n\\nfrom pydantic import TypeAdapter\\n\\nfrom lfx.base.prompts.utils import dict_values_to_string\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.content_block import ContentBlock, ContentType\\nfrom lfx.schema.content_types import ErrorContent, TextContent\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.image import Image, get_file_paths, is_image_file\\nfrom lfx.schema.legacy_render import legacy_text, render_v1_content_blocks\\nfrom lfx.schema.properties import Properties, Source\\nfrom lfx.schema.validators import str_to_timestamp_validator, timestamp_to_str, timestamp_to_str_validator\\nfrom lfx.utils.constants import MESSAGE_SENDER_AI, MESSAGE_SENDER_NAME_AI, MESSAGE_SENDER_NAME_USER, MESSAGE_SENDER_USER\\nfrom lfx.utils.image import create_image_content_dict\\nfrom lfx.utils.mustache_security import safe_mustache_render\\nfrom lfx.utils.secrets import is_secret_value\\n\\nif TYPE_CHECKING:\\n    from lfx.schema.dataframe import DataFrame\\n\\nMAX_ATTACHMENT_SIZE_BYTES: int = 50 * 1024 * 1024\\n\\n_CONTENT_TYPE_ADAPTER = TypeAdapter(ContentType)\\n\\n\\ndef _is_text_like_extension(file_path: Any) -> bool:\\n    \\\"\\\"\\\"Return True for files whose extension we recognize as plain text / structured text.\\n\\n    Used as a guard before falling back to latin-1 decoding in\\n    ``get_file_content_dicts`` \u2014 see ``read_text_file`` for the encoding chain.\\n    Files with no extension are treated as text-like so callers passing CLI-style\\n    stdin captures or extension-less plain text continue to work.\\n    \\\"\\\"\\\"\\n    from lfx.base.data.utils import TEXT_FILE_TYPES\\n\\n    try:\\n        suffix = Path(file_path).suffix.lstrip(\\\".\\\").lower()\\n    except (OSError, TypeError, ValueError):\\n        return False\\n    if not suffix:\\n        return True\\n    return suffix in TEXT_FILE_TYPES\\n\\n\\nclass Message(Data):\\n    \\\"\\\"\\\"Message schema for Langflow.\\n\\n    Message ID Semantics:\\n    - Messages only have an ID after being stored in the database\\n    - Messages that are skipped (via Component._should_skip_message) will NOT have an ID\\n    - Always use get_id(), has_id(), or require_id() methods to safely access the ID\\n    - Never access message.id directly without checking if it exists first\\n\\n    Safe ID Access Patterns:\\n    - Use get_id() when ID may or may not exist (returns None if missing)\\n    - Use has_id() to check if ID exists before operations that require it\\n    - Use require_id() when ID is required (raises ValueError if missing)\\n\\n    Example:\\n        message_id = message.get_id()  # Safe: returns None if no ID\\n        if message.has_id():\\n            # Safe to use message_id\\n            do_something_with_id(message_id)\\n    \\\"\\\"\\\"\\n\\n    model_config = ConfigDict(arbitrary_types_allowed=True)\\n    # Helper class to deal with image data\\n    text_key: str = \\\"text\\\"\\n    sender: str | None = None\\n    sender_name: str | None = None\\n    files: list[str | Image] | None = Field(default=[])\\n    session_id: str | UUID | None = Field(default=\\\"\\\")\\n    context_id: str | UUID | None = Field(default=\\\"\\\")\\n    run_id: str | UUID | None = Field(default=None)\\n    timestamp: Annotated[str, timestamp_to_str_validator] = Field(\\n        default_factory=lambda: datetime.now(timezone.utc).strftime(\\\"%Y-%m-%d %H:%M:%S.%f %Z\\\")\\n    )\\n    flow_id: str | UUID | None = None\\n    error: bool = Field(default=False)\\n    edit: bool = Field(default=False)\\n\\n    properties: Properties = Field(default_factory=Properties)\\n    category: Literal[\\\"message\\\", \\\"error\\\", \\\"warning\\\", \\\"info\\\"] | None = \\\"message\\\"\\n    content_blocks: list[ContentType] = Field(default_factory=list)\\n    duration: int | None = None\\n    session_metadata: dict | None = None\\n\\n    # Text is intentionally NOT auto-folded into content_blocks. Text-only\\n    # messages keep content_blocks empty for frontend backwards compatibility;\\n    # content_blocks is populated explicitly by components that produce rich\\n    # content (agents, multimodal, etc.). Streaming text (AsyncIterator/Iterator)\\n    # is left in data for model_post_init to handle.\\n\\n    @computed_field\\n    @property\\n    def text(self) -> str | AsyncIterator | Iterator:\\n        \\\"\\\"\\\"Extract text from content_blocks, or fall back to data dict.\\n\\n        Always returns a string. For streaming access, use `text_stream` property.\\n        \\\"\\\"\\\"\\n        stream = self.__dict__.get(\\\"_text_stream\\\")\\n        if stream is not None:\\n            return stream\\n        # If content_blocks has TextContent, derive from there\\n        text_from_blocks = \\\"\\\".join(b.text for b in self.content_blocks if isinstance(b, TextContent))\\n        if text_from_blocks:\\n            return text_from_blocks\\n        # Fall back to data dict (text-only messages, backwards compat)\\n        return self.data.get(self.text_key, \\\"\\\") or \\\"\\\"\\n\\n    @text.setter\\n    def text(self, value: str | AsyncIterator | Iterator | None) -> None:\\n        \\\"\\\"\\\"Replace text content or set a stream for later consumption.\\n\\n        Drops every existing TextContent in ``content_blocks`` and, if\\n        ``value`` is non-empty, appends a single TextContent at the end.\\n        Non-text blocks keep their position so ``content_blocks`` reflects\\n        chronological order: tool calls / reasoning / media first, final\\n        text last.\\n        \\\"\\\"\\\"\\n        if isinstance(value, AsyncIterator | Iterator):\\n            # Drop any existing TextContent (and the data[\\\"text\\\"] mirror) so the\\n            # getter doesn't return stale prior-round text while the stream sits\\n            # unconsumed. Non-text blocks keep their position.\\n            non_text = [b for b in self.content_blocks if not isinstance(b, TextContent)]\\n            object.__setattr__(self, \\\"content_blocks\\\", non_text)\\n            self.data[self.text_key] = \\\"\\\"\\n            object.__setattr__(self, \\\"_text_stream\\\", value)\\n            return\\n        # Clear any pending/exhausted stream\\n        self.__dict__.pop(\\\"_text_stream\\\", None)\\n        non_text = [b for b in self.content_blocks if not isinstance(b, TextContent)]\\n        if value:\\n            object.__setattr__(self, \\\"content_blocks\\\", [*non_text, TextContent(text=str(value))])\\n        else:\\n            object.__setattr__(self, \\\"content_blocks\\\", non_text)\\n        # Keep self.data[\\\"text\\\"] in sync for backwards compatibility\\n        self.data[self.text_key] = value or \\\"\\\"\\n\\n    @property\\n    def text_stream(self) -> AsyncIterator | Iterator | None:\\n        \\\"\\\"\\\"Access the pending text stream, if any. Used by streaming infrastructure.\\\"\\\"\\\"\\n        return self.__dict__.get(\\\"_text_stream\\\")\\n\\n    def get_text(self):\\n        \\\"\\\"\\\"Return text derived from content_blocks (overrides Data.get_text).\\\"\\\"\\\"\\n        return self.text\\n\\n    @model_serializer(mode=\\\"plain\\\", when_used=\\\"json\\\")\\n    def serialize_model(self):\\n        \\\"\\\"\\\"Override Data.serialize_model to filter out non-serializable stream objects.\\\"\\\"\\\"\\n        return {\\n            k: v.to_json() if hasattr(v, \\\"to_json\\\") else v\\n            for k, v in self.data.items()\\n            if not isinstance(v, AsyncIterator | Iterator)\\n        }\\n\\n    @field_validator(\\\"flow_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_flow_id(cls, value):\\n        if isinstance(value, UUID):\\n            value = str(value)\\n        return value\\n\\n    @field_validator(\\\"run_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_run_id(cls, value):\\n        if isinstance(value, UUID):\\n            value = str(value)\\n        return value\\n\\n    @field_validator(\\\"content_blocks\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_content_blocks(cls, value):\\n        def _parse_item(item):\\n            # Already a Pydantic model instance -- keep as-is\\n            if isinstance(item, BaseModel):\\n                return item\\n            # JSON string -- parse it\\n            if isinstance(item, str):\\n                parsed = json.loads(item)\\n                return _parse_item(parsed)\\n            # Dict -- discriminator handles every ContentType (including the\\n            # grouped ContentBlock with type=\\\"group\\\"). Legacy JSON without\\n            # an explicit \\\"type\\\" but with title+contents still validates as\\n            # a ContentBlock for backwards compat.\\n            if isinstance(item, dict):\\n                if \\\"type\\\" in item:\\n                    return _CONTENT_TYPE_ADAPTER.validate_python(item)\\n                if \\\"title\\\" in item and \\\"contents\\\" in item:\\n                    return ContentBlock.model_validate(item)\\n                # Untagged legacy/v1 text block: infer TextContent (else memory reload crashes).\\n                if \\\"text\\\" in item:\\n                    return TextContent.model_validate(item)\\n                return _CONTENT_TYPE_ADAPTER.validate_python(item)\\n            return item\\n\\n        if isinstance(value, str):\\n            value = json.loads(value) if value.startswith(\\\"[\\\") else [value]\\n        if isinstance(value, list):\\n            return [_parse_item(v) for v in value]\\n        return value\\n\\n    @field_validator(\\\"properties\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_properties(cls, value):\\n        if isinstance(value, str):\\n            value = Properties.model_validate_json(value)\\n        elif isinstance(value, dict):\\n            value = Properties.model_validate(value)\\n        return value\\n\\n    @field_serializer(\\\"flow_id\\\")\\n    def serialize_flow_id(self, value):\\n        if isinstance(value, UUID):\\n            return str(value)\\n        return value\\n\\n    @field_serializer(\\\"run_id\\\")\\n    def serialize_run_id(self, value):\\n        if isinstance(value, UUID):\\n            return str(value)\\n        return value\\n\\n    @field_serializer(\\\"timestamp\\\")\\n    def serialize_timestamp(self, value):\\n        return timestamp_to_str(value)\\n\\n    @field_validator(\\\"files\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_files(cls, value):\\n        if not value:\\n            value = []\\n        elif not isinstance(value, list):\\n            value = [value]\\n        return value\\n\\n    def model_post_init(self, /, _context: Any) -> None:\\n        # If text in data dict is an iterator/stream, move it to __dict__ for direct access.\\n        # Coerce SecretStr first so a secret value isn't mistaken for a stream\\n        # (``text`` is now a computed_field, so the old before-validator that\\n        # did this coercion no longer runs).\\n        text_val = self.data.get(\\\"text\\\")\\n        if is_secret_value(text_val):\\n            text_val = str(text_val)\\n            self.data[self.text_key] = text_val\\n        if text_val is not None and not isinstance(text_val, str):\\n            self.data.pop(\\\"text\\\", None)\\n            self.__dict__[\\\"_text_stream\\\"] = text_val\\n        new_files: list[Any] = []\\n        for file in self.files or []:\\n            # Skip if already an Image instance\\n            if isinstance(file, Image):\\n                new_files.append(file)\\n            # Get the path string if file is a dict or has path attribute\\n            elif isinstance(file, dict) and \\\"path\\\" in file:\\n                file_path = file[\\\"path\\\"]\\n                if file_path and is_image_file(file_path):\\n                    new_files.append(Image(path=file_path))\\n                else:\\n                    new_files.append(file_path if file_path else file)\\n            elif hasattr(file, \\\"path\\\") and file.path:\\n                if is_image_file(file.path):\\n                    new_files.append(Image(path=file.path))\\n                else:\\n                    new_files.append(file.path)\\n            elif isinstance(file, str) and is_image_file(file):\\n                new_files.append(Image(path=file))\\n            else:\\n                new_files.append(file)\\n        self.files = new_files\\n        if \\\"timestamp\\\" not in self.data:\\n            self.data[\\\"timestamp\\\"] = self.timestamp\\n        # Sync self.data[\\\"text\\\"] from content_blocks when content_blocks has\\n        # text content. Otherwise preserve whatever the caller passed in,\\n        # including an explicit ``None`` \u2014 downstream code (e.g.\\n        # ``MessageTable.from_message``) uses ``None`` vs ``\\\"\\\"`` to tell\\n        # \\\"missing required field\\\" apart from \\\"intentionally empty input.\\\"\\n        text_from_blocks = \\\"\\\".join(b.text for b in self.content_blocks if isinstance(b, TextContent))\\n        if text_from_blocks:\\n            self.data[self.text_key] = text_from_blocks\\n        elif self.text_key in self.data:\\n            existing = self.data[self.text_key]\\n            if existing is not None and not isinstance(existing, str):\\n                self.data[self.text_key] = \\\"\\\"\\n        else:\\n            # Bare-default message (``text`` never provided): restore the\\n            # release-1.11.0 default of ``text == \\\"\\\"`` so a sender-only message\\n            # still persists via ``from_message`` and v1 consumers keep finding\\n            # ``data[\\\"text\\\"]``. This matches baseline for both v1 and v2 (``text``\\n            # was a stored field defaulting to \\\"\\\"); only the ``text`` value is\\n            # seeded, ``content_blocks`` is untouched. An explicit ``text=None``\\n            # keeps the key present with ``None`` (handled by the elif above).\\n            self.data[self.text_key] = \\\"\\\"\\n\\n    def set_flow_id(self, flow_id: str) -> None:\\n        self.flow_id = flow_id\\n\\n    def to_lc_message(\\n        self,\\n        model_name: str | None = None,\\n    ) -> BaseMessage:\\n        \\\"\\\"\\\"Converts the Message to a BaseMessage.\\n\\n        Args:\\n            model_name: The model name to use for conversion. Optional.\\n\\n        Returns:\\n            BaseMessage: The converted BaseMessage.\\n        \\\"\\\"\\\"\\n        text = self.text  # reads from content_blocks via computed property\\n        if not isinstance(text, str):\\n            text = \\\"\\\"\\n        if not text or not self.sender:\\n            logger.warning(\\\"Missing required keys ('text', 'sender') in Message, defaulting to HumanMessage.\\\")\\n\\n        if self.sender == MESSAGE_SENDER_USER or not self.sender:\\n            if self.files:\\n                contents = [{\\\"type\\\": \\\"text\\\", \\\"text\\\": text}]\\n                file_contents = self.get_file_content_dicts(model_name)\\n                contents.extend(file_contents)\\n                return HumanMessage(content=contents)\\n            return HumanMessage(content=text)\\n\\n        return AIMessage(content=text)\\n\\n    @classmethod\\n    def from_lc_message(cls, lc_message: BaseMessage) -> Message:\\n        if lc_message.type == \\\"human\\\":\\n            sender = MESSAGE_SENDER_USER\\n            sender_name = MESSAGE_SENDER_NAME_USER\\n        elif lc_message.type == \\\"ai\\\":\\n            sender = MESSAGE_SENDER_AI\\n            sender_name = MESSAGE_SENDER_NAME_AI\\n        elif lc_message.type == \\\"system\\\":\\n            sender = \\\"System\\\"\\n            sender_name = \\\"System\\\"\\n        elif lc_message.type == \\\"tool\\\":\\n            sender = \\\"Tool\\\"\\n            sender_name = \\\"Tool\\\"\\n        else:\\n            sender = lc_message.type\\n            sender_name = lc_message.type\\n\\n        from lfx.schema.content_types import ImageContent, ToolContent\\n\\n        blocks: list[Any] = []\\n        content = lc_message.content\\n        if isinstance(content, str):\\n            if content:\\n                blocks.append(TextContent(text=content))\\n        else:\\n            for item in content:\\n                if isinstance(item, str):\\n                    blocks.append(TextContent(text=item))\\n                elif isinstance(item, dict):\\n                    item_type = item.get(\\\"type\\\", \\\"\\\")\\n                    if item_type == \\\"text\\\":\\n                        blocks.append(TextContent(text=item.get(\\\"text\\\", \\\"\\\")))\\n                    elif item_type == \\\"image_url\\\":\\n                        url = item.get(\\\"image_url\\\", {}).get(\\\"url\\\", \\\"\\\")\\n                        blocks.append(ImageContent(urls=[url]))\\n                    elif item_type == \\\"image\\\":\\n                        # ``source`` can be missing OR explicitly None on\\n                        # malformed payloads; guard both cases (``.get(key, {})``\\n                        # only defaults when the key is absent, not when it's\\n                        # explicitly None).\\n                        source = item.get(\\\"source\\\") or {}\\n                        url = item.get(\\\"url\\\") or source.get(\\\"url\\\", \\\"\\\")\\n                        b64 = source.get(\\\"data\\\") or item.get(\\\"base64\\\")\\n                        mime = source.get(\\\"media_type\\\") or item.get(\\\"mime_type\\\")\\n                        if b64 and mime:\\n                            blocks.append(ImageContent(base64=b64, mime_type=mime))\\n                        elif url:\\n                            blocks.append(ImageContent(urls=[url]))\\n                        else:\\n                            # Log shape only, never the payload, so a provider\\n                            # emitting an undecodable image part leaves a trace\\n                            # instead of silently dropping content.\\n                            logger.debug(\\n                                \\\"from_lc_message: dropping image item with no usable url/base64 \\\"\\n                                f\\\"(keys={sorted(item.keys())})\\\"\\n                            )\\n                    elif item_type == \\\"tool_use\\\":\\n                        # Anthropic raw content carries tool calls inline as\\n                        # ``{\\\"type\\\":\\\"tool_use\\\",\\\"id\\\",\\\"name\\\",\\\"input\\\"}``. LangChain\\n                        # leaves ``.tool_calls`` empty for raw-content messages,\\n                        # so the tool_calls fallback below won't fire \u2014 capture\\n                        # them here so chat-history round-trips don't drop the\\n                        # call.\\n                        blocks.append(\\n                            ToolContent(\\n                                name=item.get(\\\"name\\\", \\\"\\\"),\\n                                tool_input=item.get(\\\"input\\\", {}),\\n                                id=item.get(\\\"id\\\"),\\n                            )\\n                        )\\n                    else:\\n                        logger.debug(f\\\"from_lc_message: skipping unsupported content type '{item_type}'\\\")\\n\\n        # Tool calls and usage metadata live as AIMessage attributes, not in\\n        # ``content``. Tool-calling agents typically emit ``content=\\\"\\\"`` with\\n        # only ``tool_calls`` set, so this must run regardless of content shape.\\n        if hasattr(lc_message, \\\"tool_calls\\\") and lc_message.tool_calls:\\n            # The content walk above may have already captured tool_use blocks\\n            # (Anthropic raw content). Skip ids already present so a message\\n            # carrying both inline tool_use and a populated ``.tool_calls``\\n            # doesn't double the same logical call.\\n            seen_tool_ids = {b.id for b in blocks if isinstance(b, ToolContent) and b.id}\\n            # ``tc[\\\"id\\\"]`` is LangChain's stable ``tool_call_id``: same value\\n            # at start, during args streaming, and on the result, so the same\\n            # logical tool call dedups to one ``ToolContent`` across re-fires.\\n            blocks.extend(\\n                ToolContent(name=tc.get(\\\"name\\\", \\\"\\\"), tool_input=tc.get(\\\"args\\\", {}), id=tc.get(\\\"id\\\"))\\n                for tc in lc_message.tool_calls\\n                if tc.get(\\\"id\\\") not in seen_tool_ids\\n            )\\n\\n        if hasattr(lc_message, \\\"usage_metadata\\\") and lc_message.usage_metadata:\\n            from lfx.schema.content_types import UsageContent\\n\\n            um = lc_message.usage_metadata\\n            blocks.append(\\n                UsageContent(\\n                    input_tokens=um.get(\\\"input_tokens\\\"),\\n                    output_tokens=um.get(\\\"output_tokens\\\"),\\n                    model=lc_message.response_metadata.get(\\\"model_name\\\")\\n                    if hasattr(lc_message, \\\"response_metadata\\\")\\n                    else None,\\n                )\\n            )\\n\\n        # Preserve the text-only fast path: a string-content message with no\\n        # tool calls or usage data keeps ``content_blocks=[]`` (frontend\\n        # compat) and routes content through the ``text=`` parameter.\\n        if isinstance(content, str) and not any(not isinstance(b, TextContent) for b in blocks):\\n            return cls(text=content, sender=sender, sender_name=sender_name)\\n        return cls(content_blocks=blocks, sender=sender, sender_name=sender_name)\\n\\n    @classmethod\\n    def from_data(cls, data: Data) -> Message:\\n        \\\"\\\"\\\"Converts Data to a Message.\\n\\n        Args:\\n            data: The Data to convert.\\n\\n        Returns:\\n            The converted Message.\\n        \\\"\\\"\\\"\\n        kwargs: dict[str, Any] = {\\\"text\\\": data.get_text()}\\n        # Safely extract optional fields that may not exist on a plain Data object.\\n        # ``run_id`` and ``session_metadata`` are not present on the base ``Data``\\n        # class but are copied when the source is a ``Message`` so message\\n        # provenance round-trips through ``Message.from_data(msg.to_data())``.\\n        for field in (\\n            \\\"sender\\\",\\n            \\\"sender_name\\\",\\n            \\\"files\\\",\\n            \\\"session_id\\\",\\n            \\\"context_id\\\",\\n            \\\"run_id\\\",\\n            \\\"timestamp\\\",\\n            \\\"flow_id\\\",\\n            \\\"error\\\",\\n            \\\"edit\\\",\\n            \\\"session_metadata\\\",\\n        ):\\n            try:\\n                value = getattr(data, field)\\n                kwargs[field] = value\\n            except AttributeError:\\n                pass\\n        return cls(**kwargs)\\n\\n    # Keep this async method for backwards compatibility\\n    def get_file_content_dicts(self, model_name: str | None = None):\\n        def _safe_attachment_name(value: Any) -> str | None:\\n            if isinstance(value, Image):\\n                if not value.path:\\n                    return None\\n                try:\\n                    return Path(value.path).name\\n                except (OSError, TypeError, ValueError):\\n                    return None\\n            try:\\n                return Path(value).name\\n            except (OSError, TypeError, ValueError):\\n                return None\\n\\n        content_dicts = []\\n        try:\\n            files = get_file_paths(self.files)\\n        except (OSError, TypeError, ValueError) as exc:\\n            logger.error(\\n                \\\"Error getting file paths\\\",\\n                error_type=type(exc).__name__,\\n                exc_info=True,\\n            )\\n            return content_dicts\\n\\n        for file in files:\\n            if isinstance(file, Image):\\n                content_dicts.append(file.to_content_dict(flow_id=self.flow_id))\\n                continue\\n\\n            try:\\n                if is_image_file(file):\\n                    content_dicts.append(create_image_content_dict(file, None, model_name))\\n                    continue\\n\\n                # Refuse to text-decode files whose extension is not in\\n                # TEXT_FILE_TYPES (and that didn't pass is_image_file above).\\n                # `read_text_file` falls back to latin-1 which ALWAYS succeeds,\\n                # so binary payloads (e.g. a PNG that PIL refused to verify)\\n                # used to slip through and get injected into the HumanMessage\\n                # as a long latin-1-garbled string (QA API-010).\\n                if not _is_text_like_extension(file):\\n                    logger.debug(\\n                        \\\"Skipping attachment during message conversion: unsupported binary extension\\\",\\n                        file_name=_safe_attachment_name(file),\\n                    )\\n                    continue\\n\\n                try:\\n                    file_size_bytes = Path(file).stat().st_size\\n                except (OSError, ValueError) as exc:\\n                    logger.warning(\\n                        \\\"Skipping attachment during message conversion: could not stat file\\\",\\n                        error_type=type(exc).__name__,\\n                        file_name=_safe_attachment_name(file),\\n                    )\\n                    continue\\n\\n                if file_size_bytes > MAX_ATTACHMENT_SIZE_BYTES:\\n                    continue\\n\\n                from lfx.base.data.utils import parse_text_file_to_data\\n\\n                parsed_file = parse_text_file_to_data(file, silent_errors=True)\\n                parsed_data = parsed_file.data if parsed_file else {}\\n                parsed_text = parsed_data.get(\\\"text\\\") if isinstance(parsed_data, dict) else None\\n                if not parsed_text:\\n                    continue\\n\\n                parsed_text_str = parsed_text if isinstance(parsed_text, str) else json.dumps(parsed_text)\\n                file_name = _safe_attachment_name(file) or \\\"attachment\\\"\\n                # Avoid the literal \\\"Attachment:\\\" framing \u2014 Gemini 2.5 Flash\\n                # (and likely related models) treats it as a multimodal-attach\\n                # request and refuses with \\\"I cannot process attachments in\\n                # this environment\\\" (QA GAP-M-3). A neutral \\\"File \u2026 contents\\\"\\n                # header keeps the same context for the LLM without tripping\\n                # provider refusal heuristics.\\n                content_dicts.append(\\n                    {\\n                        \\\"type\\\": \\\"text\\\",\\n                        \\\"text\\\": f\\\"File '{file_name}' contents:\\\\n{parsed_text_str}\\\",\\n                    }\\n                )\\n            except PermissionError as exc:\\n                logger.error(\\n                    \\\"Skipping attachment during message conversion: permission denied\\\",\\n                    error_type=type(exc).__name__,\\n                    file_name=_safe_attachment_name(file),\\n                    exc_info=True,\\n                )\\n                continue\\n            except (FileNotFoundError, UnicodeDecodeError, ValueError, OSError) as exc:\\n                logger.warning(\\n                    \\\"Skipping unsupported attachment during message conversion\\\",\\n                    error_type=type(exc).__name__,\\n                    file_name=_safe_attachment_name(file),\\n                )\\n                continue\\n        return content_dicts\\n\\n    def load_lc_prompt(self):\\n        if \\\"prompt\\\" not in self:\\n            msg = \\\"Prompt is required.\\\"\\n            raise ValueError(msg)\\n        # self.prompt was passed through jsonable_encoder\\n        # so inner messages are not BaseMessage\\n        # we need to convert them to BaseMessage\\n        messages = []\\n        for message in self.prompt.get(\\\"kwargs\\\", {}).get(\\\"messages\\\", []):\\n            match message:\\n                case HumanMessage():\\n                    messages.append(message)\\n                case _ if message.get(\\\"type\\\") == \\\"human\\\":\\n                    messages.append(HumanMessage(content=message.get(\\\"content\\\")))\\n                case _ if message.get(\\\"type\\\") == \\\"system\\\":\\n                    messages.append(SystemMessage(content=message.get(\\\"content\\\")))\\n                case _ if message.get(\\\"type\\\") == \\\"ai\\\":\\n                    messages.append(AIMessage(content=message.get(\\\"content\\\")))\\n                case _ if message.get(\\\"type\\\") == \\\"tool\\\":\\n                    messages.append(ToolMessage(content=message.get(\\\"content\\\")))\\n\\n        self.prompt[\\\"kwargs\\\"][\\\"messages\\\"] = messages\\n        return load(self.prompt)\\n\\n    @classmethod\\n    def from_lc_prompt(\\n        cls,\\n        prompt: BaseChatPromptTemplate,\\n    ):\\n        prompt_json = prompt.to_json()\\n        return cls(prompt=prompt_json)\\n\\n    def format_text(self, template_format=\\\"f-string\\\"):\\n        if template_format == \\\"mustache\\\":\\n            # Use our secure mustache renderer\\n            variables_with_str_values = dict_values_to_string(self.variables)\\n            formatted_prompt = safe_mustache_render(self.template, variables_with_str_values)\\n            self.text = formatted_prompt\\n            return formatted_prompt\\n        # Use langchain's template for other formats\\n        from langchain_core.prompts.prompt import PromptTemplate\\n\\n        prompt_template = PromptTemplate.from_template(self.template, template_format=template_format)\\n        variables_with_str_values = dict_values_to_string(self.variables)\\n        formatted_prompt = prompt_template.format(**variables_with_str_values)\\n        self.text = formatted_prompt\\n        return formatted_prompt\\n\\n    @classmethod\\n    async def from_template_and_variables(cls, template: str, template_format: str = \\\"f-string\\\", **variables):\\n        # This method has to be async for backwards compatibility with versions\\n        # >1.0.15, <1.1\\n        return cls.from_template(template, template_format=template_format, **variables)\\n\\n    # Define a sync version for backwards compatibility with versions >1.0.15, <1.1\\n    @classmethod\\n    def from_template(cls, template: str, template_format: str = \\\"f-string\\\", **variables):\\n        from langchain_core.prompts.chat import ChatPromptTemplate\\n\\n        instance = cls(template=template, variables=variables)\\n        text = instance.format_text(template_format=template_format)\\n        message = HumanMessage(content=text)\\n        contents = []\\n        for value in variables.values():\\n            if isinstance(value, cls) and value.files:\\n                content_dicts = value.get_file_content_dicts()\\n                contents.extend(content_dicts)\\n        if contents:\\n            message = HumanMessage(content=[{\\\"type\\\": \\\"text\\\", \\\"text\\\": text}, *contents])\\n\\n        prompt_template = ChatPromptTemplate.from_messages([message])\\n\\n        instance.prompt = jsonable_encoder(prompt_template.to_json())\\n        instance.messages = instance.prompt.get(\\\"kwargs\\\", {}).get(\\\"messages\\\", [])\\n        return instance\\n\\n    @classmethod\\n    async def create(cls, **kwargs):\\n        \\\"\\\"\\\"If files are present, create the message in a separate thread as is_image_file is blocking.\\\"\\\"\\\"\\n        if kwargs.get(\\\"files\\\"):\\n            return await asyncio.to_thread(cls, **kwargs)\\n        return cls(**kwargs)\\n\\n    def to_data(self) -> Data:\\n        return Data(data=self.data)\\n\\n    def to_dataframe(self) -> DataFrame:\\n        from lfx.schema.dataframe import DataFrame  # Local import to avoid circular import\\n\\n        return DataFrame(data=[self])\\n\\n    def get_id(self) -> str | UUID | None:\\n        \\\"\\\"\\\"Safely get the message ID.\\n\\n        Returns:\\n            The message ID if it exists, None otherwise.\\n\\n        Note:\\n            A message only has an ID if it has been stored in the database.\\n            Messages that are skipped (via _should_skip_message) will not have an ID.\\n        \\\"\\\"\\\"\\n        return getattr(self, \\\"id\\\", None)\\n\\n    def has_id(self) -> bool:\\n        \\\"\\\"\\\"Check if the message has an ID.\\n\\n        Returns:\\n            True if the message has an ID, False otherwise.\\n\\n        Note:\\n            A message only has an ID if it has been stored in the database.\\n            Messages that are skipped (via _should_skip_message) will not have an ID.\\n        \\\"\\\"\\\"\\n        message_id = getattr(self, \\\"id\\\", None)\\n        return message_id is not None\\n\\n    def require_id(self) -> str | UUID:\\n        \\\"\\\"\\\"Get the message ID, raising an error if it doesn't exist.\\n\\n        Returns:\\n            The message ID.\\n\\n        Raises:\\n            ValueError: If the message does not have an ID.\\n\\n        Note:\\n            Use this method when an ID is required for the operation.\\n            For optional ID access, use get_id() instead.\\n        \\\"\\\"\\\"\\n        message_id = getattr(self, \\\"id\\\", None)\\n        if message_id is None:\\n            msg = \\\"Message does not have an ID. Messages only have IDs after being stored in the database.\\\"\\n            raise ValueError(msg)\\n        return message_id\\n\\n\\nclass DefaultModel(BaseModel):\\n    model_config = ConfigDict(\\n        from_attributes=True,\\n        populate_by_name=True,\\n        json_encoders={\\n            datetime: lambda v: v.isoformat(),\\n            UUID: lambda v: str(v),\\n        },\\n    )\\n\\n    def json(self, **kwargs):\\n        # Usa a fun\u00e7\u00e3o de serializa\u00e7\u00e3o personalizada\\n        return super().model_dump_json(**kwargs, encoder=self.custom_encoder)\\n\\n    @staticmethod\\n    def custom_encoder(obj):\\n        if isinstance(obj, datetime):\\n            return obj.isoformat()\\n        msg = f\\\"Object of type {obj.__class__.__name__} is not JSON serializable\\\"\\n        raise TypeError(msg)\\n\\n\\nclass MessageResponse(DefaultModel):\\n    id: str | UUID | None = Field(default=None)\\n    flow_id: UUID | None = Field(default=None)\\n    # ``Message.timestamp`` is a string with microsecond+timezone precision\\n    # (``%Y-%m-%d %H:%M:%S.%f %Z``) which Pydantic's default datetime parser\\n    # rejects. Reuse the shared parser so MessageResponse.from_message\\n    # accepts any of the formats ``Message`` itself recognises.\\n    timestamp: Annotated[datetime, str_to_timestamp_validator] = Field(\\n        default_factory=lambda: datetime.now(timezone.utc)\\n    )\\n    sender: str\\n    sender_name: str\\n    session_id: str\\n    context_id: str | None = None\\n    text: str\\n    files: list[str] = []\\n    edit: bool\\n    duration: float | None = None\\n\\n    properties: Properties | None = None\\n    category: str | None = None\\n    # v1 wire shape: content_blocks is held as plain legacy dicts, not the new\\n    # ContentType union, so the v1 API keeps emitting the release-1.11.0 shape.\\n    # The new (v2) shape never flows through MessageResponse.\\n    content_blocks: list[dict] | None = None\\n    session_metadata: dict | None = None\\n\\n    @field_validator(\\\"content_blocks\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_content_blocks(cls, v):\\n        # Project the new content_blocks model onto the legacy (release-1.11.0)\\n        # v1 shape. Accepts ContentType models (from ``from_message``), serialized\\n        # dicts (from a DB-row ``model_validate``), or a JSON string. The agent\\n        # answer is folded back into the \\\"Agent Steps\\\" group; the new (v2) shape\\n        # never flows through MessageResponse.\\n        return render_v1_content_blocks(v)\\n\\n    @field_validator(\\\"properties\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_properties(cls, v):\\n        if isinstance(v, str):\\n            v = json.loads(v)\\n        return v\\n\\n    @field_validator(\\\"files\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_files(cls, v):\\n        if isinstance(v, str):\\n            v = json.loads(v)\\n        return v\\n\\n    @field_serializer(\\\"timestamp\\\")\\n    @classmethod\\n    def serialize_timestamp(cls, v):\\n        return timestamp_to_str(v)\\n\\n    @field_serializer(\\\"files\\\")\\n    @classmethod\\n    def serialize_files(cls, v):\\n        if isinstance(v, list):\\n            return json.dumps(v)\\n        return v\\n\\n    @classmethod\\n    def from_message(cls, message: Message, flow_id: str | None = None):\\n        # first check if the record has all the required fields. ``message.text``\\n        # is a computed_field over content_blocks now, so it always returns a\\n        # string. The \\\"content present\\\" signal is: ``data[\\\"text\\\"]`` explicitly\\n        # set (covers ``text=\\\"\\\"`` from ChatInput), or a pending text stream\\n        # (iterator), or any ``content_blocks`` entries (covers tool-call-only\\n        # / media-only agent messages whose ``content_blocks`` carry the\\n        # whole payload).\\n        no_content = message.data.get(\\\"text\\\") is None and message.text_stream is None and not message.content_blocks\\n        if no_content or not message.sender or not message.sender_name:\\n            msg = \\\"The message does not have the required fields (text, sender, sender_name).\\\"\\n            raise ValueError(msg)\\n        text = legacy_text(message)\\n        return cls(\\n            sender=message.sender,\\n            sender_name=message.sender_name,\\n            text=text,\\n            session_id=message.session_id,\\n            context_id=message.context_id,\\n            files=message.files or [],\\n            timestamp=message.timestamp,\\n            flow_id=flow_id,\\n            edit=message.edit,\\n            content_blocks=message.content_blocks,\\n            properties=message.properties,\\n            category=message.category,\\n            session_metadata=getattr(message, \\\"session_metadata\\\", None),\\n        )\\n\\n\\nclass ErrorMessage(Message):\\n    \\\"\\\"\\\"A message class specifically for error messages with predefined error-specific attributes.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _coded_exception_message(exception: BaseException) -> str | None:\\n        \\\"\\\"\\\"Return the human-readable message of an exception that also carries a ``code``.\\n\\n        Reason-coded errors (for example ``ModelProviderPolicyError`` with\\n        ``code=\\\"policy_blocked\\\"``) raise with a message meant for the person\\n        reading the error panel. Rendering only ``Code: policy_blocked`` --\\n        prefixed by the Python class name -- told builders nothing about what\\n        was blocked or who to ask.\\n\\n        Driver and SDK errors are coded too, but put nothing in ``args``: a Cassandra\\n        ``SyntaxException`` carries the protocol status on ``.code`` and the parser text\\n        on ``.message``/``__str__``. Reading only ``args`` made a mistyped table name\\n        surface as ``Code: 8192`` while the real cause sat in the logs (LE-2352).\\n        \\\"\\\"\\\"\\n        args = getattr(exception, \\\"args\\\", ())\\n        if args and isinstance(args[0], str) and args[0].strip():\\n            return args[0].strip()\\n\\n        # ``.message`` is the SDK convention for the human text; ``__str__`` is the\\n        # fallback for drivers that only render it there.\\n        message = getattr(exception, \\\"message\\\", None)\\n        if isinstance(message, str) and message.strip():\\n            return message.strip()\\n\\n        rendered = str(exception).strip()\\n        return rendered or None\\n\\n    @staticmethod\\n    def _format_markdown_reason(exception: BaseException) -> str:\\n        \\\"\\\"\\\"Format the error reason with markdown formatting.\\\"\\\"\\\"\\n        reason = f\\\"**{exception.__class__.__name__}**\\\\n\\\"\\n        if hasattr(exception, \\\"body\\\") and isinstance(exception.body, dict) and \\\"message\\\" in exception.body:\\n            reason += f\\\" - **{exception.body.get('message')}**\\\\n\\\"\\n        elif hasattr(exception, \\\"code\\\"):\\n            message = ErrorMessage._coded_exception_message(exception)\\n            if message:\\n                reason = f\\\"**{message}**\\\\n - **Code: {exception.code}**\\\\n\\\"\\n            else:\\n                reason += f\\\" - **Code: {exception.code}**\\\\n\\\"\\n        elif isinstance(exception, OSError):\\n            reason += f\\\" - **Details: {exception!s}**\\\\n\\\"\\n        elif hasattr(exception, \\\"args\\\") and exception.args:\\n            reason += f\\\" - **Details: {exception.args[0]}**\\\\n\\\"\\n        elif isinstance(exception, ValidationError):\\n            reason += f\\\" - **Details:**\\\\n\\\\n```python\\\\n{exception!s}\\\\n```\\\\n\\\"\\n        else:\\n            reason += \\\" - **An unknown error occurred.**\\\\n\\\"\\n        return reason\\n\\n    @staticmethod\\n    def _format_plain_reason(exception: BaseException) -> str:\\n        \\\"\\\"\\\"Format the error reason without markdown.\\\"\\\"\\\"\\n        if hasattr(exception, \\\"body\\\") and isinstance(exception.body, dict) and \\\"message\\\" in exception.body:\\n            reason = f\\\"{exception.body.get('message')}\\\\n\\\"\\n        elif hasattr(exception, \\\"_message\\\"):\\n            reason = f\\\"{exception._message()}\\\\n\\\" if callable(exception._message) else f\\\"{exception._message}\\\\n\\\"  # noqa: SLF001\\n        elif hasattr(exception, \\\"code\\\"):\\n            message = ErrorMessage._coded_exception_message(exception)\\n            reason = f\\\"{message}\\\\n\\\" if message else f\\\"Code: {exception.code}\\\\n\\\"\\n        elif isinstance(exception, OSError):\\n            reason = f\\\"{exception!s}\\\\n\\\"\\n        elif hasattr(exception, \\\"args\\\") and exception.args:\\n            reason = f\\\"{exception.args[0]}\\\\n\\\"\\n        elif isinstance(exception, ValidationError):\\n            reason = f\\\"{exception!s}\\\\n\\\"\\n        elif hasattr(exception, \\\"detail\\\"):\\n            reason = f\\\"{exception.detail}\\\\n\\\"\\n        elif hasattr(exception, \\\"message\\\"):\\n            reason = f\\\"{exception.message}\\\\n\\\"\\n        else:\\n            reason = \\\"An unknown error occurred.\\\\n\\\"\\n        return reason\\n\\n    def __init__(\\n        self,\\n        exception: BaseException,\\n        session_id: str | None = None,\\n        context_id: str | None = None,\\n        source: Source | None = None,\\n        trace_name: str | None = None,\\n        flow_id: UUID | str | None = None,\\n        session_metadata: dict | None = None,\\n        *,\\n        include_traceback: bool = True,\\n        context_note: str | None = None,\\n    ) -> None:\\n        # This is done to avoid circular imports\\n        if exception.__class__.__name__ == \\\"ExceptionWithMessageError\\\" and exception.__cause__ is not None:\\n            exception = exception.__cause__\\n\\n        plain_reason = self._format_plain_reason(exception)\\n        markdown_reason = self._format_markdown_reason(exception)\\n        # Keep the original exception's formatting and metadata while adding\\n        # diagnostic context to both the streamed text and the error details.\\n        if context_note:\\n            plain_reason = f\\\"{plain_reason.rstrip()}\\\\n\\\\n{context_note}\\\\n\\\"\\n            markdown_reason = f\\\"{markdown_reason.rstrip()}\\\\n\\\\n{context_note}\\\\n\\\"\\n        # Get the sender ID\\n        if trace_name:\\n            match = re.search(r\\\"\\\\((.*?)\\\\)\\\", trace_name)\\n            if match:\\n                match.group(1)\\n\\n        super().__init__(\\n            session_id=session_id,\\n            context_id=context_id,\\n            sender=source.display_name if source else None,\\n            sender_name=source.display_name if source else None,\\n            properties=Properties(\\n                text_color=\\\"red\\\",\\n                background_color=\\\"red\\\",\\n                edited=False,\\n                source=source,\\n                icon=\\\"error\\\",\\n                allow_markdown=False,\\n                targets=[],\\n            ),\\n            category=\\\"error\\\",\\n            error=True,\\n            content_blocks=[\\n                TextContent(text=plain_reason),\\n                ContentBlock(\\n                    title=\\\"Error\\\",\\n                    contents=[\\n                        ErrorContent(\\n                            type=\\\"error\\\",\\n                            component=source.display_name if source else None,\\n                            field=str(exception.field) if hasattr(exception, \\\"field\\\") else None,\\n                            reason=markdown_reason,\\n                            solution=str(exception.solution) if hasattr(exception, \\\"solution\\\") else None,\\n                            traceback=traceback.format_exc() if include_traceback else \\\"\\\",\\n                        )\\n                    ],\\n                ),\\n            ],\\n            flow_id=flow_id,\\n            session_metadata=session_metadata,\\n        )\\n\\n\\n__all__ = [\\n    \\\"MAX_ATTACHMENT_SIZE_BYTES\\\",\\n    \\\"ContentBlock\\\",\\n    \\\"DefaultModel\\\",\\n    \\\"ErrorMessage\\\",\\n    \\\"Message\\\",\\n    \\\"MessageResponse\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/openai_responses_schemas.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"66b88c17ed40846a425067b054e5b670a3895f7a6d54cf78781e4945618261f4\",\"content\":\"from typing import Any, Literal\\n\\nfrom pydantic import BaseModel, Field\\n\\n\\nclass OpenAIResponsesRequest(BaseModel):\\n    \\\"\\\"\\\"OpenAI-compatible responses request with flow_id as model parameter.\\\"\\\"\\\"\\n\\n    model: str = Field(..., description=\\\"The flow ID to execute (used instead of OpenAI model)\\\")\\n    input: str = Field(..., description=\\\"The input text to process\\\")\\n    stream: bool = Field(default=False, description=\\\"Whether to stream the response\\\")\\n    background: bool = Field(default=False, description=\\\"Whether to process in background\\\")\\n    tools: list[Any] | None = Field(default=None, description=\\\"Tools are not supported yet\\\")\\n    previous_response_id: str | None = Field(\\n        default=None, description=\\\"ID of previous response to continue conversation\\\"\\n    )\\n    include: list[str] | None = Field(\\n        default=None, description=\\\"Additional response data to include, e.g., ['tool_call.results']\\\"\\n    )\\n\\n\\nclass OpenAIResponsesResponse(BaseModel):\\n    \\\"\\\"\\\"OpenAI-compatible responses response.\\\"\\\"\\\"\\n\\n    id: str\\n    object: Literal[\\\"response\\\"] = \\\"response\\\"\\n    created_at: int\\n    status: Literal[\\\"completed\\\", \\\"in_progress\\\", \\\"failed\\\"] = \\\"completed\\\"\\n    error: dict | None = None\\n    incomplete_details: dict | None = None\\n    instructions: str | None = None\\n    max_output_tokens: int | None = None\\n    model: str\\n    output: list[dict]\\n    parallel_tool_calls: bool = True\\n    previous_response_id: str | None = None\\n    reasoning: dict = Field(default_factory=lambda: {\\\"effort\\\": None, \\\"summary\\\": None})\\n    store: bool = True\\n    temperature: float = 1.0\\n    text: dict = Field(default_factory=lambda: {\\\"format\\\": {\\\"type\\\": \\\"text\\\"}})\\n    tool_choice: str = \\\"auto\\\"\\n    tools: list[dict] = Field(default_factory=list)\\n    top_p: float = 1.0\\n    truncation: str = \\\"disabled\\\"\\n    usage: dict | None = None\\n    user: str | None = None\\n    metadata: dict = Field(default_factory=dict)\\n\\n\\nclass OpenAIResponsesStreamChunk(BaseModel):\\n    \\\"\\\"\\\"OpenAI-compatible responses stream chunk.\\\"\\\"\\\"\\n\\n    id: str\\n    object: Literal[\\\"response.chunk\\\"] = \\\"response.chunk\\\"\\n    created: int\\n    model: str\\n    delta: dict\\n    status: Literal[\\\"completed\\\", \\\"in_progress\\\", \\\"failed\\\"] | None = None\\n    finish_reason: Literal[\\\"stop\\\", \\\"length\\\", \\\"error\\\", \\\"tool_calls\\\"] | None = None\\n\\n\\nclass OpenAIErrorResponse(BaseModel):\\n    error: dict = Field(..., description=\\\"Error details\\\")\\n\\n\\ndef create_openai_error(message: str, type_: str = \\\"invalid_request_error\\\", code: str | None = None) -> dict:\\n    \\\"\\\"\\\"Create an OpenAI-compatible error response.\\\"\\\"\\\"\\n    error_data = {\\n        \\\"message\\\": message,\\n        \\\"type\\\": type_,\\n    }\\n    if code:\\n        error_data[\\\"code\\\"] = code\\n\\n    return {\\\"error\\\": error_data}\\n\\n\\ndef create_openai_error_chunk(\\n    response_id: str,\\n    created_timestamp: int,\\n    model: str,\\n    error_message: str,\\n) -> OpenAIResponsesStreamChunk:\\n    \\\"\\\"\\\"Create an OpenAI-compatible error chunk for streaming responses.\\n\\n    This formats errors as content chunks with finish_reason=\\\"error\\\" so that\\n    the OpenAI SDK can properly parse and surface them to clients.\\n\\n    Args:\\n        response_id: The response ID\\n        created_timestamp: Unix timestamp when the response was created\\n        model: The model/flow ID\\n        error_message: The error message to include in the content\\n\\n    Returns:\\n        OpenAIResponsesStreamChunk with error content and finish_reason=\\\"error\\\"\\n    \\\"\\\"\\\"\\n    return OpenAIResponsesStreamChunk(\\n        id=response_id,\\n        created=created_timestamp,\\n        model=model,\\n        delta={\\\"content\\\": error_message},\\n        status=\\\"failed\\\",\\n        finish_reason=\\\"error\\\",\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/properties.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a44fe8bf92325376445cf60af49dfd351bda92f11f7d81cf8295d6223fd250f1\",\"content\":\"\\\"\\\"\\\"Properties and Source schema classes copied from langflow for lfx package.\\\"\\\"\\\"\\n\\nfrom typing import Literal\\n\\nfrom pydantic import BaseModel, Field, field_serializer, field_validator\\n\\n\\nclass Source(BaseModel):\\n    id: str | None = Field(default=None, description=\\\"The id of the source component.\\\")\\n    display_name: str | None = Field(default=None, description=\\\"The display name of the source component.\\\")\\n    source: str | None = Field(\\n        default=None,\\n        description=\\\"The source of the message. Normally used to display the model name (e.g. 'gpt-4o')\\\",\\n    )\\n\\n\\nclass Usage(BaseModel):\\n    \\\"\\\"\\\"Token usage information from LLM responses.\\\"\\\"\\\"\\n\\n    input_tokens: int | None = None\\n    output_tokens: int | None = None\\n    total_tokens: int | None = None\\n\\n\\nclass Properties(BaseModel):\\n    text_color: str | None = None\\n    background_color: str | None = None\\n    edited: bool = False\\n    source: Source = Field(default_factory=Source)\\n    icon: str | None = None\\n    allow_markdown: bool = False\\n    positive_feedback: bool | None = None\\n    state: Literal[\\\"partial\\\", \\\"complete\\\"] = \\\"complete\\\"\\n    targets: list = []\\n    usage: Usage | None = None\\n    build_duration: float | None = None\\n\\n    @field_validator(\\\"source\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_source(cls, v):\\n        if isinstance(v, str):\\n            return Source(id=v, display_name=v, source=v)\\n        if v is None:\\n            return Source()\\n        return v\\n\\n    @field_serializer(\\\"source\\\")\\n    def serialize_source(self, value):\\n        if isinstance(value, Source):\\n            return value.model_dump()\\n        return value\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"64046619a0029fcf73a894065faf83f5b40540721c5f87b0d911197e0410f26a\",\"content\":\"from collections.abc import Generator\\nfrom enum import Enum\\nfrom typing import TYPE_CHECKING, Literal\\n\\nfrom pandas import Series\\nfrom pydantic import BaseModel, ConfigDict, Field\\nfrom typing_extensions import TypedDict\\n\\nif TYPE_CHECKING:\\n    from lfx.custom.custom_component.component import Component\\n\\nINPUT_FIELD_NAME = \\\"input_value\\\"\\n\\nInputType = Literal[\\\"chat\\\", \\\"text\\\", \\\"any\\\"]\\nOutputType = Literal[\\\"chat\\\", \\\"text\\\", \\\"any\\\", \\\"debug\\\"]\\n\\n\\nclass LogType(str, Enum):\\n    MESSAGE = \\\"message\\\"\\n    DATA = \\\"data\\\"\\n    STREAM = \\\"stream\\\"\\n    OBJECT = \\\"object\\\"\\n    ARRAY = \\\"array\\\"\\n    TEXT = \\\"text\\\"\\n    UNKNOWN = \\\"unknown\\\"\\n\\n\\nclass StreamURL(TypedDict):\\n    location: str\\n\\n\\nclass ErrorLog(TypedDict):\\n    errorMessage: str\\n    stackTrace: str\\n\\n\\nclass OutputValue(BaseModel):\\n    message: ErrorLog | StreamURL | dict | list | str\\n    type: str\\n\\n\\ndef get_type(payload):\\n    # Importing here to avoid circular imports\\n    from lfx.schema.data import Data\\n    from lfx.schema.dataframe import DataFrame\\n    from lfx.schema.message import Message\\n\\n    result = LogType.UNKNOWN\\n    match payload:\\n        case Message():\\n            result = LogType.MESSAGE\\n\\n        case Data():\\n            result = LogType.DATA\\n\\n        case dict():\\n            result = LogType.OBJECT\\n\\n        case list() | DataFrame():\\n            result = LogType.ARRAY\\n\\n        case str():\\n            result = LogType.TEXT\\n\\n    if result == LogType.UNKNOWN and (\\n        (payload and isinstance(payload, Generator))\\n        or (isinstance(payload, Message) and isinstance(payload.text, Generator))\\n    ):\\n        result = LogType.STREAM\\n\\n    return result\\n\\n\\ndef get_message(payload):\\n    # Importing here to avoid circular imports\\n    from lfx.schema.data import Data\\n\\n    message = None\\n    if hasattr(payload, \\\"data\\\"):\\n        message = payload.data\\n\\n    elif hasattr(payload, \\\"model_dump\\\"):\\n        message = payload.model_dump()\\n\\n    if message is None and isinstance(payload, dict | str | Data):\\n        message = payload.data if isinstance(payload, Data) else payload\\n\\n    if isinstance(message, Series):\\n        return message if not message.empty else payload\\n\\n    return message or payload\\n\\n\\ndef build_output_logs(vertex, result) -> dict:\\n    \\\"\\\"\\\"Build output logs from vertex outputs and results.\\\"\\\"\\\"\\n    # Importing here to avoid circular imports\\n    from lfx.schema.dataframe import DataFrame\\n    from lfx.serialization.serialization import serialize\\n\\n    outputs: dict[str, OutputValue] = {}\\n    component_instance: Component = result[0]\\n    for index, output in enumerate(vertex.outputs):\\n        if component_instance.status is None:\\n            payload = component_instance.get_results()\\n            output_result = payload.get(output[\\\"name\\\"])\\n        else:\\n            payload = component_instance.get_artifacts()\\n            output_result = payload.get(output[\\\"name\\\"], {}).get(\\\"raw\\\")\\n        message = get_message(output_result)\\n        type_ = get_type(output_result)\\n\\n        match type_:\\n            case LogType.STREAM if isinstance(message, dict) and \\\"stream_url\\\" in message:\\n                message = StreamURL(location=message[\\\"stream_url\\\"])\\n\\n            case LogType.STREAM:\\n                message = \\\"\\\"\\n\\n            case LogType.MESSAGE if hasattr(message, \\\"message\\\"):\\n                message = message.message\\n\\n            case LogType.UNKNOWN:\\n                message = \\\"\\\"\\n\\n            case LogType.ARRAY:\\n                if message is None:\\n                    message = []\\n                elif isinstance(message, DataFrame):\\n                    message = message.to_dict(orient=\\\"records\\\")\\n                    message = [serialize(item) for item in message]\\n                else:\\n                    message = [serialize(item) for item in message]\\n        name = output.get(\\\"name\\\", f\\\"output_{index}\\\")\\n        outputs |= {name: OutputValue(message=message, type=type_).model_dump()}\\n\\n    return outputs\\n\\n\\nclass BuildStatus(BaseModel):\\n    \\\"\\\"\\\"Build status schema for API compatibility.\\\"\\\"\\\"\\n\\n    status: str\\n    message: str | None = None\\n    progress: float | None = None\\n\\n\\nclass InputValueRequest(BaseModel):\\n    components: list[str] | None = []\\n    input_value: str | None = None\\n    session: str | None = None\\n    type: InputType | None = Field(\\n        \\\"any\\\",\\n        description=\\\"Defines on which components the input value should be applied. \\\"\\n        \\\"'any' applies to all input components.\\\",\\n    )\\n    client_request_time: int | None = Field(\\n        None,\\n        description=\\\"Client-side timestamp in milliseconds when the request was initiated. \\\"\\n        \\\"Used to calculate accurate end-to-end duration.\\\",\\n    )\\n\\n    # add an example\\n    model_config = ConfigDict(\\n        json_schema_extra={\\n            \\\"examples\\\": [\\n                {\\n                    \\\"components\\\": [\\\"components_id\\\", \\\"Component Name\\\"],\\n                    \\\"input_value\\\": \\\"input_value\\\",\\n                    \\\"session\\\": \\\"session_id\\\",\\n                },\\n                {\\\"components\\\": [\\\"Component Name\\\"], \\\"input_value\\\": \\\"input_value\\\"},\\n                {\\\"input_value\\\": \\\"input_value\\\"},\\n                {\\n                    \\\"components\\\": [\\\"Component Name\\\"],\\n                    \\\"input_value\\\": \\\"input_value\\\",\\n                    \\\"session\\\": \\\"session_id\\\",\\n                },\\n                {\\\"input_value\\\": \\\"input_value\\\", \\\"session\\\": \\\"session_id\\\"},\\n                {\\\"type\\\": \\\"chat\\\", \\\"input_value\\\": \\\"input_value\\\"},\\n                {\\\"type\\\": \\\"json\\\", \\\"input_value\\\": '{\\\"key\\\": \\\"value\\\"}'},\\n            ]\\n        },\\n        extra=\\\"forbid\\\",\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/serialize.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"63b68bf75c37056e1962481d207a2c51876920950392ef92a2a628210b70b463\",\"content\":\"from typing import Annotated\\nfrom uuid import UUID\\n\\nfrom pydantic import BeforeValidator\\n\\n\\ndef str_to_uuid(v: str | UUID) -> UUID:\\n    if isinstance(v, str):\\n        return UUID(v)\\n    return v\\n\\n\\nUUIDstr = Annotated[UUID, BeforeValidator(str_to_uuid)]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/table.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d5174c9a4d6f6f398f156d0910684fed60c346dbd4287f65903c39bfe256852c\",\"content\":\"from enum import Enum\\n\\nfrom pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator\\n\\nVALID_TYPES = [\\n    \\\"date\\\",\\n    \\\"number\\\",\\n    \\\"text\\\",\\n    \\\"json\\\",\\n    \\\"integer\\\",\\n    \\\"int\\\",\\n    \\\"float\\\",\\n    \\\"str\\\",\\n    \\\"string\\\",\\n    \\\"boolean\\\",\\n]\\n\\n\\nclass FormatterType(str, Enum):\\n    date = \\\"date\\\"\\n    text = \\\"text\\\"\\n    number = \\\"number\\\"\\n    json = \\\"json\\\"\\n    boolean = \\\"boolean\\\"\\n\\n\\nclass EditMode(str, Enum):\\n    MODAL = \\\"modal\\\"\\n    POPOVER = \\\"popover\\\"\\n    INLINE = \\\"inline\\\"\\n\\n\\nclass Column(BaseModel):\\n    model_config = ConfigDict(populate_by_name=True)\\n    name: str\\n    display_name: str = Field(default=\\\"\\\")\\n    options: list[str] | None = Field(default=None)\\n    sortable: bool = Field(default=True)\\n    filterable: bool = Field(default=True)\\n    formatter: FormatterType | str | None = Field(default=None)\\n    type: FormatterType | str | None = Field(default=None)\\n    description: str | None = None\\n    default: str | bool | int | float | None = None\\n    disable_edit: bool = Field(default=False)\\n    edit_mode: EditMode | None = Field(default=EditMode.POPOVER)\\n    hidden: bool = Field(default=False)\\n    load_from_db: bool = Field(default=False)\\n    \\\"\\\"\\\"Whether this column's default value should be loaded from global variables\\\"\\\"\\\"\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def set_display_name(self):\\n        if not self.display_name:\\n            self.display_name = self.name\\n        return self\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def set_formatter_from_type(self):\\n        if self.type and not self.formatter:\\n            self.formatter = self.validate_formatter(self.type)\\n        if self.formatter in {\\\"boolean\\\", \\\"bool\\\"}:\\n            valid_trues = [\\\"True\\\", \\\"true\\\", \\\"1\\\", \\\"yes\\\"]\\n            valid_falses = [\\\"False\\\", \\\"false\\\", \\\"0\\\", \\\"no\\\"]\\n            if self.default in valid_trues:\\n                self.default = True\\n            if self.default in valid_falses:\\n                self.default = False\\n        elif self.formatter in {\\\"integer\\\", \\\"int\\\"}:\\n            self.default = int(self.default)\\n        elif self.formatter in {\\\"float\\\"}:\\n            self.default = float(self.default)\\n        else:\\n            self.default = str(self.default)\\n        return self\\n\\n    @field_validator(\\\"formatter\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_formatter(cls, value):\\n        if value in {\\\"boolean\\\", \\\"bool\\\"}:\\n            value = FormatterType.boolean\\n        if value in {\\\"integer\\\", \\\"int\\\", \\\"float\\\"}:\\n            value = FormatterType.number\\n        if value in {\\\"str\\\", \\\"string\\\"}:\\n            value = FormatterType.text\\n        if value == \\\"dict\\\":\\n            value = FormatterType.json\\n        if value == \\\"date\\\":\\n            value = FormatterType.date\\n        if isinstance(value, str):\\n            return FormatterType(value)\\n        if isinstance(value, FormatterType):\\n            return value\\n        msg = f\\\"Invalid formatter type: {value}. Valid types are: {FormatterType}\\\"\\n        raise ValueError(msg)\\n\\n\\nclass TableSchema(BaseModel):\\n    columns: list[Column]\\n\\n\\nclass FieldValidatorType(str, Enum):\\n    \\\"\\\"\\\"Enum for field validation types.\\\"\\\"\\\"\\n\\n    NO_SPACES = \\\"no_spaces\\\"  # Prevents spaces in input\\n    LOWERCASE = \\\"lowercase\\\"  # Forces lowercase\\n    UPPERCASE = \\\"uppercase\\\"  # Forces uppercase\\n    EMAIL = \\\"email\\\"  # Validates email format\\n    URL = \\\"url\\\"  # Validates URL format\\n    ALPHANUMERIC = \\\"alphanumeric\\\"  # Only letters and numbers\\n    NUMERIC = \\\"numeric\\\"  # Only numbers\\n    ALPHA = \\\"alpha\\\"  # Only letters\\n    PHONE = \\\"phone\\\"  # Phone number format\\n    SLUG = \\\"slug\\\"  # URL slug format (lowercase, hyphens)\\n    USERNAME = \\\"username\\\"  # Alphanumeric with underscores\\n    PASSWORD = \\\"password\\\"  # Minimum security requirements\\n\\n\\nclass FieldParserType(str, Enum):\\n    \\\"\\\"\\\"Enum for field parser types.\\\"\\\"\\\"\\n\\n    SNAKE_CASE = \\\"snake_case\\\"\\n    CAMEL_CASE = \\\"camel_case\\\"\\n    PASCAL_CASE = \\\"pascal_case\\\"\\n    KEBAB_CASE = \\\"kebab_case\\\"\\n    LOWERCASE = \\\"lowercase\\\"\\n    UPPERCASE = \\\"uppercase\\\"\\n    NO_BLANK = \\\"no_blank\\\"\\n    VALID_CSV = (\\\"valid_csv\\\",)\\n    COMMANDS = \\\"commands\\\"\\n\\n\\nclass TableOptions(BaseModel):\\n    block_add: bool = Field(default=False)\\n    block_delete: bool = Field(default=False)\\n    block_edit: bool = Field(default=False)\\n    block_sort: bool = Field(default=False)\\n    block_filter: bool = Field(default=False)\\n    block_hide: bool | list[str] = Field(default=False)\\n    block_select: bool = Field(default=False)\\n    hide_options: bool = Field(default=False)\\n    field_validators: dict[str, list[FieldValidatorType] | FieldValidatorType] | None = Field(default=None)\\n    field_parsers: dict[str, list[FieldParserType] | FieldParserType] | None = Field(default=None)\\n    description: str | None = Field(default=None)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/token_usage.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e8553fbf4c5ce4677e000ee5bfaed8bf1da613337a1824572c7f22934e956c9a\",\"content\":\"\\\"\\\"\\\"Shared token usage extraction and accumulation functions.\\n\\nCentralizes token usage extraction from LangChain message objects (AIMessage, streaming chunks)\\nto eliminate duplication across Component, LCModelComponent, and TokenUsageCallbackHandler.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\nfrom lfx.schema.properties import Usage\\n\\n\\ndef _normalize_usage_metadata(um: Any) -> Usage:\\n    \\\"\\\"\\\"Extract usage from usage_metadata, handling both dict (TypedDict) and object forms.\\\"\\\"\\\"\\n    if isinstance(um, dict):\\n        return Usage(\\n            input_tokens=um.get(\\\"input_tokens\\\"),\\n            output_tokens=um.get(\\\"output_tokens\\\"),\\n            total_tokens=um.get(\\\"total_tokens\\\"),\\n        )\\n    return Usage(\\n        input_tokens=getattr(um, \\\"input_tokens\\\", None),\\n        output_tokens=getattr(um, \\\"output_tokens\\\", None),\\n        total_tokens=getattr(um, \\\"total_tokens\\\", None),\\n    )\\n\\n\\ndef extract_usage_from_message(message: Any) -> Usage | None:\\n    \\\"\\\"\\\"Extract token usage from an AIMessage's metadata.\\n\\n    Tries three strategies in priority order:\\n    1. usage_metadata (LangChain standard, works for Ollama and newer providers)\\n    2. response_metadata[\\\"token_usage\\\"] (OpenAI format)\\n    3. response_metadata[\\\"usage\\\"] (Anthropic format)\\n\\n    Args:\\n        message: An AIMessage or similar object with usage_metadata/response_metadata.\\n\\n    Returns:\\n        Usage with token counts, or None if no usage data is available.\\n    \\\"\\\"\\\"\\n    # Strategy 1: usage_metadata (LangChain standard)\\n    usage_metadata = getattr(message, \\\"usage_metadata\\\", None)\\n    if usage_metadata and isinstance(usage_metadata, dict):\\n        input_tokens = usage_metadata.get(\\\"input_tokens\\\", 0) or 0\\n        output_tokens = usage_metadata.get(\\\"output_tokens\\\", 0) or 0\\n        if input_tokens or output_tokens:\\n            return Usage(\\n                input_tokens=input_tokens,\\n                output_tokens=output_tokens,\\n                total_tokens=input_tokens + output_tokens,\\n            )\\n\\n    response_metadata = getattr(message, \\\"response_metadata\\\", None)\\n    if not response_metadata:\\n        return None\\n\\n    # Strategy 2: response_metadata[\\\"token_usage\\\"] (OpenAI format)\\n    if \\\"token_usage\\\" in response_metadata:\\n        token_usage = response_metadata[\\\"token_usage\\\"]\\n        return Usage(\\n            input_tokens=token_usage.get(\\\"prompt_tokens\\\"),\\n            output_tokens=token_usage.get(\\\"completion_tokens\\\"),\\n            total_tokens=token_usage.get(\\\"total_tokens\\\"),\\n        )\\n\\n    # Strategy 3: response_metadata[\\\"usage\\\"] (Anthropic format)\\n    if \\\"usage\\\" in response_metadata:\\n        usage = response_metadata[\\\"usage\\\"]\\n        input_tokens = usage.get(\\\"input_tokens\\\")\\n        output_tokens = usage.get(\\\"output_tokens\\\")\\n        return Usage(\\n            input_tokens=input_tokens,\\n            output_tokens=output_tokens,\\n            total_tokens=(input_tokens or 0) + (output_tokens or 0) if input_tokens or output_tokens else None,\\n        )\\n\\n    return None\\n\\n\\ndef extract_usage_from_llm_result(response: Any) -> Usage | None:\\n    \\\"\\\"\\\"Extract token usage from an LLMResult object.\\n\\n    Consolidates the extraction logic used by both the token usage tracking feature\\n    (TokenUsageCallbackHandler) and the traces feature (NativeCallbackHandler) into\\n    a single source of truth.\\n\\n    Tries four strategies in priority order:\\n    1. llm_output[\\\"token_usage\\\"] (legacy OpenAI path, LLMResult-specific)\\n    2. generations[].message via extract_usage_from_message() (usage_metadata, response_metadata)\\n    3. generations[].generation_info[\\\"token_usage\\\"] or [\\\"usage\\\"] (older Anthropic adapters)\\n\\n    Args:\\n        response: An LLMResult or similar object with llm_output and generations attributes.\\n\\n    Returns:\\n        Usage with token counts, or None if no usage data is available.\\n    \\\"\\\"\\\"\\n    # Strategy 1: llm_output[\\\"token_usage\\\"] (legacy OpenAI, only on LLMResult)\\n    llm_output = getattr(response, \\\"llm_output\\\", None) or {}\\n    if isinstance(llm_output, dict) and \\\"token_usage\\\" in llm_output:\\n        token_usage = llm_output[\\\"token_usage\\\"]\\n        if isinstance(token_usage, dict):\\n            input_tokens = token_usage.get(\\\"prompt_tokens\\\", 0) or 0\\n            output_tokens = token_usage.get(\\\"completion_tokens\\\", 0) or 0\\n            if input_tokens or output_tokens:\\n                return Usage(\\n                    input_tokens=input_tokens,\\n                    output_tokens=output_tokens,\\n                    total_tokens=input_tokens + output_tokens,\\n                )\\n\\n    # Iterate generations for message-level and generation_info extraction\\n    generations = getattr(response, \\\"generations\\\", None) or []\\n    for generation_list in generations:\\n        for generation in generation_list:\\n            # Strategy 2: delegate to extract_usage_from_message() for standard paths\\n            message = getattr(generation, \\\"message\\\", None)\\n            if message is not None:\\n                usage = extract_usage_from_message(message)\\n                if usage:\\n                    return usage\\n\\n            # Strategy 3: generation_info fallback (older Anthropic adapters)\\n            gen_info = getattr(generation, \\\"generation_info\\\", None) or {}\\n            if isinstance(gen_info, dict):\\n                usage_dict = gen_info.get(\\\"token_usage\\\") or gen_info.get(\\\"usage\\\")\\n                if isinstance(usage_dict, dict):\\n                    input_tokens = usage_dict.get(\\\"prompt_tokens\\\") or usage_dict.get(\\\"input_tokens\\\") or 0\\n                    output_tokens = usage_dict.get(\\\"completion_tokens\\\") or usage_dict.get(\\\"output_tokens\\\") or 0\\n                    if input_tokens or output_tokens:\\n                        return Usage(\\n                            input_tokens=input_tokens,\\n                            output_tokens=output_tokens,\\n                            total_tokens=input_tokens + output_tokens,\\n                        )\\n\\n    return None\\n\\n\\ndef extract_usage_from_chunk(chunk: Any) -> Usage | None:\\n    \\\"\\\"\\\"Extract token usage from a streaming chunk.\\n\\n    Handles both usage_metadata and response_metadata formats on streaming chunks.\\n\\n    Args:\\n        chunk: A streaming chunk (AIMessageChunk or similar).\\n\\n    Returns:\\n        Usage with token counts from this chunk, or None if no usage data.\\n    \\\"\\\"\\\"\\n    if hasattr(chunk, \\\"usage_metadata\\\") and chunk.usage_metadata:\\n        return _normalize_usage_metadata(chunk.usage_metadata)\\n\\n    if hasattr(chunk, \\\"response_metadata\\\") and chunk.response_metadata:\\n        metadata = chunk.response_metadata\\n        if \\\"token_usage\\\" in metadata:\\n            return Usage(\\n                input_tokens=metadata[\\\"token_usage\\\"].get(\\\"prompt_tokens\\\"),\\n                output_tokens=metadata[\\\"token_usage\\\"].get(\\\"completion_tokens\\\"),\\n                total_tokens=metadata[\\\"token_usage\\\"].get(\\\"total_tokens\\\"),\\n            )\\n        if \\\"usage\\\" in metadata:\\n            return Usage(\\n                input_tokens=metadata[\\\"usage\\\"].get(\\\"input_tokens\\\"),\\n                output_tokens=metadata[\\\"usage\\\"].get(\\\"output_tokens\\\"),\\n                total_tokens=None,\\n            )\\n\\n    return None\\n\\n\\ndef accumulate_usage(existing: Usage | None, new: Usage | None) -> Usage | None:\\n    \\\"\\\"\\\"Accumulate usage data across multiple chunks using max-based merge.\\n\\n    Uses max() per field instead of addition to handle both provider styles:\\n    - Anthropic splits usage across chunks (input on start, output on delta) \u2014\\n      max picks each field's value from the chunk that carries it.\\n    - OpenAI may send cumulative totals on multiple chunks \u2014 max picks the\\n      latest (largest) value without double-counting.\\n\\n    Args:\\n        existing: Previously accumulated usage, or None.\\n        new: New usage from the current chunk, or None.\\n\\n    Returns:\\n        Merged Usage, or None if both inputs are None.\\n    \\\"\\\"\\\"\\n    if new is None:\\n        return existing\\n    if existing is None:\\n        return new\\n\\n    input_tokens = max(existing.input_tokens or 0, new.input_tokens or 0)\\n    output_tokens = max(existing.output_tokens or 0, new.output_tokens or 0)\\n\\n    return Usage(\\n        input_tokens=input_tokens,\\n        output_tokens=output_tokens,\\n        total_tokens=input_tokens + output_tokens,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/validators.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"efb81832c961dcb6a423e53e75df73b6e193a6b15d1aa4972abf4def082f1f2d\",\"content\":\"from datetime import datetime, timezone\\nfrom uuid import UUID\\n\\nfrom pydantic import BeforeValidator\\n\\n# An ordered list of timestamp formats to try to parse from str, from most to least specific\\nTIMESTAMP_FORMATS = [\\n    \\\"%Y-%m-%d %H:%M:%S.%f %Z\\\",  # Standard with timezone and microseconds\\n    \\\"%Y-%m-%dT%H:%M:%S.%f%z\\\",  # ISO with numeric timezone and microseconds\\n    \\\"%Y-%m-%dT%H:%M:%S.%f\\\",  # ISO with microseconds\\n    \\\"%Y-%m-%d %H:%M:%S.%f\\\",  # Without timezone, with microseconds\\n    \\\"%Y-%m-%d %H:%M:%S %Z\\\",  # Standard with timezone\\n    \\\"%Y-%m-%dT%H:%M:%S%z\\\",  # ISO with numeric timezone\\n    \\\"%Y-%m-%dT%H:%M:%S\\\",  # ISO format\\n    \\\"%Y-%m-%d %H:%M:%S\\\",  # Without timezone\\n]\\n\\n# Formats that carry their own timezone offset \u2014 must use astimezone, not replace\\n_FORMATS_WITH_NUMERIC_TZ = {\\\"%Y-%m-%dT%H:%M:%S.%f%z\\\", \\\"%Y-%m-%dT%H:%M:%S%z\\\"}\\n\\nTF_WITH_TZ_AND_MICROSECONDS = \\\"%Y-%m-%d %H:%M:%S.%f %Z\\\"\\n\\n\\ndef timestamp_to_str(timestamp: datetime | str) -> str:\\n    \\\"\\\"\\\"Convert timestamp to standardized string format.\\n\\n    Handles multiple input formats and ensures consistent UTC timezone output.\\n\\n    Args:\\n        timestamp (datetime | str): Input timestamp either as datetime object or string\\n\\n    Returns:\\n        str: Formatted timestamp string in 'YYYY-MM-DD HH:MM:SS.ffffff UTC' format\\n\\n    Raises:\\n        ValueError: If string timestamp is in invalid format\\n    \\\"\\\"\\\"\\n    if isinstance(timestamp, str):\\n        for fmt in TIMESTAMP_FORMATS:\\n            try:\\n                parsed = datetime.strptime(timestamp.strip(), fmt)  # noqa: DTZ007\\n                if fmt in _FORMATS_WITH_NUMERIC_TZ:\\n                    parsed = parsed.astimezone(timezone.utc)\\n                else:\\n                    parsed = parsed.replace(tzinfo=timezone.utc)\\n                return parsed.strftime(TF_WITH_TZ_AND_MICROSECONDS)\\n            except ValueError:\\n                continue\\n\\n        msg = f\\\"Invalid timestamp format: {timestamp}\\\"\\n        raise ValueError(msg)\\n\\n    # Handle datetime object\\n    if timestamp.tzinfo is None:\\n        timestamp = timestamp.replace(tzinfo=timezone.utc)\\n    return timestamp.strftime(TF_WITH_TZ_AND_MICROSECONDS)\\n\\n\\ndef str_to_timestamp(timestamp: str | datetime) -> datetime:\\n    \\\"\\\"\\\"Convert timestamp to datetime object.\\n\\n    Handles multiple input formats and ensures consistent UTC timezone output.\\n\\n    Args:\\n        timestamp (str | datetime): Input timestamp either as string or datetime object\\n\\n    Returns:\\n        datetime: Datetime object with UTC timezone\\n\\n    Raises:\\n        ValueError: If string timestamp is not in a recognised format\\n    \\\"\\\"\\\"\\n    if isinstance(timestamp, str):\\n        for fmt in TIMESTAMP_FORMATS:\\n            try:\\n                parsed = datetime.strptime(timestamp.strip(), fmt)  # noqa: DTZ007\\n                if fmt in _FORMATS_WITH_NUMERIC_TZ:\\n                    return parsed.astimezone(timezone.utc)\\n                return parsed.replace(tzinfo=timezone.utc)\\n            except ValueError:\\n                continue\\n\\n        msg = f\\\"Invalid timestamp format: {timestamp}. Expected format: YYYY-MM-DD HH:MM:SS.ffffff UTC\\\"\\n        raise ValueError(msg)\\n    return timestamp\\n\\n\\ndef timestamp_with_fractional_seconds(timestamp: datetime | str) -> str:\\n    \\\"\\\"\\\"Convert timestamp to string format including fractional seconds.\\n\\n    Handles multiple input formats and ensures consistent UTC timezone output.\\n\\n    Args:\\n        timestamp (datetime | str): Input timestamp either as datetime object or string\\n\\n    Returns:\\n        str: Formatted timestamp string in 'YYYY-MM-DD HH:MM:SS.ffffff UTC' format\\n\\n    Raises:\\n        ValueError: If string timestamp is in invalid format\\n    \\\"\\\"\\\"\\n    return timestamp_to_str(timestamp)\\n\\n\\ntimestamp_to_str_validator = BeforeValidator(timestamp_to_str)\\ntimestamp_with_fractional_seconds_validator = BeforeValidator(timestamp_with_fractional_seconds)\\nstr_to_timestamp_validator = BeforeValidator(str_to_timestamp)\\n\\n\\ndef uuid_validator(uuid_str: str | UUID, message: str | None = None) -> UUID:\\n    if isinstance(uuid_str, UUID):\\n        return uuid_str\\n    try:\\n        return UUID(uuid_str)\\n    except (ValueError, AttributeError, TypeError) as e:\\n        raise ValueError(message or f\\\"Invalid UUID: {uuid_str}\\\") from e\\n\\n\\ndef null_check_validator(value: str | None, message: str | None = None) -> str | None:\\n    if value is None:\\n        raise ValueError(message or \\\"Value is required\\\")\\n    return value\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/serialization/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"83e086ed8fbe12883a9923cc23bc2a5e1e89f25632805b61aa6256ac26b73fb9\",\"content\":\"\\\"\\\"\\\"Serialization module for lfx package.\\\"\\\"\\\"\\n\\nfrom .serialization import serialize, serialize_or_str\\n\\n__all__ = [\\\"serialize\\\", \\\"serialize_or_str\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/serialization/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"98060d6daa443eef7e2a2c521d53c25d4c8cf9bb053234a809ce28864406bd06\",\"content\":\"MAX_TEXT_LENGTH = 6000\\nMAX_ITEMS_LENGTH = 1000\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/serialization/serialization.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"35d717eca5de3faf6d178475001076c3820544ac6b505a2dc99560d3893bf1a5\",\"content\":\"import math\\nfrom collections.abc import AsyncIterator, Generator, Iterator\\nfrom datetime import datetime, timezone\\nfrom decimal import Decimal\\nfrom typing import Any, cast\\nfrom uuid import UUID\\n\\nimport numpy as np\\nimport pandas as pd\\nfrom langchain_core.documents import Document\\nfrom pydantic import BaseModel\\nfrom pydantic.v1 import BaseModel as BaseModelV1\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.serialization.constants import MAX_ITEMS_LENGTH, MAX_TEXT_LENGTH\\n\\n\\ndef get_max_text_length() -> int:\\n    \\\"\\\"\\\"Return the maximum allowed text length for serialization.\\\"\\\"\\\"\\n    return MAX_TEXT_LENGTH\\n\\n\\ndef get_max_items_length() -> int:\\n    \\\"\\\"\\\"Return the maximum allowed number of items for serialization.\\\"\\\"\\\"\\n    return MAX_ITEMS_LENGTH\\n\\n\\n# Sentinel variable to signal a failed serialization.\\n# Using a helper class ensures that the sentinel is a unique object,\\n# while its __repr__ displays the desired message.\\nclass _UnserializableSentinel:\\n    def __repr__(self):\\n        return \\\"[Unserializable Object]\\\"\\n\\n\\nUNSERIALIZABLE_SENTINEL = _UnserializableSentinel()\\n\\n\\ndef _serialize_str(obj: str, max_length: int | None, _) -> str:\\n    \\\"\\\"\\\"Truncates a string to the specified maximum length, appending an ellipsis if truncation occurs.\\n\\n    Parameters:\\n        obj (str): The string to be truncated.\\n        max_length (int | None): The maximum allowed length of the string. If None, no truncation is performed.\\n\\n    Returns:\\n        str: The original or truncated string, with an ellipsis appended if truncated.\\n    \\\"\\\"\\\"\\n    if max_length is None or len(obj) <= max_length:\\n        return obj\\n    return obj[:max_length] + \\\"...\\\"\\n\\n\\ndef _serialize_bytes(obj: bytes, max_length: int | None, _) -> str:\\n    \\\"\\\"\\\"Decode bytes to string and truncate if max_length provided.\\\"\\\"\\\"\\n    if max_length is not None:\\n        return (\\n            obj[:max_length].decode(\\\"utf-8\\\", errors=\\\"ignore\\\") + \\\"...\\\"\\n            if len(obj) > max_length\\n            else obj.decode(\\\"utf-8\\\", errors=\\\"ignore\\\")\\n        )\\n    return obj.decode(\\\"utf-8\\\", errors=\\\"ignore\\\")\\n\\n\\ndef _serialize_datetime(obj: datetime, *_) -> str:\\n    \\\"\\\"\\\"Convert datetime to UTC ISO format.\\\"\\\"\\\"\\n    return obj.replace(tzinfo=timezone.utc).isoformat()\\n\\n\\ndef _serialize_decimal(obj: Decimal, *_) -> float:\\n    \\\"\\\"\\\"Convert Decimal to float.\\\"\\\"\\\"\\n    return float(obj)\\n\\n\\ndef _serialize_uuid(obj: UUID, *_) -> str:\\n    \\\"\\\"\\\"Convert UUID to string.\\\"\\\"\\\"\\n    return str(obj)\\n\\n\\ndef _serialize_document(obj: Document, max_length: int | None, max_items: int | None) -> Any:\\n    \\\"\\\"\\\"Serialize Langchain Document recursively.\\\"\\\"\\\"\\n    return serialize(obj.to_json(), max_length, max_items)\\n\\n\\ndef _serialize_iterator(_: AsyncIterator | Generator | Iterator, *__) -> str:\\n    \\\"\\\"\\\"Handle unconsumed iterators uniformly.\\\"\\\"\\\"\\n    return \\\"Unconsumed Stream\\\"\\n\\n\\ndef _serialize_pydantic(obj: BaseModel, max_length: int | None, max_items: int | None) -> Any:\\n    \\\"\\\"\\\"Handle modern Pydantic models.\\\"\\\"\\\"\\n    serialized = obj.model_dump()\\n    return {k: serialize(v, max_length, max_items) for k, v in serialized.items()}\\n\\n\\ndef _serialize_pydantic_v1(obj: BaseModelV1, max_length: int | None, max_items: int | None) -> Any:\\n    \\\"\\\"\\\"Backwards-compatible handling for Pydantic v1 models.\\\"\\\"\\\"\\n    if hasattr(obj, \\\"to_json\\\"):\\n        return serialize(obj.to_json(), max_length, max_items)\\n    return serialize(obj.dict(), max_length, max_items)\\n\\n\\ndef _serialize_dict(obj: dict, max_length: int | None, max_items: int | None) -> dict:\\n    \\\"\\\"\\\"Recursively process dictionary values.\\\"\\\"\\\"\\n    return {k: serialize(v, max_length, max_items) for k, v in obj.items()}\\n\\n\\ndef _serialize_list_tuple(obj: list | tuple, max_length: int | None, max_items: int | None) -> list:\\n    \\\"\\\"\\\"Truncate long lists and process items recursively.\\\"\\\"\\\"\\n    if max_items is not None and len(obj) > max_items:\\n        truncated = list(obj)[:max_items]\\n        truncated.append(f\\\"... [truncated {len(obj) - max_items} items]\\\")\\n        obj = truncated\\n    return [serialize(item, max_length, max_items) for item in obj]\\n\\n\\ndef _serialize_primitive(obj: Any, *_) -> Any:\\n    \\\"\\\"\\\"Handle primitive types without conversion.\\\"\\\"\\\"\\n    if obj is None or isinstance(obj, bool | int | complex):\\n        return obj\\n    if isinstance(obj, float):\\n        if math.isnan(obj) or math.isinf(obj):\\n            return None\\n        return obj\\n    return UNSERIALIZABLE_SENTINEL\\n\\n\\ndef _serialize_instance(obj: Any, *_) -> str:\\n    \\\"\\\"\\\"Handle regular class instances by converting to string.\\\"\\\"\\\"\\n    return str(obj)\\n\\n\\ndef _truncate_value(value: Any, max_length: int | None, max_items: int | None) -> Any:\\n    \\\"\\\"\\\"Truncate value based on its type and provided limits.\\\"\\\"\\\"\\n    if max_length is not None and isinstance(value, str) and len(value) > max_length:\\n        return value[:max_length]\\n    if max_items is not None and isinstance(value, list | tuple) and len(value) > max_items:\\n        return value[:max_items]\\n    return value\\n\\n\\ndef _serialize_dataframe(obj: pd.DataFrame, max_length: int | None, max_items: int | None) -> list[dict]:\\n    \\\"\\\"\\\"Serialize pandas DataFrame to a dictionary format.\\\"\\\"\\\"\\n    if max_items is not None and len(obj) > max_items:\\n        obj = obj.head(max_items)\\n\\n    data = obj.to_dict(orient=\\\"records\\\")\\n\\n    return serialize(data, max_length, max_items)\\n\\n\\ndef _serialize_series(obj: pd.Series, max_length: int | None, max_items: int | None) -> dict:\\n    \\\"\\\"\\\"Serialize pandas Series to a dictionary format.\\\"\\\"\\\"\\n    if max_items is not None and len(obj) > max_items:\\n        obj = obj.head(max_items)\\n    return {index: _truncate_value(value, max_length, max_items) for index, value in obj.items()}\\n\\n\\ndef _is_numpy_type(obj: Any) -> bool:\\n    \\\"\\\"\\\"Check if an object is a numpy type by checking its type's module name.\\\"\\\"\\\"\\n    return hasattr(type(obj), \\\"__module__\\\") and type(obj).__module__ == np.__name__\\n\\n\\ndef _serialize_numpy_type(obj: Any, max_length: int | None, max_items: int | None) -> Any:\\n    \\\"\\\"\\\"Serialize numpy types.\\\"\\\"\\\"\\n    try:\\n        # For single-element arrays\\n        if obj.size == 1 and hasattr(obj, \\\"item\\\"):\\n            return obj.item()\\n\\n        # For multi-element arrays\\n        if np.issubdtype(obj.dtype, np.number):\\n            return obj.tolist()  # Convert to Python list\\n        if np.issubdtype(obj.dtype, np.bool_):\\n            return bool(obj)\\n        if np.issubdtype(obj.dtype, np.complexfloating):\\n            return complex(cast(\\\"complex\\\", obj))\\n        if np.issubdtype(obj.dtype, np.str_):\\n            return _serialize_str(str(obj), max_length, max_items)\\n        if np.issubdtype(obj.dtype, np.bytes_) and hasattr(obj, \\\"tobytes\\\"):\\n            return _serialize_bytes(obj.tobytes(), max_length, max_items)\\n        if np.issubdtype(obj.dtype, np.object_) and hasattr(obj, \\\"item\\\"):\\n            return _serialize_instance(obj.item(), max_length, max_items)\\n    except Exception:  # noqa: BLE001\\n        return UNSERIALIZABLE_SENTINEL\\n    return UNSERIALIZABLE_SENTINEL\\n\\n\\ndef _serialize_dispatcher(obj: Any, max_length: int | None, max_items: int | None) -> Any | _UnserializableSentinel:\\n    \\\"\\\"\\\"Dispatch object to appropriate serializer.\\\"\\\"\\\"\\n    # Handle primitive types first\\n    if obj is None:\\n        return obj\\n    primitive = _serialize_primitive(obj, max_length, max_items)\\n    if primitive is not UNSERIALIZABLE_SENTINEL:\\n        return primitive\\n\\n    match obj:\\n        case str():\\n            return _serialize_str(obj, max_length, max_items)\\n        case bytes():\\n            return _serialize_bytes(obj, max_length, max_items)\\n        case datetime():\\n            return _serialize_datetime(obj, max_length, max_items)\\n        case Decimal():\\n            return _serialize_decimal(obj, max_length, max_items)\\n        case UUID():\\n            return _serialize_uuid(obj, max_length, max_items)\\n        case Document():\\n            return _serialize_document(obj, max_length, max_items)\\n        case AsyncIterator() | Generator() | Iterator():\\n            return _serialize_iterator(obj, max_length, max_items)\\n        case BaseModel():\\n            return _serialize_pydantic(obj, max_length, max_items)\\n        case BaseModelV1():\\n            return _serialize_pydantic_v1(obj, max_length, max_items)\\n        case dict():\\n            return _serialize_dict(obj, max_length, max_items)\\n        case pd.DataFrame():\\n            return _serialize_dataframe(obj, max_length, max_items)\\n        case pd.Series():\\n            return _serialize_series(obj, max_length, max_items)\\n        case list() | tuple():\\n            return _serialize_list_tuple(obj, max_length, max_items)\\n        case object() if _is_numpy_type(obj):\\n            return _serialize_numpy_type(obj, max_length, max_items)\\n        case object() if not isinstance(obj, type):  # Match any instance that's not a class\\n            return _serialize_instance(obj, max_length, max_items)\\n        case object() if hasattr(obj, \\\"_name_\\\"):  # Enum case\\n            return f\\\"{obj.__class__.__name__}.{obj._name_}\\\"\\n        case object() if hasattr(obj, \\\"__name__\\\") and hasattr(obj, \\\"__bound__\\\"):  # TypeVar case\\n            return repr(obj)\\n        case object() if hasattr(obj, \\\"__origin__\\\") or hasattr(obj, \\\"__parameters__\\\"):  # Type alias/generic case\\n            return repr(obj)\\n        case _:\\n            # Handle numpy numeric types (int, float, bool, complex)\\n            if hasattr(obj, \\\"dtype\\\"):\\n                if np.issubdtype(obj.dtype, np.number) and hasattr(obj, \\\"item\\\"):\\n                    return obj.item()\\n                if np.issubdtype(obj.dtype, np.bool_):\\n                    return bool(obj)\\n                if np.issubdtype(obj.dtype, np.complexfloating):\\n                    return complex(cast(\\\"complex\\\", obj))\\n                if np.issubdtype(obj.dtype, np.str_):\\n                    return str(obj)\\n                if np.issubdtype(obj.dtype, np.bytes_) and hasattr(obj, \\\"tobytes\\\"):\\n                    return obj.tobytes().decode(\\\"utf-8\\\", errors=\\\"ignore\\\")\\n                if np.issubdtype(obj.dtype, np.object_) and hasattr(obj, \\\"item\\\"):\\n                    return serialize(obj.item())\\n            return UNSERIALIZABLE_SENTINEL\\n\\n\\ndef serialize(\\n    obj: Any,\\n    max_length: int | None = None,\\n    max_items: int | None = None,\\n    *,\\n    to_str: bool = False,\\n) -> Any:\\n    \\\"\\\"\\\"Unified serialization with optional truncation support.\\n\\n    Coordinates specialized serializers through a dispatcher pattern.\\n    Maintains recursive processing for nested structures.\\n\\n    Args:\\n        obj: Object to serialize\\n        max_length: Maximum length for string values, None for no truncation\\n        max_items: Maximum items in list-like structures, None for no truncation\\n        to_str: If True, return a string representation of the object if serialization fails\\n    \\\"\\\"\\\"\\n    if obj is None:\\n        return None\\n    try:\\n        # First try type-specific serialization\\n        result = _serialize_dispatcher(obj, max_length, max_items)\\n        if result is not UNSERIALIZABLE_SENTINEL:  # Special check for None since it's a valid result\\n            return result\\n\\n        # Handle class-based Pydantic types and other types\\n        if isinstance(obj, type):\\n            if issubclass(obj, BaseModel | BaseModelV1):\\n                return repr(obj)\\n            return str(obj)  # Handle other class types\\n\\n        # Handle type aliases and generic types\\n        if hasattr(obj, \\\"__origin__\\\") or hasattr(obj, \\\"__parameters__\\\"):  # Type alias or generic type check\\n            try:\\n                return repr(obj)\\n            except Exception:  # noqa: BLE001\\n                logger.debug(f\\\"Error serializing object: {obj}\\\", exc_info=True)\\n\\n        # Fallback to common serialization patterns\\n        if hasattr(obj, \\\"model_dump\\\"):\\n            return serialize(obj.model_dump(), max_length, max_items)\\n        if hasattr(obj, \\\"dict\\\") and not isinstance(obj, type):\\n            return serialize(obj.dict(), max_length, max_items)\\n\\n        # Final fallback to string conversion only if explicitly requested\\n        if to_str:\\n            return str(obj)\\n\\n    except Exception:  # noqa: BLE001\\n        return \\\"[Unserializable Object]\\\"\\n    return obj\\n\\n\\ndef serialize_or_str(\\n    obj: Any,\\n    max_length: int | None = MAX_TEXT_LENGTH,\\n    max_items: int | None = MAX_ITEMS_LENGTH,\\n) -> Any:\\n    \\\"\\\"\\\"Calls serialize() and if it fails, returns a string representation of the object.\\n\\n    Args:\\n        obj: Object to serialize\\n        max_length: Maximum length for string values, None for no truncation\\n        max_items: Maximum items in list-like structures, None for no truncation\\n    \\\"\\\"\\\"\\n    return serialize(obj, max_length, max_items, to_str=True)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"43852cbeb4a031fb9a10aa1b632267b65da6544aa4fd4f08bb8b48d774e19737\",\"content\":\"\\\"\\\"\\\"LFX services module - pluggable service architecture for dependency injection.\\\"\\\"\\\"\\n\\nfrom .adapters.registry import register_adapter, teardown_all_adapter_registries\\nfrom .deps import get_deployment_adapter\\nfrom .interfaces import (\\n    AuthServiceProtocol,\\n    CacheServiceProtocol,\\n    ChatServiceProtocol,\\n    DatabaseServiceProtocol,\\n    DeploymentServiceProtocol,\\n    SettingsServiceProtocol,\\n    StorageServiceProtocol,\\n    TracingServiceProtocol,\\n    VariableServiceProtocol,\\n)\\nfrom .manager import ServiceManager\\nfrom .mcp_composer import MCPComposerService, MCPComposerServiceFactory\\nfrom .registry import register_service\\nfrom .session import NoopSession\\n\\n__all__ = [\\n    \\\"AuthServiceProtocol\\\",\\n    \\\"CacheServiceProtocol\\\",\\n    \\\"ChatServiceProtocol\\\",\\n    \\\"DatabaseServiceProtocol\\\",\\n    \\\"DeploymentServiceProtocol\\\",\\n    \\\"MCPComposerService\\\",\\n    \\\"MCPComposerServiceFactory\\\",\\n    \\\"NoopSession\\\",\\n    \\\"ServiceManager\\\",\\n    \\\"SettingsServiceProtocol\\\",\\n    \\\"StorageServiceProtocol\\\",\\n    \\\"TracingServiceProtocol\\\",\\n    \\\"VariableServiceProtocol\\\",\\n    \\\"get_deployment_adapter\\\",\\n    \\\"register_adapter\\\",\\n    \\\"register_service\\\",\\n    \\\"teardown_all_adapter_registries\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/adapters/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"05f283de471f635216bc62d41e8596df386f0791ef2dc290109dc87137cbf36c\",\"content\":\"\\\"\\\"\\\"Adapter namespaces for service-scoped plugin registries.\\\"\\\"\\\"\\n\\nfrom .payload import (\\n    AdapterPayload,\\n    AdapterPayloadMissingError,\\n    AdapterPayloadValidationError,\\n    PayloadSlot,\\n    PayloadSlotPolicy,\\n    ProviderPayloadSchemas,\\n)\\n\\n__all__ = [\\n    \\\"AdapterPayload\\\",\\n    \\\"AdapterPayloadMissingError\\\",\\n    \\\"AdapterPayloadValidationError\\\",\\n    \\\"PayloadSlot\\\",\\n    \\\"PayloadSlotPolicy\\\",\\n    \\\"ProviderPayloadSchemas\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/adapters/deployment/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c909d67375442e1be7a4ed78eebbb1c6a2296d4e9301bfa861d1b1cbbbbb2bbc\",\"content\":\"\\\"\\\"\\\"Deployment adapter package.\\\"\\\"\\\"\\n\\nfrom .base import BaseDeploymentService\\nfrom .exceptions import DeploymentError, DeploymentNotConfiguredError, DeploymentServiceError\\nfrom .payloads import (\\n    DeploymentPayloadFields,\\n    DeploymentPayloadSchemas,\\n    T_ConfigListParams,\\n    T_ConfigListResult,\\n    T_DeploymentConfig,\\n    T_DeploymentCreateResult,\\n    T_DeploymentItemData,\\n    T_DeploymentListParams,\\n    T_DeploymentListResult,\\n    T_DeploymentOperationResult,\\n    T_DeploymentSpec,\\n    T_DeploymentStatusData,\\n    T_DeploymentUpdate,\\n    T_ExecutionInput,\\n    T_ExecutionResult,\\n    T_ListParamsPayload,\\n    T_ProviderData,\\n    T_ProviderResult,\\n    T_SnapshotListParams,\\n    T_SnapshotListResult,\\n    T_SnapshotUpdateResult,\\n)\\nfrom .service import DeploymentService\\n\\n__all__ = [\\n    \\\"BaseDeploymentService\\\",\\n    \\\"DeploymentError\\\",\\n    \\\"DeploymentNotConfiguredError\\\",\\n    \\\"DeploymentPayloadFields\\\",\\n    \\\"DeploymentPayloadSchemas\\\",\\n    \\\"DeploymentService\\\",\\n    \\\"DeploymentServiceError\\\",\\n    \\\"T_ConfigListParams\\\",\\n    \\\"T_ConfigListResult\\\",\\n    \\\"T_DeploymentConfig\\\",\\n    \\\"T_DeploymentCreateResult\\\",\\n    \\\"T_DeploymentItemData\\\",\\n    \\\"T_DeploymentListParams\\\",\\n    \\\"T_DeploymentListResult\\\",\\n    \\\"T_DeploymentOperationResult\\\",\\n    \\\"T_DeploymentSpec\\\",\\n    \\\"T_DeploymentStatusData\\\",\\n    \\\"T_DeploymentUpdate\\\",\\n    \\\"T_ExecutionInput\\\",\\n    \\\"T_ExecutionResult\\\",\\n    \\\"T_ListParamsPayload\\\",\\n    \\\"T_ProviderData\\\",\\n    \\\"T_ProviderResult\\\",\\n    \\\"T_SnapshotListParams\\\",\\n    \\\"T_SnapshotListResult\\\",\\n    \\\"T_SnapshotUpdateResult\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/adapters/deployment/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c29278020b79c7373fe60a824589277a23b112ab7eb933ecf0a134830288a6b2\",\"content\":\"\\\"\\\"\\\"Deployment service base class.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom abc import ABC, abstractmethod\\nfrom typing import TYPE_CHECKING, ClassVar\\n\\nfrom lfx.services.base import Service\\n\\nif TYPE_CHECKING:\\n    from sqlalchemy.ext.asyncio import AsyncSession\\n\\n    from lfx.services.adapters.deployment.payloads import DeploymentPayloadSchemas\\n    from lfx.services.adapters.deployment.schema import (\\n        ConfigListParams,\\n        ConfigListResult,\\n        DeploymentCreate,\\n        DeploymentCreateResult,\\n        DeploymentDeleteResult,\\n        DeploymentDuplicateResult,\\n        DeploymentGetResult,\\n        DeploymentListLlmsResult,\\n        DeploymentListParams,\\n        DeploymentListResult,\\n        DeploymentListTypesResult,\\n        DeploymentStatusResult,\\n        DeploymentType,\\n        DeploymentUpdate,\\n        DeploymentUpdateResult,\\n        ExecutionCreate,\\n        ExecutionCreateResult,\\n        ExecutionStatusResult,\\n        IdLike,\\n        RedeployResult,\\n        SnapshotListParams,\\n        SnapshotListResult,\\n        VerifyCredentials,\\n        VerifyCredentialsResult,\\n    )\\n    from lfx.services.interfaces import DeploymentServiceProtocol\\n\\n\\nclass BaseDeploymentService(Service, ABC):\\n    \\\"\\\"\\\"Abstract base class for deployment provider services.\\n\\n    Defines the minimal interface that all deployment service implementations\\n    must provide, whether minimal (LFX) or full-featured (Langflow).\\n\\n    Note:\\n        ``db`` parameters are typed as ``AsyncSession`` to align with current\\n        LFX dependency injection and service protocols.\\n    \\\"\\\"\\\"\\n\\n    payload_schemas: ClassVar[DeploymentPayloadSchemas | None] = None\\n\\n    @abstractmethod\\n    async def create(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        payload: DeploymentCreate,\\n        db: AsyncSession,\\n    ) -> DeploymentCreateResult:\\n        \\\"\\\"\\\"Create a new deployment in the provider.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def list_types(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        db: AsyncSession,\\n    ) -> DeploymentListTypesResult:\\n        \\\"\\\"\\\"List deployment types supported by the provider.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def list_llms(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        db: AsyncSession,\\n    ) -> DeploymentListLlmsResult:\\n        \\\"\\\"\\\"List provider-available LLM model names for deployment configuration.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def list(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        params: DeploymentListParams | None = None,\\n        db: AsyncSession,\\n    ) -> DeploymentListResult:\\n        \\\"\\\"\\\"List deployments visible to this adapter.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def get(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> DeploymentGetResult:\\n        \\\"\\\"\\\"Return deployment metadata by provider ID.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def update(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        payload: DeploymentUpdate,\\n        db: AsyncSession,\\n    ) -> DeploymentUpdateResult:\\n        \\\"\\\"\\\"Update deployment inputs and apply changes in the provider.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def redeploy(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> RedeployResult:\\n        \\\"\\\"\\\"Re-apply current deployment inputs without changing them.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def duplicate(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> DeploymentDuplicateResult:\\n        \\\"\\\"\\\"Create a new deployment using the same inputs as the source.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def delete(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> DeploymentDeleteResult:\\n        \\\"\\\"\\\"Delete the deployment from the provider.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def get_status(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> DeploymentStatusResult:\\n        \\\"\\\"\\\"Return provider-reported health/status for the deployment.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def create_execution(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        payload: ExecutionCreate,\\n        db: AsyncSession,\\n    ) -> ExecutionCreateResult:\\n        \\\"\\\"\\\"Run a provider-agnostic deployment execution.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def get_execution(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        execution_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> ExecutionStatusResult:\\n        \\\"\\\"\\\"Get provider-agnostic deployment execution state/output.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def list_configs(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        params: ConfigListParams | None = None,\\n        db: AsyncSession,\\n    ) -> ConfigListResult:\\n        \\\"\\\"\\\"List configs visible to this adapter.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def list_snapshots(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        params: SnapshotListParams | None = None,\\n        db: AsyncSession,\\n    ) -> SnapshotListResult:\\n        \\\"\\\"\\\"List snapshots visible to this adapter.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def verify_credentials(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        payload: VerifyCredentials,\\n    ) -> VerifyCredentialsResult:\\n        \\\"\\\"\\\"Verify provider credentials before account creation.\\\"\\\"\\\"\\n\\n\\nif TYPE_CHECKING:\\n    # Static assertion: keep ABC API in sync with the consumer protocol.\\n    _: type[DeploymentServiceProtocol] = BaseDeploymentService\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/adapters/deployment/exceptions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4b6861eff41811b9934d913cacdfd28bfac95d9107e0d7734f5cce62eddad972\",\"content\":\"\\\"\\\"\\\"Framework-agnostic deployment exceptions for LFX deployment service.\\n\\nShared exception types for all deployment service implementations,\\nregardless of adapter.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import NoReturn\\n\\nfrom fastapi import status\\n\\n\\nclass DeploymentServiceError(Exception):\\n    \\\"\\\"\\\"Root exception for all deployment service failures.\\n\\n    Both operational errors (:class:`DeploymentError`) and authentication\\n    or authorization errors (:class:`AuthenticationError`, :class:`AuthorizationError`)\\n    inherit from this class.\\n    Catch this only when you truly want to handle *every* deployment-related\\n    failure uniformly.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, message: str, *, error_code: str, cause: Exception | None = None):\\n        self.message = message\\n        self.error_code = error_code\\n        self.cause = cause\\n        super().__init__(message)\\n        if cause is not None:\\n            self.__cause__ = cause\\n\\n\\nclass DeploymentError(DeploymentServiceError):\\n    \\\"\\\"\\\"Base exception for deployment operation failures (non-auth).\\\"\\\"\\\"\\n\\n\\nclass AuthenticationError(DeploymentServiceError):\\n    \\\"\\\"\\\"Base exception for authentication failures.\\n\\n    Intentionally a sibling of :class:`DeploymentError`, not a child.\\n    This ensures ``except DeploymentError`` will not accidentally swallow\\n    authentication failures, allowing API layers to return the correct\\n    HTTP status (401/403) separately from deployment errors (400/404/409/422).\\n\\n    Please ensure that the message does not leak sensitive information.\\n    \\\"\\\"\\\"\\n\\n\\nclass AuthorizationError(DeploymentServiceError):\\n    \\\"\\\"\\\"Base exception for authorization failures (authenticated but forbidden).\\n\\n    Intentionally a sibling of :class:`DeploymentError`, not a child.\\n    This ensures ``except DeploymentError`` will not accidentally swallow\\n    authorization failures, allowing API layers to return status 403\\n    separately from deployment errors (400/404/409/422).\\n\\n    Please ensure that the message does not leak sensitive information.\\n    \\\"\\\"\\\"\\n\\n\\nclass CredentialResolutionError(AuthenticationError):\\n    \\\"\\\"\\\"Raised when credentials resolution fails.\\n\\n    Please ensure that the message does not leak sensitive information.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, message: str = \\\"Credentials resolution failed\\\", *, cause: Exception | None = None):\\n        super().__init__(message, error_code=\\\"credentials_resolution_error\\\", cause=cause)\\n\\n\\nclass ResourceConflictError(DeploymentError):\\n    \\\"\\\"\\\"Raised when a deployment conflict occurs.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        message: str = \\\"Deployment conflict occurred\\\",\\n        *,\\n        resource: str | None = None,\\n        resource_name: str | None = None,\\n        cause: Exception | None = None,\\n    ):\\n        self.resource = str(resource).strip().lower() if resource is not None else None\\n        self.resource_name = str(resource_name).strip() or None if resource_name is not None else None\\n        super().__init__(message, error_code=\\\"deployment_conflict\\\", cause=cause)\\n\\n\\nclass InvalidContentError(DeploymentError):\\n    \\\"\\\"\\\"Raised when a deployment request entity is unprocessable.\\\"\\\"\\\"\\n\\n    def __init__(self, message: str = \\\"Deployment request entity is unprocessable\\\", *, cause: Exception | None = None):\\n        super().__init__(message, error_code=\\\"unprocessable_content_error\\\", cause=cause)\\n\\n\\nclass InvalidDeploymentOperationError(DeploymentError):\\n    \\\"\\\"\\\"Raised when a deployment operation is invalid for current adapter semantics.\\\"\\\"\\\"\\n\\n    def __init__(self, message: str = \\\"Invalid deployment operation\\\", *, cause: Exception | None = None):\\n        super().__init__(message, error_code=\\\"invalid_deployment_operation\\\", cause=cause)\\n\\n\\nclass DeploymentSupportError(DeploymentError):\\n    \\\"\\\"\\\"Raised when a known deployment type is unsupported by this adapter.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        message: str = \\\"Deployment type is unsupported by this adapter\\\",\\n        *,\\n        cause: Exception | None = None,\\n    ):\\n        super().__init__(message, error_code=\\\"unsupported_deployment_type\\\", cause=cause)\\n\\n\\nclass RateLimitError(DeploymentError):\\n    \\\"\\\"\\\"Raised when provider/API rate limits deployment operations.\\\"\\\"\\\"\\n\\n    def __init__(self, message: str = \\\"Deployment operation rate limited\\\", *, cause: Exception | None = None):\\n        super().__init__(message, error_code=\\\"deployment_rate_limited\\\", cause=cause)\\n\\n\\nclass DeploymentTimeoutError(DeploymentError):\\n    \\\"\\\"\\\"Raised when deployment operation times out.\\\"\\\"\\\"\\n\\n    def __init__(self, message: str = \\\"Deployment operation timed out\\\", *, cause: Exception | None = None):\\n        super().__init__(message, error_code=\\\"deployment_timeout\\\", cause=cause)\\n\\n\\nclass ServiceUnavailableError(DeploymentError):\\n    \\\"\\\"\\\"Raised when upstream provider is temporarily unavailable.\\\"\\\"\\\"\\n\\n    def __init__(self, message: str = \\\"Deployment provider is unavailable\\\", *, cause: Exception | None = None):\\n        super().__init__(message, error_code=\\\"deployment_provider_unavailable\\\", cause=cause)\\n\\n\\nclass AuthSchemeError(AuthenticationError):\\n    \\\"\\\"\\\"Raised when no matching authentication scheme was found.\\n\\n    Please ensure that the message does not leak sensitive information.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, message: str = \\\"No matching authentication scheme was found\\\", *, cause: Exception | None = None):\\n        super().__init__(message, error_code=\\\"unsupported_auth_type\\\", cause=cause)\\n\\n\\nclass InvalidDeploymentTypeError(DeploymentError):\\n    \\\"\\\"\\\"Raised when an input deployment type is malformed or not recognized.\\\"\\\"\\\"\\n\\n    def __init__(self, message: str = \\\"Deployment type is malformed or unknown\\\", *, cause: Exception | None = None):\\n        super().__init__(message, error_code=\\\"invalid_deployment_type\\\", cause=cause)\\n\\n\\nclass ResourceNotFoundError(DeploymentError):\\n    \\\"\\\"\\\"Raised when a requested deployment-related resource is not found.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        message: str | None = None,\\n        *,\\n        resource_id: str | None = None,\\n        cause: Exception | None = None,\\n    ):\\n        self.resource_id = resource_id\\n        if message is None:\\n            message = \\\"Resource not found\\\"\\n            if resource_id:\\n                message = f\\\"Resource not found: {resource_id}\\\"\\n        super().__init__(message, error_code=\\\"resource_not_found\\\", cause=cause)\\n\\n\\nclass DeploymentNotFoundError(ResourceNotFoundError):\\n    \\\"\\\"\\\"Raised when a deployment is not found.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        message: str | None = None,\\n        *,\\n        deployment_id: str | None = None,\\n        cause: Exception | None = None,\\n    ):\\n        self.deployment_id = deployment_id\\n        if message is None:\\n            message = \\\"Deployment not found\\\"\\n            if deployment_id:\\n                message = f\\\"Deployment not found: {deployment_id}\\\"\\n        super().__init__(message=message, resource_id=deployment_id, cause=cause)\\n        self.error_code = \\\"deployment_not_found\\\"\\n\\n\\nclass OperationNotSupportedError(DeploymentError):\\n    \\\"\\\"\\\"Raised when a deployment operation is not supported by the current adapter.\\n\\n    Use this for operations that are valid in the abstract contract but\\n    are not implemented by the active adapter (e.g. ``redeploy`` or\\n    ``duplicate`` on a provider that does not support them).\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        message: str = \\\"This operation is not supported by the current deployment adapter.\\\",\\n        *,\\n        cause: Exception | None = None,\\n    ):\\n        super().__init__(message, error_code=\\\"operation_not_supported\\\", cause=cause)\\n\\n\\nclass DeploymentNotConfiguredError(DeploymentError):\\n    \\\"\\\"\\\"Raised when no concrete deployment adapter has been registered.\\n\\n    The stub :class:`~lfx.services.adapters.deployment.service.DeploymentService` raises\\n    this for every operation so that callers receive a domain exception rather\\n    than a bare ``NotImplementedError``.\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        message: str = (\\n            \\\"No deployment adapter is registered. Register a concrete adapter to enable deployment operations.\\\"\\n        ),\\n        *,\\n        method: str | None = None,\\n        cause: Exception | None = None,\\n    ):\\n        if method is not None:\\n            message = (\\n                f\\\"DeploymentService.{method}() requires a concrete deployment adapter. \\\"\\n                \\\"Register one to enable deployment operations.\\\"\\n            )\\n        super().__init__(message, error_code=\\\"deployment_not_configured\\\", cause=cause)\\n\\n\\ndef http_status_for_deployment_error(exc: DeploymentServiceError) -> int:\\n    \\\"\\\"\\\"Return the HTTP status code that best represents a domain exception.\\n\\n    This is the inverse of :func:`raise_as_deployment_error`: given a\\n    domain exception instance, it returns the HTTP status code that an API\\n    layer should use when surfacing the error to a client.\\n\\n    Order mirrors the except-chain priority in the Langflow route layer:\\n    more specific exception types are checked before their parents.\\n    \\\"\\\"\\\"\\n    if isinstance(exc, ResourceConflictError):\\n        return status.HTTP_409_CONFLICT\\n    if isinstance(exc, InvalidDeploymentOperationError):\\n        return status.HTTP_400_BAD_REQUEST\\n    if isinstance(exc, DeploymentSupportError):\\n        return status.HTTP_400_BAD_REQUEST\\n    if isinstance(exc, InvalidDeploymentTypeError):\\n        return status.HTTP_400_BAD_REQUEST\\n    if isinstance(exc, InvalidContentError):\\n        return status.HTTP_422_UNPROCESSABLE_CONTENT\\n    if isinstance(exc, DeploymentNotFoundError):\\n        return status.HTTP_404_NOT_FOUND\\n    if isinstance(exc, ResourceNotFoundError):\\n        return status.HTTP_404_NOT_FOUND\\n    if isinstance(exc, RateLimitError):\\n        return status.HTTP_429_TOO_MANY_REQUESTS\\n    if isinstance(exc, DeploymentTimeoutError):\\n        return status.HTTP_408_REQUEST_TIMEOUT\\n    if isinstance(exc, ServiceUnavailableError):\\n        return status.HTTP_503_SERVICE_UNAVAILABLE\\n    if isinstance(exc, OperationNotSupportedError):\\n        return status.HTTP_501_NOT_IMPLEMENTED\\n    if isinstance(exc, DeploymentNotConfiguredError):\\n        return status.HTTP_503_SERVICE_UNAVAILABLE\\n    if isinstance(exc, AuthenticationError):\\n        return status.HTTP_401_UNAUTHORIZED\\n    if isinstance(exc, AuthorizationError):\\n        return status.HTTP_403_FORBIDDEN\\n    if isinstance(exc, DeploymentError):\\n        return status.HTTP_500_INTERNAL_SERVER_ERROR\\n    return status.HTTP_500_INTERNAL_SERVER_ERROR\\n\\n\\n# lru+ttl cache?\\ndef raise_as_deployment_error(\\n    *,\\n    status_code: int | None,\\n    detail: str,\\n    message_prefix: str | None = None,\\n    resource: str | None = None,\\n    resource_name: str | None = None,\\n    cause: Exception | None = None,\\n) -> NoReturn:\\n    \\\"\\\"\\\"Raise domain-specific deployment exceptions based on HTTP-like status/detail.\\n\\n    When *cause* is ``None`` (the default), implicit exception chaining is\\n    suppressed (``raise \u2026 from None``).  Pass the original exception as\\n    *cause* to preserve the traceback chain for debugging.  Callers that\\n    handle security-sensitive errors (e.g. credential verification) should\\n    set it to None to avoid leaking provider responses through the exception chain.\\n\\n    For conflict errors, callers should pass ``resource`` and ``resource_name``\\n    whenever known. This helper does not infer conflict hints from free-form\\n    provider detail text.\\n    \\\"\\\"\\\"\\n    detail_text = str(detail)\\n    detail_lower = detail_text.lower()\\n    prefix = str(message_prefix or \\\"\\\").strip()\\n    message = f\\\"{prefix} error details: {detail_text}\\\" if prefix else detail_text\\n\\n    if status_code == status.HTTP_401_UNAUTHORIZED:\\n        raise AuthenticationError(message=message, error_code=\\\"authentication_error\\\", cause=cause) from cause\\n    if status_code == status.HTTP_403_FORBIDDEN:\\n        raise AuthorizationError(message=message, error_code=\\\"authorization_error\\\", cause=cause) from cause\\n    if status_code == status.HTTP_422_UNPROCESSABLE_CONTENT:\\n        raise InvalidContentError(message=message, cause=cause) from cause\\n    if status_code == status.HTTP_400_BAD_REQUEST:\\n        raise InvalidDeploymentOperationError(message=message, cause=cause) from cause\\n    if status_code == status.HTTP_405_METHOD_NOT_ALLOWED:\\n        raise InvalidDeploymentOperationError(message=message, cause=cause) from cause\\n    if status_code == status.HTTP_413_CONTENT_TOO_LARGE:\\n        raise InvalidContentError(message=message, cause=cause) from cause\\n    if status_code == status.HTTP_415_UNSUPPORTED_MEDIA_TYPE:\\n        raise InvalidContentError(message=message, cause=cause) from cause\\n    if status_code == status.HTTP_404_NOT_FOUND:\\n        raise ResourceNotFoundError(message, cause=cause) from cause\\n    if status_code == status.HTTP_410_GONE:\\n        raise ResourceNotFoundError(message, cause=cause) from cause\\n    if status_code == status.HTTP_409_CONFLICT:\\n        raise ResourceConflictError(\\n            message=message,\\n            resource=resource,\\n            resource_name=resource_name,\\n            cause=cause,\\n        ) from cause\\n    if status_code == status.HTTP_429_TOO_MANY_REQUESTS:\\n        raise RateLimitError(message=message, cause=cause) from cause\\n    if status_code in {status.HTTP_408_REQUEST_TIMEOUT, status.HTTP_504_GATEWAY_TIMEOUT}:\\n        raise DeploymentTimeoutError(message=message, cause=cause) from cause\\n    if status_code in {status.HTTP_502_BAD_GATEWAY, status.HTTP_503_SERVICE_UNAVAILABLE}:\\n        raise ServiceUnavailableError(message=message, cause=cause) from cause\\n    if \\\"not found\\\" in detail_lower:\\n        raise ResourceNotFoundError(message, cause=cause) from cause\\n    if \\\"already exists\\\" in detail_lower or \\\"conflict\\\" in detail_lower:\\n        raise ResourceConflictError(\\n            message=message,\\n            resource=resource,\\n            resource_name=resource_name,\\n            cause=cause,\\n        ) from cause\\n    if \\\"unprocessable\\\" in detail_lower:\\n        raise InvalidContentError(message=message, cause=cause) from cause\\n    if \\\"too many requests\\\" in detail_lower or \\\"rate limit\\\" in detail_lower:\\n        raise RateLimitError(message=message, cause=cause) from cause\\n    if \\\"timed out\\\" in detail_lower or \\\"timeout\\\" in detail_lower:\\n        raise DeploymentTimeoutError(message=message, cause=cause) from cause\\n    if (\\n        \\\"service unavailable\\\" in detail_lower\\n        or \\\"temporarily unavailable\\\" in detail_lower\\n        or \\\"bad gateway\\\" in detail_lower\\n    ):\\n        raise ServiceUnavailableError(message=message, cause=cause) from cause\\n    if \\\"unauthorized\\\" in detail_lower or \\\"authentication\\\" in detail_lower:\\n        raise AuthenticationError(message=message, error_code=\\\"authentication_error\\\", cause=cause) from cause\\n    if \\\"forbidden\\\" in detail_lower or \\\"permission\\\" in detail_lower or \\\"not allowed\\\" in detail_lower:\\n        raise AuthorizationError(message=message, error_code=\\\"authorization_error\\\", cause=cause) from cause\\n    if \\\"bad request\\\" in detail_lower:\\n        raise InvalidDeploymentOperationError(message=message, cause=cause) from cause\\n    if (\\n        \\\"invalid\\\" in detail_lower\\n        or \\\"missing\\\" in detail_lower\\n        or \\\"required\\\" in detail_lower\\n        or \\\"malformed\\\" in detail_lower\\n    ):\\n        raise InvalidContentError(message=message, cause=cause) from cause\\n    raise DeploymentError(message=message, error_code=\\\"deployment_error\\\", cause=cause) from cause\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/adapters/deployment/payloads.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1124f468c0bb580e40cee19d423699e8ab297abd07f3f63ab2aece9f55cad793\",\"content\":\"\\\"\\\"\\\"Deployment payload slot taxonomy shared across adapter and API layers.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import dataclass\\n\\nfrom pydantic import BaseModel\\nfrom typing_extensions import TypeVar\\n\\nfrom lfx.services.adapters.payload import AdapterPayload, PayloadSlot, ProviderPayloadSchemas\\n\\n# This pairing is an explicit boundary design:\\n# - payload value typevars default to dict for open provider extension points\\n# - slot model typevars are BaseModel-bound for strict parse/dump contracts\\n# Together this preserves a stable pluggable surface while keeping validation\\n# strict at slot boundaries.\\n# Inbound payload pairs\\nT_DeploymentSpec = TypeVar(\\\"T_DeploymentSpec\\\", default=AdapterPayload)\\nT_DeploymentSpecModel = TypeVar(\\\"T_DeploymentSpecModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_DeploymentConfig = TypeVar(\\\"T_DeploymentConfig\\\", default=AdapterPayload)\\nT_DeploymentConfigModel = TypeVar(\\\"T_DeploymentConfigModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_DeploymentUpdate = TypeVar(\\\"T_DeploymentUpdate\\\", default=AdapterPayload)\\nT_DeploymentUpdateModel = TypeVar(\\\"T_DeploymentUpdateModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_DeploymentCreate = TypeVar(\\\"T_DeploymentCreate\\\", default=AdapterPayload)\\nT_DeploymentCreateModel = TypeVar(\\\"T_DeploymentCreateModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_ExecutionInput = TypeVar(\\\"T_ExecutionInput\\\", default=AdapterPayload)\\nT_ExecutionInputModel = TypeVar(\\\"T_ExecutionInputModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_DeploymentListParams = TypeVar(\\\"T_DeploymentListParams\\\", default=AdapterPayload)\\nT_DeploymentListParamsModel = TypeVar(\\\"T_DeploymentListParamsModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_ConfigListParams = TypeVar(\\\"T_ConfigListParams\\\", default=AdapterPayload)\\nT_ConfigListParamsModel = TypeVar(\\\"T_ConfigListParamsModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_SnapshotListParams = TypeVar(\\\"T_SnapshotListParams\\\", default=AdapterPayload)\\nT_SnapshotListParamsModel = TypeVar(\\\"T_SnapshotListParamsModel\\\", bound=BaseModel, default=BaseModel)\\n\\n# Verify credentials pairs \u2014 credentials are provider-specific and carried\\n# in provider_data rather than as top-level fields on the base schema.\\nT_VerifyCredentials = TypeVar(\\\"T_VerifyCredentials\\\", default=AdapterPayload)\\nT_VerifyCredentialsModel = TypeVar(\\\"T_VerifyCredentialsModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_VerifyCredentialsResult = TypeVar(\\\"T_VerifyCredentialsResult\\\", default=AdapterPayload)\\nT_VerifyCredentialsResultModel = TypeVar(\\\"T_VerifyCredentialsResultModel\\\", bound=BaseModel, default=BaseModel)\\n\\n# Flow artifact provider_data pair\\nT_FlowProviderData = TypeVar(\\\"T_FlowProviderData\\\", default=AdapterPayload)\\nT_FlowProviderDataModel = TypeVar(\\\"T_FlowProviderDataModel\\\", bound=BaseModel, default=BaseModel)\\nT_SnapshotItemData = TypeVar(\\\"T_SnapshotItemData\\\", default=AdapterPayload)\\nT_SnapshotItemDataModel = TypeVar(\\\"T_SnapshotItemDataModel\\\", bound=BaseModel, default=BaseModel)\\nT_ConfigItemData = TypeVar(\\\"T_ConfigItemData\\\", default=AdapterPayload)\\nT_ConfigItemDataModel = TypeVar(\\\"T_ConfigItemDataModel\\\", bound=BaseModel, default=BaseModel)\\n\\n# Outbound payload pairs\\nT_DeploymentCreateResult = TypeVar(\\\"T_DeploymentCreateResult\\\", default=AdapterPayload)\\nT_DeploymentCreateResultModel = TypeVar(\\\"T_DeploymentCreateResultModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_DeploymentOperationResult = TypeVar(\\\"T_DeploymentOperationResult\\\", default=AdapterPayload)\\nT_DeploymentOperationResultModel = TypeVar(\\\"T_DeploymentOperationResultModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_DeploymentUpdateResult = TypeVar(\\\"T_DeploymentUpdateResult\\\", default=AdapterPayload)\\nT_DeploymentUpdateResultModel = TypeVar(\\\"T_DeploymentUpdateResultModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_DeploymentListResult = TypeVar(\\\"T_DeploymentListResult\\\", default=AdapterPayload)\\nT_DeploymentListResultModel = TypeVar(\\\"T_DeploymentListResultModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_DeploymentLlmListResult = TypeVar(\\\"T_DeploymentLlmListResult\\\", default=AdapterPayload)\\nT_DeploymentLlmListResultModel = TypeVar(\\\"T_DeploymentLlmListResultModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_ConfigListResult = TypeVar(\\\"T_ConfigListResult\\\", default=AdapterPayload)\\nT_ConfigListResultModel = TypeVar(\\\"T_ConfigListResultModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_SnapshotListResult = TypeVar(\\\"T_SnapshotListResult\\\", default=AdapterPayload)\\nT_SnapshotListResultModel = TypeVar(\\\"T_SnapshotListResultModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_SnapshotUpdateResult = TypeVar(\\\"T_SnapshotUpdateResult\\\", default=AdapterPayload)\\n\\nT_ExecutionResult = TypeVar(\\\"T_ExecutionResult\\\", default=AdapterPayload)\\nT_ExecutionResultModel = TypeVar(\\\"T_ExecutionResultModel\\\", bound=BaseModel, default=BaseModel)\\nT_ExecutionCreateResult = TypeVar(\\\"T_ExecutionCreateResult\\\", default=AdapterPayload)\\nT_ExecutionCreateResultModel = TypeVar(\\\"T_ExecutionCreateResultModel\\\", bound=BaseModel, default=BaseModel)\\nT_ExecutionStatusResult = TypeVar(\\\"T_ExecutionStatusResult\\\", default=AdapterPayload)\\nT_ExecutionStatusResultModel = TypeVar(\\\"T_ExecutionStatusResultModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_DeploymentItemData = TypeVar(\\\"T_DeploymentItemData\\\", default=AdapterPayload)\\nT_DeploymentItemDataModel = TypeVar(\\\"T_DeploymentItemDataModel\\\", bound=BaseModel, default=BaseModel)\\n\\nT_DeploymentStatusData = TypeVar(\\\"T_DeploymentStatusData\\\", default=AdapterPayload)\\nT_DeploymentStatusDataModel = TypeVar(\\\"T_DeploymentStatusDataModel\\\", bound=BaseModel, default=BaseModel)\\n\\n# Shared payload-only typevars\\nT_ProviderData = TypeVar(\\\"T_ProviderData\\\", default=AdapterPayload)\\nT_ProviderResult = TypeVar(\\\"T_ProviderResult\\\", default=AdapterPayload)\\nT_ListParamsPayload = TypeVar(\\\"T_ListParamsPayload\\\", default=AdapterPayload)\\n\\n\\n@dataclass(frozen=True)\\nclass DeploymentPayloadFields(ProviderPayloadSchemas):\\n    \\\"\\\"\\\"Canonical deployment payload slot names for all providers.\\n\\n    Outbound slots are intentionally operation-specific (create, operation,\\n    deployment list, config list, snapshot list, execution) so providers can\\n    expose distinct payload contracts per operation without sharing one\\n    umbrella ``deployment_result`` shape.\\n\\n    Ownership boundary:\\n    this module defines *slot names* (shared structure) for both layers.\\n    Slot population is layer-specific:\\n    - adapters populate ``DeploymentPayloadSchemas`` (adapter-side contracts)\\n    - Langflow mappers populate ``DeploymentApiPayloads`` (API-side contracts)\\n    \\\"\\\"\\\"\\n\\n    # Inbound (request -> adapter)\\n    deployment_spec: PayloadSlot[T_DeploymentSpecModel] | None = None\\n    deployment_create: PayloadSlot[T_DeploymentCreateModel] | None = None\\n    deployment_config: PayloadSlot[T_DeploymentConfigModel] | None = None\\n    deployment_update: PayloadSlot[T_DeploymentUpdateModel] | None = None\\n    execution_input: PayloadSlot[T_ExecutionInputModel] | None = None\\n    deployment_list_params: PayloadSlot[T_DeploymentListParamsModel] | None = None\\n    config_list_params: PayloadSlot[T_ConfigListParamsModel] | None = None\\n    snapshot_list_params: PayloadSlot[T_SnapshotListParamsModel] | None = None\\n    flow_artifact: PayloadSlot[T_FlowProviderDataModel] | None = None\\n    verify_credentials: PayloadSlot[T_VerifyCredentialsModel] | None = None\\n\\n    # Outbound (adapter -> response)\\n    deployment_create_result: PayloadSlot[T_DeploymentCreateResultModel] | None = None\\n    deployment_operation_result: PayloadSlot[T_DeploymentOperationResultModel] | None = None\\n    deployment_update_result: PayloadSlot[T_DeploymentUpdateResultModel] | None = None\\n    deployment_list_result: PayloadSlot[T_DeploymentListResultModel] | None = None\\n    deployment_llm_list_result: PayloadSlot[T_DeploymentLlmListResultModel] | None = None\\n    config_list_result: PayloadSlot[T_ConfigListResultModel] | None = None\\n    config_item_data: PayloadSlot[T_ConfigItemDataModel] | None = None\\n    snapshot_list_result: PayloadSlot[T_SnapshotListResultModel] | None = None\\n    snapshot_item_data: PayloadSlot[T_SnapshotItemDataModel] | None = None\\n    execution_create_result: PayloadSlot[T_ExecutionCreateResultModel] | None = None\\n    execution_status_result: PayloadSlot[T_ExecutionStatusResultModel] | None = None\\n    deployment_item_data: PayloadSlot[T_DeploymentItemDataModel] | None = None\\n    deployment_status_data: PayloadSlot[T_DeploymentStatusDataModel] | None = None\\n    verify_credentials_result: PayloadSlot[T_VerifyCredentialsResultModel] | None = None\\n\\n\\n@dataclass(frozen=True)\\nclass DeploymentPayloadSchemas(DeploymentPayloadFields):\\n    \\\"\\\"\\\"Adapter-side payload schema registry for deployment providers.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/adapters/deployment/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d27ef19f4429e2111201f77f1553949d1d719e71f6f6247dcd3ca2da90d1db25\",\"content\":\"import datetime\\nimport json\\nfrom enum import Enum\\nfrom functools import lru_cache\\nfrom typing import Annotated, Generic\\nfrom uuid import UUID\\n\\nfrom pydantic import BaseModel, ConfigDict, Field, StringConstraints, field_validator, model_validator\\n\\nfrom lfx.services.adapters.deployment.payloads import (\\n    T_ConfigItemData,\\n    T_ConfigListParams,\\n    T_ConfigListResult,\\n    T_DeploymentConfig,\\n    T_DeploymentCreate,\\n    T_DeploymentCreateResult,\\n    T_DeploymentItemData,\\n    T_DeploymentListParams,\\n    T_DeploymentListResult,\\n    T_DeploymentLlmListResult,\\n    T_DeploymentOperationResult,\\n    T_DeploymentStatusData,\\n    T_DeploymentUpdate,\\n    T_DeploymentUpdateResult,\\n    T_ExecutionCreateResult,\\n    T_ExecutionInput,\\n    T_ExecutionResult,\\n    T_ExecutionStatusResult,\\n    T_FlowProviderData,\\n    T_ListParamsPayload,\\n    T_ProviderData,\\n    T_ProviderResult,\\n    T_SnapshotItemData,\\n    T_SnapshotListParams,\\n    T_SnapshotListResult,\\n    T_SnapshotUpdateResult,\\n    T_VerifyCredentials,\\n    T_VerifyCredentialsResult,\\n)\\nfrom lfx.services.adapters.payload import AdapterPayload\\n\\nDeploymentProviderName = Annotated[\\n    str,\\n    StringConstraints(strip_whitespace=True, min_length=1, max_length=128),\\n]  # the name of the deployment provider.\\n\\nNormalizedId = Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)]\\nNormalizedStr = Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)]\\nIdLike = UUID | NormalizedId\\n\\n\\nclass DeploymentType(str, Enum):\\n    \\\"\\\"\\\"Core deployment types recognized by LFX contracts.\\n\\n    **Cross-package coupling** \u2014 langflow's ``Deployment`` database model\\n    (``langflow.services.database.models.deployment.model``) persists this\\n    enum's ``.value`` as a ``NOT NULL`` string column and deserialises it\\n    back via ``DeploymentType(value)``.  Because of this:\\n\\n    * **Never remove or rename** an existing member value \u2014 doing so will\\n      cause ``ValueError`` on every read of rows that stored that value.\\n    * Adding new members is safe and requires no migration.\\n    \\\"\\\"\\\"\\n\\n    # Adapters may carry additional provider-specific classification in `provider_data`.\\n    AGENT = \\\"agent\\\"\\n\\n\\nclass BaseFlowArtifact(BaseModel, Generic[T_FlowProviderData]):\\n    \\\"\\\"\\\"Model representing a payload for a flow.\\\"\\\"\\\"\\n\\n    model_config = ConfigDict(extra=\\\"allow\\\")  # e.g., viewport - good for viewing the flow in the UI\\n\\n    id: UUID = Field(description=\\\"Unique identifier for the flow\\\")\\n    name: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)] = Field(\\n        description=\\\"The name of the flow\\\"\\n    )\\n    description: str | None = Field(None, description=\\\"The description of the flow\\\")\\n    data: dict = Field(description=\\\"The data of the flow\\\")\\n    tags: list[str] | None = Field(None, description=\\\"The tags of the flow\\\")\\n    provider_data: T_FlowProviderData | None = Field(\\n        None,\\n        description=\\\"Provider-specific flow metadata consumed only by the active deployment adapter.\\\",\\n    )\\n\\n    @field_validator(\\\"data\\\")\\n    @classmethod\\n    def validate_data(cls, value: dict) -> dict:\\n        \\\"\\\"\\\"Validate flow payload shape.\\n\\n        Keep validation aligned with backend flow model expectations.\\n        \\\"\\\"\\\"\\n        if \\\"nodes\\\" not in value:\\n            msg = \\\"Flow must have nodes\\\"\\n            raise ValueError(msg)\\n        if \\\"edges\\\" not in value:\\n            msg = \\\"Flow must have edges\\\"\\n            raise ValueError(msg)\\n        if not isinstance(value[\\\"nodes\\\"], list):\\n            msg = \\\"Flow 'nodes' must be a list\\\"\\n            raise ValueError(msg)  # noqa: TRY004 - Pydantic validators must raise ValueError\\n        if not isinstance(value[\\\"edges\\\"], list):\\n            msg = \\\"Flow 'edges' must be a list\\\"\\n            raise ValueError(msg)  # noqa: TRY004 - Pydantic validators must raise ValueError\\n        return value\\n\\n\\nSnapshotList = Annotated[list[BaseFlowArtifact[AdapterPayload]], Field(min_length=1)]\\n\\n\\nclass SnapshotItem(BaseModel, Generic[T_SnapshotItemData]):\\n    \\\"\\\"\\\"Model representing a result for a snapshot item.\\\"\\\"\\\"\\n\\n    id: IdLike = Field(description=\\\"The id of the snapshot item\\\")\\n    name: str = Field(description=\\\"The name of the snapshot item\\\")\\n    provider_data: T_SnapshotItemData | None = Field(\\n        None,\\n        description=\\\"The data of the snapshot item from the provider\\\",\\n    )\\n\\n\\nclass SnapshotItems(BaseModel, Generic[T_FlowProviderData]):\\n    \\\"\\\"\\\"Snapshot input for deployment create.\\n\\n    Accept raw snapshot artifact payloads for deployment create.\\n    \\\"\\\"\\\"\\n\\n    model_config = ConfigDict(extra=\\\"forbid\\\")\\n\\n    raw_payloads: Annotated[list[BaseFlowArtifact[T_FlowProviderData]], Field(min_length=1)] | None = Field(\\n        None,\\n        description=\\\"List of raw snapshot payloads to create and bind for this deployment. Omit to leave unchanged.\\\",\\n    )\\n    ids: list[IdLike] | None = Field(\\n        None,\\n        description=\\\"List of existing snapshot ids to bind to the deployment. Omit to leave unchanged.\\\",\\n    )\\n\\n    @field_validator(\\\"ids\\\")\\n    @classmethod\\n    def validate_ids(cls, value: list[IdLike] | None) -> list[str] | None:\\n        if value is None:\\n            return None\\n        return _normalize_and_dedupe_id_list(value, field_name=\\\"snapshot_id\\\")\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_snapshot_source(self) -> \\\"SnapshotItems\\\":\\n        if not self.raw_payloads and not self.ids:\\n            msg = \\\"At least one of 'raw_payloads' or 'ids' must be provided and non-empty.\\\"\\n            raise ValueError(msg)\\n        return self\\n\\n\\nclass SnapshotDeploymentBindingUpdate(BaseModel, Generic[T_FlowProviderData]):\\n    \\\"\\\"\\\"Snapshot deployment binding patch payload.\\n\\n    Supports three operations: bind existing snapshots by ID, create new\\n    snapshots from raw payloads, or unbind snapshots by ID.  At least one\\n    of the three fields must be provided.\\n    \\\"\\\"\\\"\\n\\n    add_ids: list[IdLike] | None = Field(\\n        None,\\n        description=\\\"Existing snapshot ids to attach to the deployment. Omit to leave unchanged.\\\",\\n    )\\n    add_raw_payloads: Annotated[list[BaseFlowArtifact[T_FlowProviderData]], Field(min_length=1)] | None = Field(\\n        None,\\n        description=\\\"Raw snapshot payloads to create and attach to the deployment. Omit to leave unchanged.\\\",\\n    )\\n    remove_ids: list[IdLike] | None = Field(\\n        None,\\n        description=\\\"Snapshot ids to detach from the deployment. Omit to leave unchanged.\\\",\\n    )\\n\\n    @field_validator(\\\"add_ids\\\", \\\"remove_ids\\\")\\n    @classmethod\\n    def validate_id_lists(cls, v: list[IdLike] | None) -> list[str] | None:\\n        # Post-validation: values are always normalized strings (UUIDs\\n        # are stringified by _normalize_and_dedupe_id_list).  The field\\n        # annotation remains list[IdLike] so Pydantic accepts UUID input.\\n        if v is None:\\n            return None\\n        return _normalize_and_dedupe_id_list(v, field_name=\\\"snapshot_id\\\")\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_operations(self):\\n        \\\"\\\"\\\"Ensure patch contains explicit and non-conflicting operations.\\\"\\\"\\\"\\n        add_values = self.add_ids or []\\n        raw_values = self.add_raw_payloads or []\\n        remove_values = self.remove_ids or []\\n\\n        if not add_values and not raw_values and not remove_values:\\n            msg = \\\"At least one of 'add_ids', 'add_raw_payloads', or 'remove_ids' must be provided.\\\"\\n            raise ValueError(msg)\\n\\n        # Overlap check covers add_ids vs remove_ids only.\\n        # add_raw_payloads carry flow-artifact IDs (Langflow domain),\\n        # while add_ids/remove_ids carry snapshot IDs (provider domain).\\n        overlap = set(add_values).intersection(remove_values)\\n        if overlap:\\n            ids = \\\", \\\".join(sorted(overlap))\\n            msg = f\\\"Snapshot ids cannot be present in both 'add_ids' and 'remove_ids': {ids}.\\\"\\n            raise ValueError(msg)\\n\\n        return self\\n\\n\\nEnvVarKey = Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)]\\n\\n\\nclass EnvVarSource(str, Enum):\\n    RAW = \\\"raw\\\"\\n    VARIABLE = \\\"variable\\\"\\n\\n\\nclass EnvVarValueSpec(BaseModel):\\n    \\\"\\\"\\\"Environment variable resolution spec.\\\"\\\"\\\"\\n\\n    value: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)] = Field(\\n        description=\\\"Raw value or variable name, depending on the selected source.\\\"\\n    )\\n    source: EnvVarSource = Field(\\n        default=EnvVarSource.VARIABLE,\\n        description=\\\"How to interpret `value`: resolve from variable service or use raw value as-is.\\\",\\n    )\\n\\n\\nclass DeploymentConfig(BaseModel):\\n    \\\"\\\"\\\"Deployment configuration payload, including environment variables and provider-specific settings.\\\"\\\"\\\"\\n\\n    name: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)] = Field(\\n        description=\\\"The name of the config\\\"\\n    )\\n    description: str | None = Field(None, description=\\\"The description of the config\\\")\\n    environment_variables: dict[EnvVarKey, EnvVarValueSpec] | None = Field(None, description=\\\"Environment variables\\\")\\n    # the provider might have additional configuration options that are not covered here\\n    provider_config: T_DeploymentConfig | None = Field(None, description=\\\"Provider configuration\\\")\\n\\n\\nclass ConfigItem(BaseModel):\\n    \\\"\\\"\\\"Config input for deployment create.\\n\\n    Exactly one of `reference_id` or `raw_payload` must be provided.\\n    \\\"\\\"\\\"\\n\\n    reference_id: NormalizedId | None = Field(\\n        None,\\n        description=\\\"Existing config reference id to bind to the deployment.\\\",\\n    )\\n    raw_payload: DeploymentConfig | None = Field(\\n        None,\\n        description=\\\"Config payload to create and bind to the deployment.\\\",\\n    )\\n\\n    @field_validator(\\\"reference_id\\\")\\n    @classmethod\\n    def validate_reference_id(cls, v: str | None) -> str | None:\\n        if v is None:\\n            return None\\n        return _normalize_and_validate_id(v, field_name=\\\"reference_id\\\")\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_config_source(self) -> \\\"ConfigItem\\\":\\n        _validate_exactly_one_of(\\n            self,\\n            first_field=\\\"reference_id\\\",\\n            second_field=\\\"raw_payload\\\",\\n        )\\n        return self\\n\\n\\nclass ConfigDeploymentBindingUpdate(BaseModel):\\n    \\\"\\\"\\\"Config deployment binding patch payload.\\n\\n    Exactly one of ``config_id``, ``raw_payload``, or ``unbind`` must be\\n    provided:\\n\\n    * ``config_id`` \u2014 bind an existing config by reference.\\n    * ``raw_payload`` \u2014 create a new config and bind it.\\n    * ``unbind = True`` \u2014 detach the current config.\\n    \\\"\\\"\\\"\\n\\n    config_id: IdLike | None = Field(\\n        None,\\n        description=\\\"Config reference id to bind to the deployment.\\\",\\n    )\\n    raw_payload: DeploymentConfig | None = Field(\\n        None,\\n        description=\\\"Config payload to create and bind to the deployment.\\\",\\n    )\\n    unbind: bool = Field(\\n        default=False,\\n        description=\\\"Set to true to detach the current config from the deployment.\\\",\\n    )\\n\\n    @field_validator(\\\"config_id\\\")\\n    @classmethod\\n    def validate_config_id(cls, v: IdLike | None) -> IdLike | None:\\n        if isinstance(v, str):\\n            return _normalize_and_validate_id(v, field_name=\\\"config_id\\\")\\n        return v\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_config_source(self) -> \\\"ConfigDeploymentBindingUpdate\\\":\\n        provided = sum(\\n            [\\n                self.config_id is not None,\\n                self.raw_payload is not None,\\n                self.unbind,\\n            ]\\n        )\\n        if provided != 1:\\n            msg = \\\"Exactly one of 'config_id', 'raw_payload', or 'unbind=true' must be provided.\\\"\\n            raise ValueError(msg)\\n        return self\\n\\n\\nclass ConfigListItem(BaseModel, Generic[T_ConfigItemData]):\\n    \\\"\\\"\\\"Model representing a result for a config list item.\\\"\\\"\\\"\\n\\n    id: IdLike = Field(description=\\\"The id of the config item\\\")\\n    name: str = Field(description=\\\"The name of the config item\\\")\\n    created_at: datetime.datetime | None = Field(None, description=\\\"The created timestamp of the config item\\\")\\n    updated_at: datetime.datetime | None = Field(None, description=\\\"The last updated timestamp of the config item\\\")\\n    provider_data: T_ConfigItemData | None = Field(None, description=\\\"Provider-specific data for the config item\\\")\\n\\n\\nclass ProviderDataModel(BaseModel, Generic[T_ProviderData]):\\n    \\\"\\\"\\\"Base model for provider metadata payloads.\\\"\\\"\\\"\\n\\n    provider_data: T_ProviderData | None = Field(None, description=\\\"The data from the provider\\\")\\n\\n\\nclass ProviderResultModel(BaseModel, Generic[T_ProviderResult]):\\n    \\\"\\\"\\\"Base model for provider operation payloads.\\\"\\\"\\\"\\n\\n    provider_result: T_ProviderResult | None = Field(None, description=\\\"The result from the provider\\\")\\n\\n\\nclass BaseDeploymentData(BaseModel):\\n    \\\"\\\"\\\"Model representing a data for a deployment.\\\"\\\"\\\"\\n\\n    name: NormalizedStr | None = Field(None, description=\\\"Technical name of the deployment\\\")\\n    description: str = Field(\\n        default=\\\"\\\",\\n        description=\\\"The description of the deployment\\\",\\n    )\\n    type: DeploymentType = Field(description=\\\"The type of the deployment\\\")\\n\\n\\nclass DeploymentCreateResult(ProviderResultModel[T_DeploymentCreateResult]):\\n    \\\"\\\"\\\"Model representing a result for a deployment creation operation.\\\"\\\"\\\"\\n\\n    id: IdLike = Field(description=\\\"The id of the created deployment\\\")\\n    type: DeploymentType = Field(description=\\\"The type of the deployment\\\")\\n    name: NormalizedStr | None = Field(None, description=\\\"Technical name of the deployment\\\")\\n    description: str | None = Field(\\n        default=None,\\n        description=\\\"The description of the deployment\\\",\\n    )\\n\\n\\nclass DeploymentOperationResult(ProviderResultModel[T_DeploymentOperationResult]):\\n    \\\"\\\"\\\"Base model for deployment operation responses by deployment id.\\\"\\\"\\\"\\n\\n    id: IdLike = Field(description=\\\"The id of the deployment\\\")\\n\\n\\nclass DeploymentDeleteResult(DeploymentOperationResult):\\n    \\\"\\\"\\\"Model representing a result for a deployment deletion operation.\\\"\\\"\\\"\\n\\n\\nclass ItemResult(ProviderDataModel[T_DeploymentItemData]):\\n    \\\"\\\"\\\"Model representing a result for a deployment list item.\\\"\\\"\\\"\\n\\n    id: IdLike = Field(description=\\\"The id of the deployment\\\")\\n    name: NormalizedStr = Field(description=\\\"Technical name of the deployment\\\")\\n    type: DeploymentType = Field(description=\\\"The type of the deployment\\\")\\n    created_at: datetime.datetime | None = Field(None, description=\\\"The created timestamp of the deployment\\\")\\n    updated_at: datetime.datetime | None = Field(None, description=\\\"The last updated timestamp of the deployment\\\")\\n\\n\\nclass DeploymentGetResult(ItemResult):\\n    \\\"\\\"\\\"Model representing a detailed deployment payload.\\\"\\\"\\\"\\n\\n    description: str | None = Field(None, description=\\\"The description of the deployment\\\")\\n\\n\\nclass DeploymentDuplicateResult(ItemResult):\\n    \\\"\\\"\\\"Model representing the result of a deployment duplication operation.\\\"\\\"\\\"\\n\\n\\nclass DeploymentListResult(ProviderResultModel[T_DeploymentListResult]):\\n    \\\"\\\"\\\"Model representing a result for a deployment list operation.\\\"\\\"\\\"\\n\\n    deployments: list[ItemResult] = Field(description=\\\"The list of deployments\\\")\\n\\n\\nclass DeploymentListLlmsResult(ProviderResultModel[T_DeploymentLlmListResult]):\\n    \\\"\\\"\\\"Provider payload container for listing available deployment LLM metadata.\\\"\\\"\\\"\\n\\n\\nclass ConfigListResult(\\n    ProviderResultModel[T_ConfigListResult],\\n    Generic[T_ConfigListResult, T_ConfigItemData],\\n):\\n    \\\"\\\"\\\"Model representing a result for a config list operation.\\\"\\\"\\\"\\n\\n    configs: list[ConfigListItem[T_ConfigItemData]] = Field(description=\\\"The list of configs\\\")\\n\\n\\nclass SnapshotListResult(\\n    ProviderResultModel[T_SnapshotListResult],\\n    Generic[T_SnapshotListResult, T_SnapshotItemData],\\n):\\n    \\\"\\\"\\\"Model representing a result for a snapshot list operation.\\\"\\\"\\\"\\n\\n    snapshots: list[SnapshotItem[T_SnapshotItemData]] = Field(description=\\\"The list of snapshots\\\")\\n\\n\\nclass SnapshotUpdateResult(ProviderResultModel[T_SnapshotUpdateResult]):\\n    \\\"\\\"\\\"Model representing a result for a snapshot update operation.\\\"\\\"\\\"\\n\\n    snapshot_id: str = Field(description=\\\"The provider-owned snapshot identifier\\\")\\n\\n\\nclass _BaseListParams(BaseModel, Generic[T_ListParamsPayload]):\\n    \\\"\\\"\\\"Shared list-filter fields.\\\"\\\"\\\"\\n\\n    provider_params: T_ListParamsPayload | None = Field(\\n        None,\\n        description=\\\"Provider-specific query params to filter by.\\\",\\n    )\\n    deployment_ids: list[IdLike] | None = Field(\\n        None,\\n        description=\\\"Deployment ids to filter by.\\\",\\n    )\\n\\n    @staticmethod\\n    def _normalize_filter_id_values(value: list[IdLike] | None, *, field_name: str) -> list[str] | None:\\n        if value is None:\\n            return None\\n        normalized_ids = _normalize_and_validate_id_list(\\n            [str(item) for item in value],\\n            field_name=field_name,\\n        )\\n        # Keep first occurrence order while removing duplicates.\\n        return list(dict.fromkeys(normalized_ids))\\n\\n    @field_validator(\\\"deployment_ids\\\")\\n    @classmethod\\n    def validate_filter_ids(cls, value: list[IdLike] | None, info) -> list[str] | None:\\n        return cls._normalize_filter_id_values(value, field_name=info.field_name)\\n\\n\\nclass DeploymentListParams(_BaseListParams[T_DeploymentListParams]):\\n    \\\"\\\"\\\"Query params for deployment list operations.\\\"\\\"\\\"\\n\\n    deployment_types: list[DeploymentType] | None = Field(\\n        None,\\n        description=\\\"Deployment types to filter by.\\\",\\n    )\\n    snapshot_ids: list[IdLike] | None = Field(\\n        None,\\n        description=\\\"Snapshot ids to filter by.\\\",\\n    )\\n    config_ids: list[IdLike] | None = Field(\\n        None,\\n        description=\\\"Config ids to filter by.\\\",\\n    )\\n\\n    @field_validator(\\\"deployment_types\\\")\\n    @classmethod\\n    def validate_deployment_types(cls, value: list[DeploymentType] | None) -> list[DeploymentType] | None:\\n        if value is None:\\n            return None\\n        # Keep first occurrence order while removing duplicates.\\n        return list(dict.fromkeys(value))\\n\\n    @field_validator(\\\"snapshot_ids\\\", \\\"config_ids\\\")\\n    @classmethod\\n    def validate_entity_filter_ids(cls, value: list[IdLike] | None, info) -> list[str] | None:\\n        return cls._normalize_filter_id_values(value, field_name=info.field_name)\\n\\n\\nclass ConfigListParams(_BaseListParams[T_ConfigListParams]):\\n    \\\"\\\"\\\"Query params for config list operations.\\\"\\\"\\\"\\n\\n    config_ids: list[IdLike] | None = Field(\\n        None,\\n        description=\\\"Config ids to filter by.\\\",\\n    )\\n\\n    @field_validator(\\\"config_ids\\\")\\n    @classmethod\\n    def validate_config_ids(cls, value: list[IdLike] | None, info) -> list[str] | None:\\n        return cls._normalize_filter_id_values(value, field_name=info.field_name)\\n\\n\\nclass SnapshotListParams(_BaseListParams[T_SnapshotListParams]):\\n    \\\"\\\"\\\"Query params for snapshot list operations.\\\"\\\"\\\"\\n\\n    snapshot_ids: list[IdLike] | None = Field(\\n        None,\\n        description=\\\"Snapshot ids to filter by.\\\",\\n    )\\n\\n    @field_validator(\\\"snapshot_ids\\\")\\n    @classmethod\\n    def validate_snapshot_ids(cls, value: list[IdLike] | None, info) -> list[str] | None:\\n        return cls._normalize_filter_id_values(value, field_name=info.field_name)\\n\\n\\nclass DeploymentCreate(BaseModel):\\n    \\\"\\\"\\\"Deployment create payload.\\\"\\\"\\\"\\n\\n    spec: BaseDeploymentData = Field(description=\\\"The base metadata of the deployment\\\")\\n    snapshot: SnapshotItems | None = Field(None, description=\\\"The snapshots of the deployment\\\")\\n    config: ConfigItem | None = Field(None, description=\\\"The config of the deployment\\\")\\n    provider_data: T_DeploymentCreate | None = Field(\\n        None,\\n        description=\\\"Provider-specific opaque payload for deployment create operations.\\\",\\n    )\\n\\n\\n@lru_cache(maxsize=1)\\ndef get_deployment_create_schema() -> str:\\n    \\\"\\\"\\\"Return serialized JSON schema for deployment create payload.\\\"\\\"\\\"\\n    return json.dumps(DeploymentCreate.model_json_schema(), indent=2)\\n\\n\\nclass BaseDeploymentDataUpdate(BaseModel):\\n    \\\"\\\"\\\"Deployment base update payload.\\\"\\\"\\\"\\n\\n    name: NormalizedStr | None = Field(None, description=\\\"Technical name of the deployment\\\")\\n    description: str | None = Field(\\n        None,\\n        description=\\\"The description of the deployment\\\",\\n    )\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_has_changes(self) -> \\\"BaseDeploymentDataUpdate\\\":\\n        if \\\"name\\\" in self.model_fields_set and self.name is None:\\n            msg = \\\"'name' cannot be set to null.\\\"\\n            raise ValueError(msg)\\n        if \\\"description\\\" not in self.model_fields_set and self.name is None:\\n            msg = \\\"At least one of 'name' or 'description' must be provided.\\\"\\n            raise ValueError(msg)\\n        return self\\n\\n\\nclass DeploymentUpdate(BaseModel):\\n    \\\"\\\"\\\"Deployment update payload.\\\"\\\"\\\"\\n\\n    spec: BaseDeploymentDataUpdate | None = Field(None, description=\\\"The metadata of the deployment\\\")\\n    snapshot: SnapshotDeploymentBindingUpdate | None = Field(None, description=\\\"The snapshot of the deployment\\\")\\n    config: ConfigDeploymentBindingUpdate | None = Field(None, description=\\\"The config of the deployment\\\")\\n    provider_data: T_DeploymentUpdate | None = Field(\\n        None,\\n        description=\\\"Provider-specific opaque payload for deployment update operations.\\\",\\n    )\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_has_changes(self) -> \\\"DeploymentUpdate\\\":\\n        if not self.model_fields_set:\\n            msg = \\\"At least one of 'spec', 'snapshot', 'config', or 'provider_data' must be provided.\\\"\\n            raise ValueError(msg)\\n        if self.spec is None and self.snapshot is None and self.config is None and self.provider_data is None:\\n            msg = \\\"At least one of 'spec', 'snapshot', 'config', or 'provider_data' must be provided.\\\"\\n            raise ValueError(msg)\\n        return self\\n\\n\\nclass DeploymentUpdateResult(DeploymentOperationResult[T_DeploymentUpdateResult]):\\n    \\\"\\\"\\\"Model representing a result for a deployment update operation.\\\"\\\"\\\"\\n\\n\\nclass RedeployResult(DeploymentOperationResult):\\n    \\\"\\\"\\\"Model representing a deployment redeployment operation result.\\\"\\\"\\\"\\n\\n\\nclass DeploymentStatusResult(ProviderDataModel[T_DeploymentStatusData]):\\n    \\\"\\\"\\\"Model representing a deployment status response.\\n\\n    Inherits ``provider_data`` from ``ProviderDataModel`` to carry\\n    provider-reported health information.\\n    \\\"\\\"\\\"\\n\\n    id: IdLike = Field(description=\\\"The id of the deployment\\\")\\n\\n\\nclass ExecutionCreate(BaseModel):\\n    \\\"\\\"\\\"Provider-agnostic deployment execution payload.\\\"\\\"\\\"\\n\\n    deployment_id: IdLike = Field(description=\\\"The id of the deployment to create an execution for.\\\")\\n    deployment_type: DeploymentType | None = Field(\\n        default=None,\\n        description=\\\"Optional deployment type routing hint for execution creation.\\\",\\n    )\\n\\n    provider_data: T_ExecutionInput | None = Field(\\n        None,\\n        description=\\\"Provider-specific execution data.\\\",\\n    )\\n\\n    @field_validator(\\\"deployment_id\\\")\\n    @classmethod\\n    def validate_deployment_id(cls, value: IdLike) -> IdLike:\\n        if isinstance(value, str):\\n            return _normalize_and_validate_id(value, field_name=\\\"deployment_id\\\")\\n        return value\\n\\n\\nclass ExecutionResultBase(ProviderResultModel[T_ExecutionResult]):\\n    \\\"\\\"\\\"Base model for deployment execution responses.\\\"\\\"\\\"\\n\\n    execution_id: str | None = Field(\\n        default=None,\\n        description=\\\"Opaque execution identifier for status polling.\\\",\\n    )\\n    deployment_id: IdLike = Field(description=\\\"The id of the deployment that was executed.\\\")\\n\\n\\nclass ExecutionCreateResult(ExecutionResultBase[T_ExecutionCreateResult]):\\n    \\\"\\\"\\\"Result returned when an execution is created.\\n\\n    This model intentionally remains distinct from ``ExecutionStatusResult`` even\\n    though both currently share the same shape. Callers should not mix the two\\n    response types: create responses and status responses represent different API\\n    stages and may diverge as the contract evolves.\\n    \\\"\\\"\\\"\\n\\n\\nclass ExecutionStatusResult(ExecutionResultBase[T_ExecutionStatusResult]):\\n    \\\"\\\"\\\"Result returned when querying an execution status.\\n\\n    This model intentionally remains distinct from ``ExecutionCreateResult`` even\\n    though both currently share the same shape. Callers should not mix the two\\n    response types: create responses and status responses represent different API\\n    stages and may diverge as the contract evolves.\\n    \\\"\\\"\\\"\\n\\n\\nclass VerifyCredentials(BaseModel, Generic[T_VerifyCredentials]):\\n    \\\"\\\"\\\"Provider-agnostic input for credential verification.\\n\\n    ``base_url`` is the only provider-agnostic field; actual credentials\\n    (API keys, access-key pairs, client secrets, etc.) are carried in\\n    ``provider_data`` because different providers use fundamentally different\\n    credential shapes.  Each adapter defines its own credential model via the\\n    ``T_VerifyCredentials`` type parameter, and the mapper is responsible for\\n    packing the appropriate credentials into ``provider_data``.\\n    \\\"\\\"\\\"\\n\\n    base_url: str = Field(description=\\\"Provider service URL to verify against.\\\")\\n    provider_data: T_VerifyCredentials | None = Field(\\n        None,\\n        description=\\\"Provider-specific credential payload.\\\",\\n    )\\n\\n\\nclass VerifyCredentialsResult(BaseModel, Generic[T_VerifyCredentialsResult]):\\n    \\\"\\\"\\\"Provider-agnostic result from credential verification.\\\"\\\"\\\"\\n\\n    provider_result: T_VerifyCredentialsResult | None = Field(\\n        None,\\n        description=\\\"Provider-specific result payload.\\\",\\n    )\\n\\n\\nclass DeploymentListTypesResult(ProviderResultModel[AdapterPayload]):\\n    \\\"\\\"\\\"Model representing deployment types listing response.\\\"\\\"\\\"\\n\\n    deployment_types: list[DeploymentType] = Field(description=\\\"Supported deployment types.\\\")\\n\\n\\ndef _normalize_and_validate_id(value: str, *, field_name: str) -> str:\\n    \\\"\\\"\\\"Normalize identifier values and reject blank strings.\\\"\\\"\\\"\\n    normalized = value.strip()\\n    if not normalized:\\n        msg = f\\\"'{field_name}' must not be empty or whitespace.\\\"\\n        raise ValueError(msg)\\n    return normalized\\n\\n\\ndef _normalize_and_validate_id_list(values: list[str], *, field_name: str) -> list[str]:\\n    \\\"\\\"\\\"Normalize identifier lists and reject blank entries.\\\"\\\"\\\"\\n    return [_normalize_and_validate_id(value, field_name=field_name) for value in values]\\n\\n\\ndef _normalize_and_dedupe_id_list(values: list[IdLike], *, field_name: str) -> list[str]:\\n    \\\"\\\"\\\"Normalize identifier lists and remove duplicates while preserving order.\\\"\\\"\\\"\\n    normalized_values = _normalize_and_validate_id_list(\\n        [str(value) for value in values],\\n        field_name=field_name,\\n    )\\n    return list(dict.fromkeys(normalized_values))\\n\\n\\ndef _validate_exactly_one_of(\\n    model: BaseModel,\\n    *,\\n    first_field: str,\\n    second_field: str,\\n) -> None:\\n    \\\"\\\"\\\"Ensure exactly one of two model fields is provided.\\\"\\\"\\\"\\n    has_first = getattr(model, first_field) is not None\\n    has_second = getattr(model, second_field) is not None\\n\\n    if has_first == has_second:\\n        msg = f\\\"Exactly one of '{first_field}' or '{second_field}' must be provided.\\\"\\n        raise ValueError(msg)\\n\\n\\ndef get_str_id(v: IdLike) -> str:\\n    return str(v) if isinstance(v, UUID) else v\\n\\n\\ndef get_uuid(v: UUID | str) -> UUID:\\n    \\\"\\\"\\\"Return a UUID from a UUID object or UUID-formatted string.\\n\\n    This helper is intentionally strict: opaque deployment identifiers like\\n    ``dep_1`` are valid ``IdLike`` values, but are not valid UUIDs.\\n    Use ``get_str_id`` when callers need to preserve opaque ids.\\n    \\\"\\\"\\\"\\n    if isinstance(v, str):\\n        try:\\n            return UUID(v)\\n        except ValueError as exc:\\n            msg = f\\\"Cannot convert identifier '{v}' to UUID. Use get_str_id() for opaque IDs.\\\"\\n            raise ValueError(msg) from exc\\n    return v\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/adapters/deployment/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"806377638958de742d08f01e60152bf26d3a9cac5ceb3c3c16591d4983803c6f\",\"content\":\"# ruff: noqa: ARG002\\n\\\"\\\"\\\"Default (no-op) deployment service implementation.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.adapters.deployment.base import BaseDeploymentService\\nfrom lfx.services.adapters.deployment.exceptions import DeploymentNotConfiguredError\\n\\nif TYPE_CHECKING:\\n    from sqlalchemy.ext.asyncio import AsyncSession\\n\\n    from lfx.services.adapters.deployment.schema import (\\n        ConfigListParams,\\n        ConfigListResult,\\n        DeploymentCreate,\\n        DeploymentCreateResult,\\n        DeploymentDeleteResult,\\n        DeploymentDuplicateResult,\\n        DeploymentGetResult,\\n        DeploymentListLlmsResult,\\n        DeploymentListParams,\\n        DeploymentListResult,\\n        DeploymentListTypesResult,\\n        DeploymentStatusResult,\\n        DeploymentType,\\n        DeploymentUpdate,\\n        DeploymentUpdateResult,\\n        ExecutionCreate,\\n        ExecutionCreateResult,\\n        ExecutionStatusResult,\\n        IdLike,\\n        RedeployResult,\\n        SnapshotListParams,\\n        SnapshotListResult,\\n        VerifyCredentials,\\n        VerifyCredentialsResult,\\n    )\\n\\n\\n# No adapter key registered -- this stub exists so the protocol and ABC are\\n# testable.  Concrete adapters (e.g. in Langflow) subclass BaseDeploymentService\\n# and register under meaningful keys like \\\"local\\\" or \\\"remote\\\".\\nclass DeploymentService(BaseDeploymentService):\\n    \\\"\\\"\\\"Null deployment service for LFX.\\n\\n    All operations raise :class:`DeploymentNotConfiguredError` because LFX does\\n    not ship a deployment adapter.  Concrete adapters (e.g. in Langflow) should\\n    subclass :class:`BaseDeploymentService` to provide real behaviour.\\n    \\\"\\\"\\\"\\n\\n    name = \\\"deployment_service\\\"\\n\\n    async def create(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        payload: DeploymentCreate,\\n        db: AsyncSession,\\n    ) -> DeploymentCreateResult:\\n        \\\"\\\"\\\"Create a new deployment in the provider.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"create\\\")\\n\\n    async def list_types(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        db: AsyncSession,\\n    ) -> DeploymentListTypesResult:\\n        \\\"\\\"\\\"List deployment types supported by the provider.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"list_types\\\")\\n\\n    async def list_llms(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        db: AsyncSession,\\n    ) -> DeploymentListLlmsResult:\\n        \\\"\\\"\\\"List provider-available LLM model names for deployment configuration.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"list_llms\\\")\\n\\n    async def list(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        params: DeploymentListParams | None = None,\\n        db: AsyncSession,\\n    ) -> DeploymentListResult:\\n        \\\"\\\"\\\"List deployments visible to this adapter.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"list\\\")\\n\\n    async def get(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> DeploymentGetResult:\\n        \\\"\\\"\\\"Return deployment metadata by provider ID.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"get\\\")\\n\\n    async def update(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        payload: DeploymentUpdate,\\n        db: AsyncSession,\\n    ) -> DeploymentUpdateResult:\\n        \\\"\\\"\\\"Update deployment inputs and apply changes in the provider.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"update\\\")\\n\\n    async def redeploy(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> RedeployResult:\\n        \\\"\\\"\\\"Re-apply current deployment inputs without changing them.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"redeploy\\\")\\n\\n    async def duplicate(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> DeploymentDuplicateResult:\\n        \\\"\\\"\\\"Create a new deployment using the same inputs as the source.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"duplicate\\\")\\n\\n    async def delete(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> DeploymentDeleteResult:\\n        \\\"\\\"\\\"Delete the deployment from the provider.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"delete\\\")\\n\\n    async def get_status(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        deployment_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> DeploymentStatusResult:\\n        \\\"\\\"\\\"Return provider-reported health/status for the deployment.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"get_status\\\")\\n\\n    async def create_execution(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        payload: ExecutionCreate,\\n        db: AsyncSession,\\n    ) -> ExecutionCreateResult:\\n        \\\"\\\"\\\"Run a provider-agnostic deployment execution.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"create_execution\\\")\\n\\n    async def get_execution(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        execution_id: IdLike,\\n        deployment_type: DeploymentType | None = None,\\n        db: AsyncSession,\\n    ) -> ExecutionStatusResult:\\n        \\\"\\\"\\\"Get provider-agnostic deployment execution state/output.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"get_execution\\\")\\n\\n    async def list_configs(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        params: ConfigListParams | None = None,\\n        db: AsyncSession,\\n    ) -> ConfigListResult:\\n        \\\"\\\"\\\"List configs visible to this adapter.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"list_configs\\\")\\n\\n    async def list_snapshots(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        params: SnapshotListParams | None = None,\\n        db: AsyncSession,\\n    ) -> SnapshotListResult:\\n        \\\"\\\"\\\"List snapshots visible to this adapter.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"list_snapshots\\\")\\n\\n    async def verify_credentials(\\n        self,\\n        *,\\n        user_id: IdLike,\\n        payload: VerifyCredentials,\\n    ) -> VerifyCredentialsResult:\\n        \\\"\\\"\\\"Verify provider credentials before account creation.\\\"\\\"\\\"\\n        raise DeploymentNotConfiguredError(method=\\\"verify_credentials\\\")\\n\\n    async def teardown(self) -> None:\\n        logger.debug(\\\"Deployment service teardown\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/adapters/payload.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a4e84e841a4c1bf57a1334dbe5f7b3730291419c78c2ced59e2e515574fe1abb\",\"content\":\"\\\"\\\"\\\"Shared payload contracts and schema registry primitives.\\n\\nOwnership boundaries start here:\\n\\n- ``PayloadSlot`` is a generic parse/dump contract and is layer-agnostic.\\n  Both adapter-side and API-side registries use the same slot primitive.\\n- ``ProviderPayloadSchemas`` is a structural base for named slot registries.\\n  It owns introspection helpers only (``slots`` / ``active_slots``), not\\n  any adapter- or API-specific slot names.\\n- Concrete ``*PayloadFields`` classes (for example deployment payload fields)\\n  define canonical slot names in lfx so both layers share one structure.\\n- Adapter integrations populate adapter-side registries in lfx\\n  (``*PayloadSchemas`` subclasses).\\n- Langflow integrations populate API-side registries in Langflow\\n  (for example ``DeploymentApiPayloads``), including Langflow-specific\\n  validation/reshaping decisions.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import dataclass, fields\\nfrom enum import Enum\\nfrom typing import Any, Generic\\n\\nfrom pydantic import BaseModel, ValidationError\\nfrom typing_extensions import TypeVar\\n\\nAdapterPayload = dict[str, Any]\\nT_Model = TypeVar(\\\"T_Model\\\", bound=BaseModel)\\n\\n\\nclass PayloadSlotPolicy(str, Enum):\\n    \\\"\\\"\\\"Controls how a slot applies schema validation.\\\"\\\"\\\"\\n\\n    VALIDATE_ONLY = \\\"validate_only\\\"\\n    VALIDATE_AND_DUMP = \\\"validate_and_dump\\\"\\n\\n\\nclass AdapterPayloadValidationError(ValueError):\\n    \\\"\\\"\\\"Raised when a payload fails adapter schema validation.\\\"\\\"\\\"\\n\\n    def __init__(self, *, model_name: str, error: ValidationError) -> None:\\n        self.model_name = model_name\\n        self.error = error\\n        # Keep public exception text sanitized to avoid leaking raw payload\\n        # fragments from ValidationError.__str__() into logs/responses.\\n        super().__init__(f\\\"Invalid payload for '{model_name}'.\\\")\\n\\n    def format_first_error(self) -> str:\\n        \\\"\\\"\\\"Return a sanitized first validation error message.\\n\\n        Missing-field errors keep explicit field names for UX.\\n        Model-level ``value_error`` messages (from model validators) are\\n        passed through after stripping the pydantic \\\"Value error, \\\" prefix,\\n        since those contain intentional business-logic messages.\\n        All other errors avoid echoing raw validator text.\\n        \\\"\\\"\\\"\\n        errors = self.error.errors()\\n        if not errors:\\n            return \\\"Invalid payload.\\\"\\n\\n        first_error = errors[0]\\n        loc = first_error.get(\\\"loc\\\") or ()\\n        loc_path = \\\".\\\".join(str(part) for part in loc if part != \\\"__root__\\\")\\n\\n        error_type = first_error.get(\\\"type\\\")\\n\\n        if error_type == \\\"missing\\\" and loc_path:\\n            return f\\\"Missing required field '{loc_path}'.\\\"\\n        if error_type in {\\\"extra_forbidden\\\", \\\"unexpected_keyword_argument\\\"} and loc_path:\\n            return f\\\"Invalid field '{loc_path}'. Please remove it.\\\"\\n        if loc_path:\\n            return f\\\"Invalid value for field '{loc_path}'.\\\"\\n        # Model-level validator errors (empty loc) contain intentional\\n        # business-logic messages; expose them after stripping the\\n        # pydantic \\\"Value error, \\\" prefix.\\n        if first_error.get(\\\"type\\\") == \\\"value_error\\\":\\n            msg = first_error.get(\\\"msg\\\", \\\"\\\")\\n            clean = msg.removeprefix(\\\"Value error, \\\")\\n            if clean:\\n                return clean\\n        return \\\"Invalid payload.\\\"\\n\\n\\nclass AdapterPayloadMissingError(ValueError):\\n    \\\"\\\"\\\"Raised when a required payload is missing.\\\"\\\"\\\"\\n\\n    def __init__(self, *, model_name: str) -> None:\\n        self.model_name = model_name\\n        super().__init__(f\\\"Missing payload for '{model_name}'.\\\")\\n\\n\\n@dataclass(frozen=True)\\nclass PayloadSlot(Gener";
